INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B2', 'Xà phòng và chất giặt rửa', 16, 2, $JSON$
{
  "content": [
    "# BÀI 2 XÀ PHÒNG VÀ CHẤT GIẶT RỬA",
    "",
    "**MỤC TIÊU**",
    "– Nêu được khái niệm, đặc điểm về cấu tạo và tính chất chất giặt rửa của xà phòng và chất giặt rửa tự nhiên, tổng hợp.",
    "– Trình bày được một số phương pháp sản xuất xà phòng, phương pháp chủ yếu sản xuất chất giặt rửa tổng hợp.",
    "– Thực hiện được (hoặc quan sát video) thí nghiệm về phản ứng xà phòng hoá chất béo.",
    "– Trình bày được cách sử dụng hợp lí, an toàn xà phòng và chất giặt rửa tổng hợp trong đời sống.",
    "",
    "❓ Tại sao xà phòng và chất giặt rửa có thể loại bỏ các vết bẩn trên quần áo, dầu mỡ ở chén bát.",
    "",
    "## I KHÁI NIỆM, ĐẶC ĐIỂM CẤU TẠO CỦA XÀ PHÒNG VÀ CHẤT GIẶT RỬA",
    "*Xà phòng* là hỗn hợp muối sodium hoặc potassium của các acid béo và các chất phụ gia. Thành phần chủ yếu của xà phòng thường là muối sodium của palmitic acid hoặc stearic acid.",
    "",
    "*Chất giặt rửa tổng hợp* là các chất được tổng hợp hoá học, có tác dụng giặt rửa như xà phòng nhưng không phải là muối sodium, potassium của các acid béo. Những chất này thường là muối sodium alkylsulfate hoặc alkylbenzene sulfonate.",
    "",
    "Ngoài ra, một số sản phẩm từ thiên nhiên cũng có tác dụng giặt rửa như nước quả bồ kết, quả bồ hòn,... (chất giặt rửa tự nhiên).",
    "",
    "Cấu tạo của xà phòng và chất giặt rửa phổ biến thường gồm hai phần:",
    "*Phần phân cực* (“đầu” ưa nước): là nhóm carboxylate (xà phòng) hoặc nhóm sulfate, sulfonate (chất giặt rửa tổng hợp). Phần này có thể hoà tan được trong nước.",
    "*Phần không phân cực* (“đuôi” kị nước): là gốc hydrocarbon có mạch dài (R). Phần này không tan trong nước.",
    "",
    "Xà phòng",
    "[Hình ảnh minh hoạ phân tử xà phòng: Phần không phân cực (kị nước) R- nối với Phần phân cực (ưa nước) -COO⁻Na⁺]",
    "",
    "Chất giặt rửa tổng hợp",
    "[Hình ảnh minh hoạ phân tử chất giặt rửa tổng hợp 1: Phần không phân cực (kị nước) R- nối với Phần phân cực (ưa nước) -SO3⁻Na⁺]",
    "[Hình ảnh minh hoạ phân tử chất giặt rửa tổng hợp 2: Phần không phân cực (kị nước) R-O- nối với Phần phân cực (ưa nước) -SO3⁻Na⁺]",
    "",
    "**Hình 2.1.** Cấu tạo chung của xà phòng và chất giặt rửa tổng hợp phổ biến",
    "",
    "14",
    "Dưới đây là ví dụ về cấu tạo của xà phòng và chất giặt rửa:",
    "[Hình 2.2: Công thức cấu tạo của một số chất hoạt động bề mặt]",
    "(a) Xà phòng (phần đuôi dài zic-zac kị nước nối với đầu COO⁻Na⁺ ưa nước)",
    "(b) Chất giặt rửa phổ biến (phần đuôi dài zic-zac có vòng benzene kị nước nối với đầu SO3⁻Na⁺ ưa nước)",
    "",
    "❓ ",
    "1. Em hãy nêu sự giống và khác nhau về cấu tạo giữa xà phòng và chất giặt rửa tổng hợp.",
    "2. Trong các chất sau, chất nào là xà phòng, chất nào là chất giặt rửa tổng hợp? Xác định đầu ưa nước và đuôi kị nước của các chất này.",
    "   a) CH$_3$[CH$_2$]$_{14}$COONa;        b) CH$_3$[CH$_2$]$_{10}$CH$_2$OSO$_3$Na.",
    "",
    "## II TÍNH CHẤT GIẶT RỬA",
    "Khi xà phòng, chất giặt rửa tan vào nước sẽ tạo dung dịch có sức căng bề mặt nhỏ làm cho vật cần giặt rửa dễ thấm ướt. Đuôi kị nước trong xà phòng và chất giặt rửa thâm nhập vào vết bẩn (Hình 2.3b), phân chia vết bẩn thành những hạt rất nhỏ có đầu ưa nước quay ra ngoài (Hình 2.3c), các hạt này phân tán vào nước và bị rửa trôi (Hình 2.3d).",
    "",
    "[Hình 2.3. Tính chất giặt rửa]",
    "(a) Vật liệu có vết bẩn dầu mỡ, phân tử chất giặt rửa tiến lại gần (Đầu ưa nước hướng ra, Đuôi kị nước hướng vào).",
    "(b) Đuôi kị nước thâm nhập vào vết bẩn.",
    "(c) Vết bẩn bị phân chia thành hạt nhỏ.",
    "(d) Vết bẩn bị rửa trôi.",
    "",
    "## III PHƯƠNG PHÁP SẢN XUẤT XÀ PHÒNG VÀ CHẤT GIẶT RỬA",
    "### 1. Phương pháp sản xuất xà phòng",
    "Xà phòng được sản xuất bằng cách đun chất béo với dung dịch NaOH đặc hoặc KOH đặc (phản ứng xà phòng hoá):",
    "Chất béo + NaOH/KOH (đặc) $\\xrightarrow{\\text{t}^\\circ}$ Glycerol + Muối sodium/potassium của acid béo (Thành phần chính của xà phòng)",
    "",
    "15",
    "*Ví dụ:*",
    "H$_2$C–O–C(=O)–C$_{17}$H$_{35}$",
    "|",
    "HC–O–C(=O)–C$_{17}$H$_{35}$ + 3NaOH $\\xrightarrow{\\text{t}^\\circ}$ ",
    "|",
    "H$_2$C–O–C(=O)–C$_{17}$H$_{35}$",
    "(chất béo)",
    "",
    "H$_2$C–OH",
    "|",
    "HC–OH + 3C$_{17}$H$_{35}$COO$^-$Na$^+$",
    "|",
    "H$_2$C–OH",
    "(glycerol) (sodium stearate - xà phòng)",
    "",
    "Các muối của acid béo tách ra được đem trộn với chất diệt khuẩn, chất tạo hương,... rồi ép thành bánh với nhiều hình dạng khác nhau.",
    "Xà phòng còn được sản xuất từ dầu mỏ theo sơ đồ sau:",
    "Alkane (lấy từ dầu mỏ) $\\longrightarrow$ Acid béo $\\longrightarrow$ Muối sodium/potassium của acid béo",
    "",
    "**Thí nghiệm: Phản ứng xà phòng hoá chất béo**",
    "*Chuẩn bị:*",
    "Hoá chất: chất béo (dầu thực vật hoặc mỡ động vật), dung dịch NaOH 40%, dung dịch NaCl bão hoà.",
    "Dụng cụ: bát sứ, cốc thuỷ tinh, đũa thuỷ tinh, kiềng sắt, đèn cồn.",
    "*Tiến hành:*",
    "– Cho khoảng 2 g chất béo và khoảng 4 mL dung dịch NaOH 40% vào bát sứ. Đun hỗn hợp trong khoảng 10 phút và liên tục khuấy bằng đũa thuỷ tinh. Nếu thể tích nước giảm cần bổ sung thêm nước.",
    "– Kết thúc phản ứng, đổ hỗn hợp vào cốc thuỷ tinh chứa khoảng 30 mL dung dịch NaCl bão hoà, khuấy nhẹ. Để nguội hỗn hợp, tách lấy khối xà phòng nổi lên ở trên.",
    "*Quan sát hiện tượng xảy ra và thực hiện các yêu cầu sau:*",
    "1. Tại sao phải khuấy liên tục hỗn hợp phản ứng?",
    "2. Giải thích hiện tượng xảy ra trong thí nghiệm.",
    "",
    "❓ ",
    "3. Viết phương trình phản ứng xà phòng hoá chất béo tripalmitin (tạo thành từ glycerol và palmitic acid).",
    "",
    "### 2. Phương pháp sản xuất chất giặt rửa tổng hợp",
    "Chất giặt rửa tổng hợp được sản xuất từ dầu mỏ theo sơ đồ sau:",
    "Dầu mỏ $\\xrightarrow{(*)}$ R–SO$_3$H / R–OSO$_3$H $\\longrightarrow$ R–SO$_3$Na / R–OSO$_3$Na",
    "Muối sulfonate hoặc muối sulfate được trộn với một số chất phụ gia khác nhau để tạo thành chất giặt rửa tổng hợp.",
    "",
    "(*) Quá trình có thể diễn ra qua nhiều giai đoạn.",
    "",
    "16",
    "💡 **EM CÓ BIẾT**",
    "Bột giặt tổng hợp có thành phần chính gồm: chất tạo hạt bột giặt, chất giặt rửa tổng hợp, chất tẩy trắng, enzyme. Ngoài ra, chúng còn có thêm chất chống lắng đọng, chất điều chỉnh bọt, chất tạo huỳnh quang, chất tạo hương, chất độn,...",
    "",
    "## IV ỨNG DỤNG CỦA XÀ PHÒNG VÀ CHẤT GIẶT RỬA",
    "Xà phòng được sử dụng để tắm, rửa tay,... Chất giặt rửa tổng hợp được sử dụng để giặt quần áo, rửa chén bát, rửa tay, lau sàn,...",
    "Hiện nay, chất giặt rửa tổng hợp được sử dụng phổ biến là do: chất giặt rửa dễ hoà tan trong nước hơn xà phòng; chất giặt rửa có thể sử dụng với nước cứng và môi trường acid, ngược lại xà phòng kém tác dụng trong môi trường này.",
    "Nhược điểm của chất giặt rửa tổng hợp so với xà phòng là một số chất giặt rửa tổng hợp khó phân huỷ sinh học nên kém thân thiện với môi trường.",
    "",
    "**EM ĐÃ HỌC**",
    "- Xà phòng là hỗn hợp muối sodium hoặc potassium của các acid béo và các chất phụ gia.",
    "- Chất giặt rửa tổng hợp là các chất được tổng hợp hoá học, có tác dụng giặt rửa như xà phòng nhưng không phải là muối sodium, potassium của các acid béo. Những chất này thường là muối sodium alkylsulfate hoặc alkylbenzene sulfonate.",
    "- Một số sản phẩm từ thiên nhiên có tác dụng giặt rửa như nước quả bồ kết, quả bồ hòn,...",
    "- Cấu tạo của xà phòng và chất giặt rửa phổ biến thường gồm hai phần: đầu ưa nước và đuôi kị nước.",
    "- Xà phòng được sản xuất bằng phản ứng thuỷ phân chất béo trong môi trường kiềm hoặc sản xuất từ dầu mỏ.",
    "- Chất giặt rửa tổng hợp được sản xuất từ dầu mỏ.",
    "- Xà phòng được dùng để tắm, rửa tay,... Chất giặt rửa được sử dụng để giặt quần áo, rửa tay, rửa chén bát, nước lau kính, lau sàn,...",
    "",
    "**EM CÓ THỂ**",
    "- Biết được đặc điểm cấu tạo, tính chất, các ưu, nhược điểm của xà phòng và chất giặt rửa để lựa chọn và sử dụng chúng hợp lí, an toàn trong đời sống.",
    "",
    "17"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B3', 'Ôn tập chương 1', 20, 3, $JSON$
{
  "content": [
    "# BÀI 3 ÔN TẬP CHƯƠNG 1",
    "",
    "## I HỆ THỐNG HOÁ KIẾN THỨC",
    "",
    "**ESTER**",
    "- **Công thức tổng quát:** Ester đơn chức R–C(=O)–O–R'",
    "- **Tính chất hoá học:**",
    "  - Phản ứng thuỷ phân trong môi trường acid thường là phản ứng thuận nghịch: RCOOR' + H$_2$O $\\rightleftharpoons$ RCOOH + R'OH (H$^+$, t$^\\circ$)",
    "  - Phản ứng thuỷ phân trong môi trường base: RCOOR' + NaOH $\\xrightarrow{\\text{t}^\\circ}$ RCOONa + R'OH",
    "- **Điều chế:** RCOOH + R'OH $\\rightleftharpoons$ RCOOR' + H$_2$O (H$_2$SO$_4$ đặc, t$^\\circ$)",
    "",
    "**CHẤT BÉO**",
    "- **Công thức tổng quát:**",
    "  H$_2$C–O–C(=O)–R$^1$",
    "  |",
    "  HC–O–C(=O)–R$^2$",
    "  |",
    "  H$_2$C–O–C(=O)–R$^3$",
    "  (3 gốc acid béo giống hoặc khác nhau)",
    "- **Tính chất hoá học:**",
    "  - Phản ứng xà phòng hoá (chuyển sang phần Xà phòng)",
    "  - Phản ứng hydrogen hoá: chất béo chứa gốc acid không no (dạng lỏng) $\\xrightarrow{+\\text{H}_2, \\text{t}^\\circ, \\text{xt}}$ chất béo chứa gốc acid no (dạng rắn)",
    "  - Phản ứng oxi hoá chất béo bởi oxygen không khí",
    "",
    "**XÀ PHÒNG**",
    "Muối sodium hoặc potassium của acid béo",
    "Cấu tạo: R–C(=O)–O$^-$Na$^+$ (R– phần không phân cực/kị nước, –COO$^-$Na$^+$ phần phân cực/ưa nước)",
    "",
    "**CHẤT GIẶT RỬA** (tổng hợp / tự nhiên)",
    "Chất giặt rửa tổng hợp:",
    "Cấu tạo: R–SO$_3^-$Na$^+$ hoặc R–O–SO$_3^-$Na$^+$ (R– phần không phân cực/kị nước, –SO$_3^-$Na$^+$ phần phân cực/ưa nước)",
    "",
    "18",
    "## LUYỆN TẬP",
    "",
    "**Câu 1.** Tên gọi của HCOOC$_2$H$_5$ là",
    "A. methyl formate.     B. ethyl formate.",
    "C. methyl acetate.     D. ethyl acetate.",
    "",
    "**Câu 2.** Ester X có mùi đặc trưng giống mùi táo và có công thức phân tử C$_5$H$_{10}$O$_2$. Thuỷ phân X trong dung dịch NaOH, thu được sodium butanoate và một alcohol. Công thức của X là",
    "A. CH$_3$COOCH$_2$CH$_2$CH$_3$.     B. CH$_3$CH$_2$COOCH$_2$CH$_3$.",
    "C. CH$_3$CH$_2$CH$_2$COOCH$_3$.     D. (CH$_3$)$_2$CHCOOCH$_2$CH$_3$.",
    "",
    "**Câu 3.** Phản ứng hoá học nào sau đây xảy ra thuận nghịch?",
    "A. Đun nóng ethyl acetate với dung dịch H$_2$SO$_4$ loãng.",
    "B. Đun nóng ethyl acetate với dung dịch NaOH.",
    "C. Hydrogen hoá chất béo có gốc acid không no.",
    "D. Đun nóng chất béo với dung dịch NaOH.",
    "",
    "**Câu 4.** Cho các phát biểu sau:",
    "(1) Một số ester có mùi thơm nên được dùng làm chất tạo hương trong công nghiệp thực phẩm và mĩ phẩm.",
    "(2) Chất béo là triester của glycerol với acid béo.",
    "(3) Chất béo tan tốt trong nước.",
    "(4) Mỡ động vật, dầu thực vật có thể được dùng làm nguyên liệu để sản xuất xà phòng.",
    "(5) Phản ứng thuỷ phân ester trong môi trường acid luôn là phản ứng một chiều.",
    "Số phát biểu đúng là",
    "A. 2.     B. 3.     C. 4.     D. 5.",
    "",
    "**Câu 5.** Hãy phân loại các chất sau thành hai nhóm là xà phòng và chất giặt rửa tổng hợp:",
    "C$_{15}$H$_{31}$COONa; CH$_3$[CH$_2$]$_{11}$OSO$_3$Na; CH$_3$[CH$_2$]$_{11}$C$_6$H$_4$SO$_3$Na; C$_{17}$H$_{33}$COOK.",
    "",
    "19"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B4', 'Giới thiệu về carbohydrate. Glucose và fructose', 22, 1, $JSON$
{
  "content": [
    "# CHƯƠNG 2",
    "# CARBOHYDRATE",
    "",
    "# BÀI 4 GIỚI THIỆU VỀ CARBOHYDRATE. GLUCOSE VÀ FRUCTOSE",
    "",
    "**MỤC TIÊU**",
    "– Nêu được khái niệm, cách phân loại carbohydrate, trạng thái tự nhiên của glucose, fructose.",
    "– Viết được công thức cấu tạo dạng mạch hở, dạng mạch vòng và gọi được tên của glucose, fructose.",
    "– Trình bày được tính chất hoá học cơ bản của glucose và fructose (phản ứng với copper(II) hydroxide, nước bromine, thuốc thử Tollens, phản ứng lên men của glucose, phản ứng riêng của nhóm –OH hemiacetal khi glucose ở dạng mạch vòng).",
    "– Thực hiện được (hoặc quan sát video) thí nghiệm về phản ứng của glucose (với copper(II) hydroxide, nước bromine, thuốc thử Tollens). Mô tả các hiện tượng thí nghiệm và giải thích được tính chất hoá học của glucose và fructose.",
    "– Trình bày được ứng dụng của glucose, fructose.",
    "",
    "❓ Carbohydrate gồm nhiều hợp chất thiên nhiên có vai trò quan trọng đối với sinh vật như: tinh bột và glucose là nguồn dự trữ và cung cấp năng lượng quan trọng cho các quá trình sinh hoá tế bào; cellulose giúp xây dựng cấu trúc cho màng tế bào thực vật và thân cây. Vậy, carbohydrate là gì? Các carbohydrate đơn giản như glucose và fructose có các tính chất hoá học cơ bản nào?",
    "",
    "## I KHÁI NIỆM VÀ PHÂN LOẠI CARBOHYDRATE",
    "### 1. Khái niệm",
    "",
    "**Xét công thức cấu tạo mạch hở của hai carbohydrate sau:**",
    "CH$_2$OH–CHOH–CHOH–CHOH–CHOH–CH=O;",
    "CH$_2$OH–CHOH–CHOH–CHOH–CO–CH$_2$OH.",
    "Hai carbohydrate trên chứa những loại nhóm chức nào?",
    "2. Công thức phân tử của một số carbohydrate là C$_6$H$_{12}$O$_6$, C$_{12}$H$_{22}$O$_{11}$ và (C$_6$H$_{10}$O$_5$)$_n$.",
    "Viết lại các công thức này dưới dạng C$_n$(H$_2$O)$_m$.",
    "",
    "Carbohydrate là những hợp chất hữu cơ tạp chức, thường có công thức chung là C$_n$(H$_2$O)$_m$.",
    "",
    "💡 **EM CÓ BIẾT**",
    "Tên gọi carbohydrate có nguồn gốc lịch sử từ nhận xét rằng phần nhiều hợp chất loại này có thành phần phân tử tương ứng với công thức chung C$_n$(H$_2$O)$_m$ và được hiểu như sự kết hợp của carbon và nước (hydrate). Hiện nay, dù tên gọi carbohydrate vẫn được sử dụng, nhưng quan điểm trên đã được thay thế với hiểu biết đúng về cấu tạo của các hợp chất loại này.",
    "Carbohydrate còn có tên gọi khác là saccharide hoặc glucide. Thuật ngữ saccharide có nguồn gốc từ tiếng Hy Lạp, nghĩa là đường. Thuật ngữ glucide được dùng với nghĩa loại chất khi thuỷ phân sinh ra glucose.",
    "",
    "20",
    "### 2. Phân loại",
    "Carbohydrate có thể được chia thành ba loại chính: monosaccharide, disaccharide và polysaccharide.",
    "*Monosaccharide* là những carbohydrate không bị thuỷ phân.",
    "*Ví dụ:* glucose và fructose.",
    "*Disaccharide* là những carbohydrate khi thuỷ phân hoàn toàn mỗi phân tử tạo thành hai phân tử monosaccharide.",
    "*Ví dụ:* saccharose và maltose.",
    "*Polysaccharide* là những carbohydrate khi thuỷ phân hoàn toàn mỗi phân tử tạo thành nhiều phân tử monosaccharide.",
    "*Ví dụ:* tinh bột và cellulose.",
    "",
    "## II GLUCOSE – FRUCTOSE",
    "### 1. Cấu tạo phân tử",
    "Glucose có công thức phân tử C$_6$H$_{12}$O$_6$. Phân tử glucose ở dạng mạch hở có năm nhóm hydroxy và một nhóm aldehyde, với công thức cấu tạo là CH$_2$OH[CHOH]$_4$CH=O.",
    "Các nghiên cứu sâu hơn về cấu tạo cho biết glucose có một dạng mạch hở và hai dạng mạch vòng ($\\alpha$ và $\\beta$) chuyển hoá qua lại lẫn nhau.",
    "",
    "[Hình minh hoạ cấu tạo mạch vòng $\\alpha$-glucose $\\rightleftharpoons$ dạng mạch hở $\\rightleftharpoons$ dạng mạch vòng $\\beta$-glucose]",
    "$\\alpha$-glucose (nhóm –OH hemiacetal ở vị trí số 1 hướng xuống dưới)",
    "$\\beta$-glucose (nhóm –OH hemiacetal ở vị trí số 1 hướng lên trên)",
    "",
    "Fructose có công thức phân tử C$_6$H$_{12}$O$_6$, ở dạng mạch hở chứa năm nhóm hydroxy và một nhóm ketone. Tương tự glucose, fructose tồn tại đồng thời ở dạng mạch hở và mạch vòng.",
    "",
    "[Hình minh hoạ cấu tạo mạch vòng $\\alpha$-fructose $\\rightleftharpoons$ dạng mạch hở $\\rightleftharpoons$ dạng mạch vòng $\\beta$-fructose]",
    "$\\alpha$-fructose (nhóm –OH hemiketal ở vị trí số 2 hướng xuống dưới)",
    "$\\beta$-fructose (nhóm –OH hemiketal ở vị trí số 2 hướng lên trên)",
    "",
    "Trong môi trường kiềm, glucose và fructose có thể chuyển hoá qua lại:",
    "Glucose $\\rightleftharpoons$ Fructose (trong môi trường OH$^-$)",
    "",
    "21",
    "💡 **EM CÓ BIẾT**",
    "**Sự hình thành cấu tạo vòng**",
    "Cấu tạo vòng của các monosaccharide hình thành do phản ứng thuận nghịch giữa nhóm –OH với nhóm –CH=O (hoặc >C=O) hình thành cấu tạo hemiacetal (hoặc hemiketal). Ví dụ: sự hình thành cấu tạo vòng của glucose là do phản ứng của nhóm –OH trên carbon số 5 với nhóm –CH=O (hình bên).",
    "[Hình minh hoạ cơ chế đóng vòng của glucose]",
    "",
    "### 2. Tính chất hoá học",
    "",
    "Từ cấu tạo phân tử của glucose và fructose (dạng mạch hở và mạch vòng), cho biết mỗi chất chứa các nhóm chức nào và đề xuất một số phản ứng chứng minh sự tồn tại của các nhóm chức đó.",
    "",
    "Glucose có tính chất của polyalcohol và của aldehyde. Fructose có tính chất của polyalcohol và của ketone.",
    "",
    "**a) Tính chất polyalcohol**",
    "",
    "**Thí nghiệm: Phản ứng của glucose với Cu(OH)$_2$**",
    "*Chuẩn bị:*",
    "Hoá chất: dung dịch CuSO$_4$ 5%, dung dịch NaOH 10%, dung dịch glucose 2%.",
    "Dụng cụ: ống nghiệm.",
    "*Tiến hành:*",
    "– Cho khoảng 2 mL dung dịch NaOH 10% vào ống nghiệm. Sau đó, thêm khoảng 0,5 mL dung dịch CuSO$_4$ 5% vào, lắc nhẹ.",
    "– Cho tiếp khoảng 3 mL dung dịch glucose 2% vào ống nghiệm và lắc đều.",
    "*Quan sát hiện tượng xảy ra, giải thích và viết phương trình hoá học.*",
    "",
    "Phân tử glucose và fructose có nhiều nhóm hydroxy liền kề nên dung dịch glucose và dung dịch fructose có thể hoà tan copper(II) hydroxide trong môi trường kiềm, tạo thành dung dịch có màu xanh lam.",
    "2C$_6$H$_{12}$O$_6$ + Cu(OH)$_2$ $\\longrightarrow$ (C$_6$H$_{11}$O$_6$)$_2$Cu + 2H$_2$O",
    "",
    "**b) Tính chất aldehyde**",
    "",
    "**Thí nghiệm: Tính chất aldehyde của glucose**",
    "*Chuẩn bị:*",
    "Hoá chất: dung dịch CuSO$_4$ 5%, dung dịch NaOH 10%, dung dịch AgNO$_3$ 1%, dung dịch ammonia 5%, nước bromine loãng, dung dịch glucose 2%, nước nóng.",
    "Dụng cụ: ống nghiệm, cốc thuỷ tinh, đèn cồn.",
    "*Tiến hành:*",
    "1. Oxi hoá glucose bằng Cu(OH)$_2$:",
    "– Cho khoảng 2 mL dung dịch NaOH 10% vào ống nghiệm. Sau đó, thêm khoảng 0,5 mL dung dịch CuSO$_4$ 5% vào, lắc nhẹ.",
    "– Cho tiếp khoảng 3 mL dung dịch glucose 2% vào ống nghiệm và lắc đều.",
    "– Đun nóng ống nghiệm bằng ngọn lửa đèn cồn trong vài phút.",
    "",
    "22",
    "2. Phản ứng của glucose với thuốc thử Tollens:",
    "– Cho khoảng 2 mL dung dịch AgNO$_3$ 1% vào ống nghiệm, thêm từ từ dung dịch ammonia 5%, lắc đều đến khi kết tủa tan hết. Dung dịch thu được là thuốc thử Tollens.",
    "– Thêm vào ống nghiệm khoảng 2 mL dung dịch glucose 2%, lắc đều. Sau đó, ngâm ống nghiệm vào cốc thuỷ tinh chứa nước nóng trong vài phút.",
    "3. Phản ứng của glucose với nước bromine",
    "– Cho khoảng 1 mL nước bromine loãng vào ống nghiệm.",
    "– Thêm tiếp từ từ 2 mL dung dịch glucose 2%, lắc đều.",
    "*Quan sát và mô tả hiện tượng xảy ra trong mỗi ống nghiệm, giải thích và viết phương trình hoá học.*",
    "",
    "Nhóm aldehyde của glucose có thể bị oxi hoá bởi Cu(OH)$_2$ trong môi trường kiềm khi đun nóng, bởi thuốc thử Tollens và bởi nước bromine.",
    "CH$_2$OH[CHOH]$_4$CH=O + 2Cu(OH)$_2$ + NaOH $\\xrightarrow{\\text{t}^\\circ}$ CH$_2$OH[CHOH]$_4$COONa + Cu$_2$O + 3H$_2$O",
    "(sodium gluconate)",
    "",
    "CH$_2$OH[CHOH]$_4$CH=O + 2[Ag(NH$_3$)$_2$]OH $\\xrightarrow{\\text{t}^\\circ}$ CH$_2$OH[CHOH]$_4$COONH$_4$ + 2Ag + 3NH$_3$ + H$_2$O",
    "(ammonium gluconate)",
    "",
    "CH$_2$OH[CHOH]$_4$CH=O + Br$_2$ + H$_2$O $\\longrightarrow$ CH$_2$OH[CHOH]$_4$COOH + 2HBr",
    "(gluconic acid)",
    "",
    "Tương tự glucose, fructose cũng bị oxi hoá bởi thuốc thử Tollens và bởi Cu(OH)$_2$ trong môi trường kiềm.",
    "",
    "❓ 1. Viết phương trình hoá học minh hoạ phản ứng của fructose với thuốc thử Tollens và Cu(OH)$_2$ (trong môi trường kiềm, đun nóng).",
    "",
    "**c) Tính chất của nhóm –OH hemiacetal**",
    "Ở dạng cấu tạo mạch vòng, nhóm –OH hemiacetal của glucose tác dụng với methanol khi có mặt của HCl khan, tạo thành methyl glucoside.",
    "[Hình minh hoạ phản ứng: $\\alpha$-glucose + CH$_3$OH $\\xrightarrow{\\text{HCl}}$ methyl $\\alpha$-glucoside + H$_2$O]",
    "($^{(1)}$ Ngoài dạng methyl $\\alpha$-glucoside còn sinh ra dạng methyl $\\beta$-glucoside.)",
    "",
    "**d) Phản ứng lên men của glucose**",
    "Dưới tác dụng của các enzyme từ các vi sinh vật khác nhau, glucose được lên men tạo thành các hợp chất có nhiều ứng dụng trong đời sống như ethanol, lactic acid,...",
    "",
    "23",
    "*Ví dụ:*",
    "C$_6$H$_{12}$O$_6$ $\\xrightarrow{\\text{enzyme}}$ 2C$_2$H$_5$OH + 2CO$_2$",
    "C$_6$H$_{12}$O$_6$ $\\xrightarrow{\\text{enzyme}}$ 2CH$_3$CH(OH)COOH (lactic acid)",
    "",
    "### 3. Trạng thái tự nhiên và ứng dụng",
    "**a) Glucose**",
    "Glucose là chất rắn, dễ tan trong nước, có vị ngọt.",
    "Glucose hình thành trong thực vật nhờ quá trình quang hợp. Glucose có trong hầu hết các bộ phận của cây như hoa, lá,... và nhất là trong quả chín. Glucose cũng có trong cơ thể người và động vật. Trong máu người trưởng thành, khoẻ mạnh vào lúc đói có một lượng nhỏ glucose với nồng độ khoảng 4,4 – 7,2 mmol/L (hay 80 – 130 mg/dL)$^{(1)}$.",
    "Glucose đóng vai trò cung cấp năng lượng cho tế bào. Trong cuộc sống, glucose có các ứng dụng phổ biến sau:",
    "[Sơ đồ ứng dụng của GLUCOSE: Tráng gương, tráng ruột phích; Thực phẩm và đồ uống; Nguyên liệu sản xuất ethanol; Dung dịch truyền tĩnh mạch glucose 5%]",
    "",
    "❓ 2. Cho biết các ứng dụng của glucose trong sơ đồ trên dựa trên tính chất nào của chất này.",
    "",
    "**b) Fructose**",
    "Fructose là chất rắn, dễ tan trong nước, có vị ngọt.",
    "Fructose có trong nhiều loại trái cây (táo, lựu, nho, lê,...), trong một số loại rau củ (cà rốt, củ cải đường,...) và fructose có nhiều trong mật ong.",
    "Tương tự glucose, fructose chủ yếu đóng vai trò cung cấp năng lượng cho tế bào.",
    "",
    "**EM ĐÃ HỌC**",
    "- Carbohydrate là những hợp chất hữu cơ tạp chức, thường có công thức chung là C$_n$(H$_2$O)$_m$.",
    "- Glucose và fructose tồn tại đồng thời cấu tạo dạng mạch hở và mạch vòng. Fructose chuyển hoá thuận nghịch thành glucose trong môi trường kiềm.",
    "- Glucose và fructose thể hiện tính chất của các hợp chất alcohol có nhiều nhóm –OH liền kề. Glucose còn thể hiện tính chất của nhóm –OH hemiacetal và của nhóm chức aldehyde.",
    "- Glucose và fructose là nguồn dinh dưỡng có giá trị cho con người, chúng có nhiều ứng dụng trong các ngành công nghiệp thực phẩm, y tế,...",
    "",
    "**EM CÓ THỂ**",
    "Lựa chọn và sử dụng các nguồn cung cấp glucose và fructose phù hợp.",
    "",
    "$^{(1)}$ Nguồn: Quyết định số 5481/QĐ-BYT, ngày 30 tháng 12 năm 2020 của Bộ trưởng Bộ Y tế về việc ban hành tài liệu chuyên môn \"Hướng dẫn chẩn đoán và điều trị đái tháo đường típ 2\".",
    "",
    "24"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B5', 'Saccharose và maltose', 27, 2, $JSON$
{
  "content": [
    "# BÀI 5 SACCHAROSE VÀ MALTOSE",
    "",
    "**MỤC TIÊU**",
    "– Viết được công thức cấu tạo dạng mạch hở, dạng mạch vòng và gọi được tên của saccharose, maltose.",
    "– Trình bày được tính chất hoá học cơ bản của saccharose (phản ứng với copper(II) hydroxide, phản ứng thuỷ phân).",
    "– Thực hiện được (hoặc quan sát video) thí nghiệm về phản ứng của saccharose với copper(II) hydroxide. Mô tả hiện tượng thí nghiệm và giải thích được tính chất hoá học của saccharose.",
    "– Nêu được trạng thái tự nhiên và trình bày được ứng dụng của saccharose, maltose.",
    "",
    "❓ Đường ăn (saccharose) là chất làm ngọt phổ biến trong sản xuất thực phẩm, còn đường mạch nha (maltose) chủ yếu sử dụng để sản xuất bia. Saccharose và maltose có cấu tạo như thế nào? Chúng có những tính chất hoá học cơ bản nào?",
    "",
    "## I CẤU TẠO PHÂN TỬ",
    "Saccharose có công thức phân tử C$_{12}$H$_{22}$O$_{11}$, cấu tạo từ một đơn vị $\\alpha$-glucose và một đơn vị $\\beta$-fructose qua liên kết $\\alpha$-1,2-glycoside.",
    "[Hình ảnh công thức cấu tạo vòng của Saccharose với liên kết $\\alpha$-1,2-glycoside]",
    "",
    "Maltose có công thức phân tử C$_{12}$H$_{22}$O$_{11}$, cấu tạo từ hai đơn vị glucose qua liên kết $\\alpha$-1,4-glycoside.",
    "[Hình ảnh công thức cấu tạo vòng của Maltose với liên kết $\\alpha$-1,4-glycoside, trong đó vòng thứ 2 có nhóm -OH hemiacetal ở dạng $\\alpha$ hoặc $\\beta$]",
    "Dạng mở vòng của maltose $\\rightleftharpoons$ Dạng mạch vòng của maltose",
    "",
    "❓ 1. Tại sao saccharose chỉ tồn tại ở dạng mạch vòng, trong khi maltose tồn tại đồng thời ở dạng mở vòng và mạch vòng?",
    "",
    "$^{(1)}$ Nhóm –OH có thể ở dạng $\\alpha$ hoặc $\\beta$.",
    "",
    "25",
    "## II TÍNH CHẤT HOÁ HỌC CỦA SACCHAROSE",
    "Từ đặc điểm cấu tạo phân tử của sacharose, dự đoán các tính chất hoá học có thể có của saccharose.",
    "",
    "### 1. Tính chất của polyalcohol",
    "",
    "**Thí nghiệm: Phản ứng của saccharose với Cu(OH)$_2$**",
    "*Chuẩn bị:*",
    "Hoá chất: dung dịch CuSO$_4$ 5%, dung dịch NaOH 10%, dung dịch saccharose 5%.",
    "Dụng cụ: ống nghiệm.",
    "*Tiến hành:*",
    "– Cho khoảng 2 mL dung dịch NaOH 10% vào ống nghiệm. Sau đó, thêm khoảng 0,5 mL dung dịch CuSO$_4$ 5% vào, lắc nhẹ.",
    "– Cho khoảng 3 mL dung dịch saccharose 5% vào ống nghiệm, lắc đều.",
    "*Quan sát hiện tượng xảy ra, giải thích và viết phương trình hoá học.*",
    "",
    "Phân tử saccharose có nhiều nhóm hydroxy kề nhau nên dung dịch chất này có thể hoà tan Cu(OH)$_2$ trong môi trường kiềm, tạo thành dung dịch có màu xanh lam.",
    "2C$_{12}$H$_{22}$O$_{11}$ + Cu(OH)$_2$ $\\longrightarrow$ (C$_{12}$H$_{21}$O$_{11}$)$_2$Cu + 2H$_2$O",
    "",
    "### 2. Phản ứng thuỷ phân",
    "Saccharose bị thuỷ phân trong môi trường acid hoặc dưới tác dụng của enzyme, tạo thành glucose và fructose.",
    "C$_{12}$H$_{22}$O$_{11}$ + H$_2$O $\\xrightarrow{\\text{enzyme hoặc H}^+}$ C$_6$H$_{12}$O$_6$ (glucose) + C$_6$H$_{12}$O$_6$ (fructose)",
    "",
    "❓ 2. Dung dịch saccharose không phản ứng với thuốc thử Tollens nhưng khi đun nóng với dung dịch acid loãng thì tạo thành dung dịch phản ứng với thuốc thử Tollens. Giải thích.",
    "",
    "## III TRẠNG THÁI TỰ NHIÊN VÀ ỨNG DỤNG",
    "### 1. Saccharose",
    "Saccharose là chất rắn có vị ngọt, dễ tan trong nước.",
    "Saccharose được tổng hợp trong thực vật từ glucose và fructose. Saccharose có trong nhiều loài thực vật, có nhiều nhất trong cây mía, củ cải đường và hoa thốt nốt.",
    "Saccharose được sử dụng như một chất làm ngọt phổ biến trong sản xuất thực phẩm như bánh, kẹo, nước giải khát và đồ uống có gas,...",
    "[Hình 5.1. Mía chứa nhiều saccharose]",
    "",
    "26",
    "### 2. Maltose",
    "Maltose là chất rắn, có vị ngọt, dễ tan trong nước.",
    "Maltose có trong một số hạt nảy mầm. Maltose chủ yếu được tạo ra trong quá trình thuỷ phân tinh bột.",
    "Maltose được sử dụng làm nguyên liệu sản xuất bia và chất tạo ngọt cho một số loại bánh kẹo.",
    "[Hình 5.2. Mạch nha chứa maltose (còn gọi là đường mạch nha)]",
    "",
    "**EM ĐÃ HỌC**",
    "- Phân tử saccharose cấu tạo từ một đơn vị $\\alpha$-glucose và một đơn vị $\\beta$-fructose qua liên kết $\\alpha$-1,2-glycoside. Phân tử maltose cấu tạo từ hai đơn vị glucose qua liên kết $\\alpha$-1,4-glycoside.",
    "- Saccharose có tính chất của polyalcohol tương tự glucose (hoà tan được Cu(OH)$_2$ trong môi trường kiềm tạo dung dịch màu xanh lam).",
    "- Saccharose có thể bị thuỷ phân (dưới tác dụng của enzyme hoặc acid) tạo thành glucose và fructose.",
    "- Saccharose thường được sử dụng làm chất tạo ngọt cho thực phẩm, được sản xuất từ mía, thốt nốt, củ cải đường. Maltose thường sử dụng để sản xuất bia, được hình thành trong quá trình thuỷ phân tinh bột.",
    "",
    "**EM CÓ THỂ**",
    "- Lựa chọn và sử dụng các nguồn cung cấp saccharose và maltose phù hợp trong chế độ ăn uống để đảm bảo sức khoẻ.",
    "",
    "27"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B6', 'Tinh bột và cellulose', 30, 3, $JSON$
{
  "content": [
    "# BÀI 6 TINH BỘT VÀ CELLULOSE",
    "",
    "**MỤC TIÊU**",
    "– Viết được công thức cấu tạo và gọi được tên của tinh bột, cellulose.",
    "– Trình bày được tính chất hoá học cơ bản của tinh bột (phản ứng thuỷ phân, phản ứng với iodine); của cellulose (phản ứng thuỷ phân, phản ứng với nitric acid và với nước Schweizer (Svayde)).",
    "– Thực hiện được (hoặc quan sát video) thí nghiệm về phản ứng của tinh bột (phản ứng thuỷ phân, phản ứng của hồ tinh bột với iodine); của cellulose (phản ứng thuỷ phân, phản ứng với nitric acid và tan trong nước Schweizer). Mô tả các hiện tượng thí nghiệm và giải thích được tính chất hoá học của tinh bột và cellulose.",
    "– Nêu được trạng thái tự nhiên và trình bày được ứng dụng của tinh bột, cellulose.",
    "– Trình bày được sự chuyển hoá tinh bột trong cơ thể, sự tạo thành tinh bột trong cây xanh.",
    "",
    "❓ Tinh bột và cellulose đều là polysaccharide, nhưng chúng đóng những vai trò quan trọng khác nhau trong thực vật và có một số ứng dụng khác nhau trong cuộc sống. Vậy, về cấu tạo và tính chất của tinh bột và cellulose khác nhau như thế nào?",
    "",
    "## I CẤU TẠO PHÂN TỬ",
    "### 1. Tinh bột",
    "Tinh bột là polymer thiên nhiên, gồm amylose và amylopectin. Tinh bột có công thức phân tử là (C$_6$H$_{10}$O$_5$)$_n$.",
    "",
    "Phân tử amylose cấu tạo từ nhiều đơn vị $\\alpha$-glucose liên kết với nhau qua các liên kết $\\alpha$-1,4-glycoside và hình thành chuỗi xoắn.",
    "[Hình minh hoạ đoạn mạch amylose với các liên kết $\\alpha$-1,4-glycoside]",
    "",
    "Phân tử amylopectin có cấu tạo phân nhánh, gồm các chuỗi chứa nhiều đơn vị $\\alpha$-glucose liên kết với nhau qua các liên kết $\\alpha$-1,4-glycoside. Các chuỗi này liên kết với nhau tạo cấu tạo mạch nhánh qua liên kết $\\alpha$-1,6-glycoside.",
    "[Hình minh hoạ đoạn mạch amylopectin với liên kết $\\alpha$-1,4-glycoside và nhánh tại liên kết $\\alpha$-1,6-glycoside]",
    "",
    "28",
    "### 2. Cellulose",
    "Cellulose là polymer thiên nhiên, có công thức phân tử là (C$_6$H$_{10}$O$_5$)$_n$. Phân tử cellulose cấu tạo từ nhiều đơn vị $\\beta$-glucose qua liên kết $\\beta$-1,4-glycoside và hình thành chuỗi không nhánh.",
    "[Hình minh hoạ đoạn mạch cellulose với liên kết $\\beta$-1,4-glycoside]",
    "",
    "❓ 1. Cấu tạo của tinh bột và cellulose có những đặc điểm nào khác nhau?",
    "",
    "## II TÍNH CHẤT HOÁ HỌC",
    "### 1. Tính chất của tinh bột",
    "**a) Phản ứng thuỷ phân**",
    "",
    "**Thí nghiệm: Phản ứng thuỷ phân tinh bột**",
    "*Chuẩn bị:*",
    "Hoá chất: dung dịch hồ tinh bột 1%, dung dịch CuSO$_4$ 5%, dung dịch NaOH 10%, dung dịch HCl 1 M, NaHCO$_3$ rắn, nước nóng.",
    "Dụng cụ: ống nghiệm, cốc thuỷ tinh, bếp điện.",
    "*Tiến hành:*",
    "– Cho khoảng 5 mL dung dịch hồ tinh bột 1% vào ống nghiệm. Sau đó thêm khoảng 1 mL dung dịch HCl 1 M vào, lắc đều.",
    "– Đặt ống nghiệm trong một cốc thuỷ tinh chứa nước nóng, đun cách thuỷ trong 10 phút. Sau đó để nguội.",
    "– Thêm từ từ NaHCO$_3$ vào đến khi ngừng sủi bọt khí.",
    "– Cho khoảng 2 mL dung dịch thu được vào ống nghiệm chứa Cu(OH)$_2$ (được điều chế bằng cách cho 0,5 mL dung dịch CuSO$_4$ 5% vào 2 mL dung dịch NaOH 10%, lắc nhẹ). Sau đó đặt ống nghiệm trong cốc thuỷ tinh chứa nước nóng khoảng 5 phút.",
    "*Quan sát hiện tượng xảy ra và rút ra nhận xét.*",
    "",
    "Tinh bột bị thuỷ phân dưới tác dụng của enzyme hoặc acid. Khi tinh bột bị thuỷ phân không hoàn toàn tạo thành dextrin$^{(1)}$, maltose và glucose. Tinh bột bị thuỷ phân hoàn toàn tạo thành glucose.",
    "(C$_6$H$_{10}$O$_5$)$_n$ + nH$_2$O $\\xrightarrow{\\text{enzyme hoặc H}^+}$ nC$_6$H$_{12}$O$_6$ (glucose)",
    "",
    "**b) Phản ứng màu với dung dịch iodine**",
    "",
    "**Thí nghiệm: Phản ứng màu của hồ tinh bột với iodine**",
    "*Chuẩn bị:*",
    "Hoá chất: dung dịch iodine trong KI, dung dịch hồ tinh bột 1%.",
    "Dụng cụ: ống nghiệm, ống hút nhỏ giọt.",
    "*Tiến hành:* Lấy 2 mL dung dịch hồ tinh bột 1% vào ống nghiệm. Nhỏ tiếp vài giọt dung dịch iodine vào ống nghiệm, lắc đều.",
    "*Quan sát hiện tượng xảy ra và rút ra nhận xét.*",
    "",
    "$^{(1)}$ Dextrin là các hợp chất carbohydrate có phân tử khối thấp hơn tinh bột.",
    "",
    "29",
    "Trong tinh bột, các phân tử amylose có dạng xoắn, khi tương tác với iodine tạo ra màu xanh tím. Phản ứng này được dùng để nhận biết tinh bột.",
    "[Hình 6.1. Mô hình tương tác giữa tinh bột và iodine]",
    "",
    "### 2. Tính chất của cellulose",
    "**a) Phản ứng thuỷ phân**",
    "",
    "**Thí nghiệm: Phản ứng thuỷ phân cellulose trong môi trường acid**",
    "*Chuẩn bị:*",
    "Hoá chất: cellulose (bông), dung dịch H$_2$SO$_4$ 70%, dung dịch NaOH 10%, dung dịch CuSO$_4$ 5%, NaHCO$_3$ rắn, nước nóng.",
    "Dụng cụ: ống nghiệm, cốc thuỷ tinh 250 mL, đũa thuỷ tinh, đèn cồn, giá đựng ống nghiệm.",
    "*Tiến hành:*",
    "– Cho 10 mL dung dịch H$_2$SO$_4$ 70% vào cốc thuỷ tinh, thêm một lượng nhỏ cellulose (bông) vào cốc và dùng đũa thuỷ tinh khuấy đều. Sau đó, đặt cốc thuỷ tinh vào cốc nước nóng và khuấy trong khoảng 3 phút để cellulose tan hết tạo dung dịch đồng nhất.",
    "– Trung hoà dung dịch bằng cách thêm từ từ NaHCO$_3$ đến khi dừng sủi bọt khí, sau đó thêm tiếp 5 mL dung dịch NaOH 10%.",
    "– Cho 5 mL dung dịch thu được ở trên vào ống nghiệm chứa Cu(OH)$_2$ (được điều chế bằng cách cho 0,5 mL dung dịch CuSO$_4$ 5% vào 2 mL dung dịch NaOH 10%, lắc nhẹ). Đun nóng đều ống nghiệm khoảng 2 phút, sau đó để ống nghiệm trên giá khoảng 3 phút.",
    "*Chú ý:* Cần thận trọng khi làm việc với dung dịch H$_2$SO$_4$ đặc.",
    "*Quan sát hiện tượng xảy ra, giải thích và viết phương trình hoá học.*",
    "",
    "Tương tự tinh bột, cellulose bị thuỷ phân bởi enzyme hoặc acid (HCl hoặc H$_2$SO$_4$). Phản ứng thuỷ phân hoàn toàn tạo thành glucose.",
    "(C$_6$H$_{10}$O$_5$)$_n$ + nH$_2$O $\\xrightarrow{\\text{enzyme hoặc H}^+}$ nC$_6$H$_{12}$O$_6$ (glucose)",
    "",
    "❓ 2. Tại sao tinh bột và cellulose đều có thể dùng để sản xuất ethanol?",
    "",
    "**b) Phản ứng với nitric acid**",
    "",
    "**Thí nghiệm: Phản ứng của cellulose với nitric acid**",
    "*Chuẩn bị:*",
    "Hoá chất: cellulose (bông), dung dịch HNO$_3$ đặc, dung dịch H$_2$SO$_4$ đặc, dung dịch NaHCO$_3$ loãng, quỳ tím.",
    "Dụng cụ: cốc thuỷ tinh 100 mL, chậu nước nóng, chậu nước đá, đũa thuỷ tinh, giấy lọc, đĩa sứ, đèn cồn.",
    "*Tiến hành:*",
    "– Cho khoảng 5 mL dung dịch HNO$_3$ đặc vào cốc thuỷ tinh (loại 100 mL) ngâm trong chậu nước đá. Thêm từ từ khoảng 10 mL dung dịch H$_2$SO$_4$ đặc vào cốc và khuấy đều. Sau đó, lấy cốc thuỷ tinh ra khỏi chậu nước đá, thêm tiếp một nhúm bông vào cốc và dùng đũa thuỷ tinh ấn bông ngập trong dung dịch.",
    "",
    "30",
    "– Ngâm cốc trong chậu nước nóng khoảng 10 phút. Để nguội, lấy sản phẩm thu được ra khỏi cốc, rửa nhiều lần với nước lạnh (đến khi nước rửa không làm đổi màu quỳ tím), sau đó rửa lại bằng dung dịch NaHCO$_3$ loãng.",
    "– Ép sản phẩm giữa hai miếng giấy lọc để hút nước và làm khô tự nhiên. Sau đó, để sản phẩm lên đĩa sứ rồi đốt cháy sản phẩm.",
    "*Chú ý:* Cần thận trọng khi làm việc với dung dịch HNO$_3$ đặc và dung dịch H$_2$SO$_4$ đặc.",
    "*Quan sát hiện tượng xảy ra, giải thích và viết phương trình hoá học.*",
    "",
    "Trong mỗi đơn vị glucose cấu thành phân tử cellulose có ba nhóm hydroxy. Khi đun nóng cellulose với hỗn hợp HNO$_3$ đặc và H$_2$SO$_4$ đặc, tuỳ theo điều kiện phản ứng mà một, hai hay cả ba nhóm hydroxy này có thể phản ứng với nitric acid tạo thành cellulose nitrate.",
    "*Ví dụ:* [(C$_6$H$_7$O$_2$(OH)$_3$]$_n$ + 3nHONO$_2$ $\\xrightarrow{\\text{H}_2\\text{SO}_4 \\text{ đặc, t}^\\circ}$ [(C$_6$H$_7$O$_2$(ONO$_2$)$_3$]$_n$ + 3nH$_2$O",
    "(cellulose trinitrate)",
    "",
    "**c) Cellulose phản ứng với nước Schweizer**",
    "",
    "**Thí nghiệm: Tính tan của cellulose trong nước Schweizer**",
    "*Chuẩn bị:*",
    "Hoá chất: cellulose (bông), dung dịch CuSO$_4$ 1 M, dung dịch NaOH 20%, dung dịch NH$_3$ đặc.",
    "Dụng cụ: giấy lọc, cốc thuỷ tinh 250 mL, đũa thuỷ tinh, ống hút.",
    "*Tiến hành:*",
    "– Cho khoảng 50 mL dung dịch CuSO$_4$ 1 M vào cốc 250 mL. Thêm 20 mL dung dịch NaOH 20% vào, khuấy đều.",
    "– Lọc tách kết tủa, cho vào cốc thuỷ tinh 250 mL. Thêm khoảng 50 mL dung dịch NH$_3$ đặc, khuấy đều đến khi kết tủa tan hết thu được nước Schweizer.",
    "– Thêm một lượng nhỏ bông vào khoảng 30 mL nước Schweizer và khuấy đều trong khoảng 3 phút.",
    "*Quan sát hiện tượng xảy ra, giải thích và viết phương trình hoá học.*",
    "",
    "Cellulose tan được trong nước Schweizer (dung dịch thu được khi hoà tan Cu(OH)$_2$ trong ammonia).",
    "",
    "## III TRẠNG THÁI TỰ NHIÊN VÀ ỨNG DỤNG",
    "### 1. Tinh bột",
    "Tinh bột là chất rắn màu trắng, hầu như không tan trong nước lạnh. Trong nước nóng, tinh bột tan tạo dung dịch keo nhớt, gọi là hồ tinh bột.",
    "[Hình 6.2. Hạt gạo chứa nhiều tinh bột (hàm lượng khoảng 80%)]",
    "",
    "**Sự tạo thành tinh bột trong cây xanh:**",
    "Trong thực vật, tinh bột có chủ yếu trong củ, quả hay hạt. Sự hình thành tinh bột trong thực vật diễn ra qua nhiều giai đoạn, gồm hai quá trình chính là quá trình quang hợp hình thành glucose và quá trình kết hợp của các đơn vị glucose tạo thành tinh bột.",
    "6nCO$_2$ + 5nH$_2$O $\\xrightarrow{\\text{ánh sáng, chất diệp lục}}$ (C$_6$H$_{10}$O$_5$)$_n$ + 6nO$_2$",
    "",
    "31",
    "*Sự chuyển hoá tinh bột trong cơ thể:*",
    "Khi con người sử dụng thức ăn chứa tinh bột, enzyme $\\alpha$-amylase có trong nước bọt thúc đẩy quá trình thuỷ phân tinh bột thành các phân tử nhỏ hơn gồm maltose và dextrin. Quá trình này tiếp tục ở ruột non, nơi phần lớn tinh bột bị thuỷ phân thành glucose. Glucose được hấp thụ vào máu và di chuyển đến các tế bào trong khắp cơ thể. Glucose có thể được sử dụng cho nhu cầu năng lượng hoặc có thể được chuyển đổi thành glycogen lưu trữ trong gan và cơ.",
    "",
    "Tinh bột là nguồn lương thực chính của con người và một số động vật, đồng thời cũng được dùng nhiều trong công nghiệp thực phẩm (chất làm đặc, chất kết dính, sản xuất ethanol,...). Ngoài ra, tinh bột cũng được sử dụng làm chất kết dính trong công nghiệp giấy và công nghiệp dệt may.",
    "",
    "### 2. Cellulose",
    "Cellulose là chất rắn, dạng sợi, màu trắng, không tan trong nước ngay cả khi đun nóng, không tan trong các dung môi hữu cơ thông thường như ether, benzene,...",
    "Cellulose được tổng hợp bởi thực vật, chiếm khoảng 50% khối lượng của gỗ khô và khoảng 90% khối lượng sợi bông.",
    "[Hình 6.3. Quả bông chứa nhiều cellulose (hàm lượng khoảng 90%)]",
    "",
    "Cellulose được sử dụng để làm vật liệu xây dựng (các loại đồ gỗ), sản xuất giấy, sợi tự nhiên và sợi nhân tạo. Cellulose cũng được sử dụng làm nguyên liệu để điều chế ethanol và cellulose trinitrate (dùng chế tạo thuốc súng không khói).",
    "",
    "**EM ĐÃ HỌC**",
    "- Tinh bột và cellulose là những polymer thiên nhiên, có công thức phân tử là (C$_6$H$_{10}$O$_5$)$_n$. Tinh bột gồm amylose và amylopectin.",
    "- Tinh bột có phản ứng thuỷ phân, phản ứng màu với dung dịch iodine.",
    "- Cellulose có phản ứng thuỷ phân, phản ứng với HNO$_3$, tan trong nước Schweizer.",
    "- Tinh bột là nguồn cung cấp năng lượng và chất dinh dưỡng quan trọng cho con người và một số động vật, nguyên liệu sản xuất glucose, ethanol,... Cellulose được dùng làm vật liệu xây dựng, tơ sợi, giấy,...",
    "",
    "**EM CÓ THỂ**",
    "- Lựa chọn và sử dụng một số nguồn cung cấp tinh bột hợp lí.",
    "- Lựa chọn và sử dụng một số sản phẩm từ cellulose an toàn, hợp lí.",
    "",
    "32"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B7', 'Ôn tập chương 2', 35, 4, $JSON$
{
  "content": [
    "# BÀI 7 ÔN TẬP CHƯƠNG 2",
    "",
    "## I HỆ THỐNG HOÁ KIẾN THỨC",
    "### 1. Cấu tạo của các carbohydrate",
    "",
    "| Chất | Công thức phân tử | Công thức cấu tạo |",
    "| --- | --- | --- |",
    "| **Glucose** | C$_6$H$_{12}$O$_6$ | $\\alpha$-glucose $\\rightleftharpoons$ dạng mạch hở $\\rightleftharpoons$ $\\beta$-glucose |",
    "| **Fructose** | C$_6$H$_{12}$O$_6$ | $\\alpha$-fructose $\\rightleftharpoons$ dạng mạch hở $\\rightleftharpoons$ $\\beta$-fructose |",
    "| **Saccharose** | C$_{12}$H$_{22}$O$_{11}$ | Liên kết $\\alpha$-1,2-glycoside giữa $\\alpha$-glucose và $\\beta$-fructose |",
    "| **Maltose** | C$_{12}$H$_{22}$O$_{11}$ | Dạng mở vòng của maltose $\\rightleftharpoons$ Dạng mạch vòng của maltose (Liên kết $\\alpha$-1,4-glycoside giữa 2 đơn vị glucose) |",
    "| **Tinh bột** (amylose và amylopectin) | (C$_6$H$_{10}$O$_5$)$_n$ | **amylose:** Liên kết $\\alpha$-1,4-glycoside<br>**amylopectin:** Liên kết $\\alpha$-1,4-glycoside và mạch nhánh tại $\\alpha$-1,6-glycoside |",
    "| **Cellulose** | (C$_6$H$_{10}$O$_5$)$_n$ | Liên kết $\\beta$-1,4-glycoside giữa các đơn vị $\\beta$-glucose |",
    "",
    "33",
    "### 2. Tính chất hoá học cơ bản của các carbohydrate",
    "",
    "|  | Cu(OH)$_2$ /NaOH | Br$_2$/H$_2$O | AgNO$_3$/NH$_3$ | Thuỷ phân |",
    "| --- | --- | --- | --- | --- |",
    "| **Glucose** | Tạo dung dịch xanh lam | Mất màu nước bromine | Tạo kết tủa bạc | Không |",
    "| **Fructose** | Tạo dung dịch xanh lam | Không | Tạo kết tủa bạc | Không |",
    "| **Saccharose**| Tạo dung dịch xanh lam | Không | Không | Tạo glucose và fructose |",
    "| **Tinh bột** | Không | Không | Không | Tạo glucose |",
    "| **Cellulose** | Không | Không | Không | Tạo glucose |",
    "",
    "Glucose còn có phản ứng của nhóm –OH hemiacetal (khi glucose ở dạng mạch vòng), phản ứng lên men; tinh bột có phản ứng màu với dung dịch iodine; cellulose có phản ứng với nitric acid và tan trong nước Schweizer.",
    "",
    "## II LUYỆN TẬP",
    "**Câu 1.** Cho các chất sau: glucose, fructose, saccharose, maltose, tinh bột và cellulose. Mỗi phát biểu sau đây đúng hay sai?",
    "a) Trong các chất trên, có hai monosaccharide, hai disaccharide và hai polysaccharide.",
    "b) Cấu tạo phân tử các chất trên đều có nhiều nhóm hydroxy.",
    "c) Glucose và fructose có thể chuyển hoá qua lại với nhau trong môi trường kiềm.",
    "",
    "**Câu 2.** Giải thích các hiện tượng sau:",
    "a) Khi ăn cơm, nếu nhai kĩ sẽ thấy vị ngọt.",
    "b) Nước ép chuối chín cho phản ứng tráng bạc.",
    "c) Nhỏ dung dịch iodine lên miếng chuối xanh xuất hiện màu xanh tím.",
    "",
    "**Câu 3.** Cồn sinh học được dùng làm nhiên liệu sạch, được sản xuất thông qua quá trình lên men các chất hữu cơ như tinh bột, cellulose. Tính khối lượng ethanol thu được từ một tấn mùn cưa chứa 45% cellulose về khối lượng, biết hiệu suất cả quá trình đạt 70%.",
    "",
    "34"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B8', 'Amine', 37, 1, $JSON$
{
  "content": [
    "# CHƯƠNG 3",
    "# HỢP CHẤT CHỨA NITROGEN",
    "",
    "# BÀI 8 AMINE",
    "",
    "**MỤC TIÊU**",
    "– Nêu được khái niệm amine và phân loại amine (theo bậc của amine và bản chất gốc hydrocarbon).",
    "– Viết được công thức cấu tạo và gọi được tên một số amine theo danh pháp thay thế, danh pháp gốc – chức (số nguyên tử C trong phân tử $\\le$ 5), tên thông thường của một số amine hay gặp.",
    "– Nêu được đặc điểm về tính chất vật lí của amine (trạng thái, nhiệt độ sôi, nhiệt độ nóng chảy, khả năng hoà tan).",
    "– Trình bày được đặc điểm cấu tạo phân tử và hình dạng phân tử methylamine và aniline.",
    "– Trình bày được tính chất hoá học đặc trưng của amine: tính chất của nhóm –NH$_2$ (tính base (với quỳ tím, với HCl, với FeCl$_3$), phản ứng với nitrous acid (axit nitrơ)), phản ứng thế ở nhân thơm (với nước bromine) của aniline (anilin), phản ứng tạo phức của methylamine (hoặc ethylamine) với Cu(OH)$_2$.",
