    "H$_2$N–CH$_2$–COOH (glycine (Gly))",
    "H$_2$N–CH(CH$_3$)–COOH (alanine (Ala))",
    "H$_2$N–CH(CH(CH$_3$)$_2$)–COOH (valine (Val))",
