    "HOOC–CH$_2$–CH$_2$–CH(NH$_2$)–COOH (glutamic acid (Glu))",
    "**Hình 9.1.** Cấu tạo, tên thông thường, kí hiệu của một số amino acid",
    "",
    "*Amino acid* là hợp chất hữu cơ tạp chức, trong phân tử chứa đồng thời nhóm amino (–NH$_2$) và nhóm carboxyl (–COOH).",
    "",
    "41",
    "Các amino acid thiên nhiên hầu hết là $\\alpha$-amino acid (công thức chung có dạng H$_2$N–CH(R)–COOH). Trong đó, chỉ có khoảng 20 amino acid cấu thành nên phần lớn protein trong cơ thể người, gọi là những amino acid tiêu chuẩn. Một số amino acid tiêu chuẩn mà cơ thể người không thể tự tổng hợp được, gọi là amino acid thiết yếu. Con người tiếp nhận amino acid thiết yếu qua thức ăn như thịt, cá, trứng, sữa,...",
