    "Ngoài ra, các $\\alpha$-amino acid có trong thiên nhiên thường được gọi bằng tên thông thường (Bảng 9.1).",
    "",
    "**Bảng 9.1.** Tên gọi của một số amino acid",
    "",
    "| Công thức cấu tạo | Tên thay thế | Tên bán hệ thống | Tên thông thường | Kí hiệu |",
    "| --- | --- | --- | --- | --- |",
    "| H$_2$N–CH$_2$–COOH | Aminoethanoic acid | Aminoacetic acid | Glycine | Gly |",
    "| H$_2$N–CH(CH$_3$)–COOH | 2-aminopropanoic acid | $\\alpha$-aminopropionic acid | Alanine | Ala |",
    "| H$_2$N–[CH$_2$]$_4$–CH(NH$_2$)COOH | 2,6-diaminohexanoic acid | $\\alpha$,$\\varepsilon$-diaminocaproic acid | Lysine | Lys |",
    "| HOOC–[CH$_2$]$_2$–CH(NH$_2$)COOH | 2-aminopentane-1,5-dioic acid | $\\alpha$-aminoglutaric acid | Glutamic acid | Glu |",
    "| (CH$_3$)$_2$CH–CH(NH$_2$)–COOH | 2-amino-3-methylbutanoic acid | $\\alpha$-aminoisovaleric acid | Valine | Val |",
    "",
    "### 2. Đặc điểm cấu tạo",
    "Các amino acid tồn tại chủ yếu ở dạng ion lưỡng cực$^{(1)}$ do tương tác giữa nhóm –COOH và nhóm –NH$_2$:",
    "H$_2$N–CH(R)–COOH $\\rightleftharpoons$ $^+$H$_3$N–CH(R)–COO$^-$",
    "(Dạng phân tử trung hoà) $\\rightleftharpoons$ (Dạng ion lưỡng cực)",
    "",
    "### 3. Tính chất vật lí",
    "Ở điều kiện thường, các amino acid là chất rắn, khi ở dạng tinh thể chúng không có màu, có nhiệt độ nóng chảy cao và thường tan tốt trong nước vì chúng tồn tại ở dạng ion lưỡng cực.",
    "",
    "$^{(1)}$ Trong một số trường hợp, để đơn giản amino acid thường được biểu diễn ở dạng phân tử.",
    "",
    "42",
    "### 4. Tính chất hoá học",
    "Tương tự các hợp chất hữu cơ tạp chức khác, amino acid có tính chất của các nhóm chức cấu thành (tính chất của nhóm amino và nhóm carboxyl) và có thêm tính chất gây ra bởi đồng thời cả hai nhóm chức này.",
    "",
    "**a) Phản ứng ester hoá**",
    "Tương tự carboxylic acid, amino acid phản ứng được với alcohol tạo ester.",
    "*Ví dụ:* Đun nóng hỗn hợp glycine và ethanol có mặt H$_2$SO$_4$ đặc xúc tác, ở nhiệt độ 80 – 90 $^\\circ$C, trong khoảng 2 – 3 giờ, thu được ester$^{(1)}$.",
    "H$_2$N–CH$_2$–COOH + CH$_3$CH$_2$OH $\\rightleftharpoons$ H$_2$N–CH$_2$–COOCH$_2$CH$_3$ + H$_2$O (H$_2$SO$_4$, t$^\\circ$)",
    "",
    "**b) Tính chất lưỡng tính**",
    "Nhóm amino có tính base và nhóm carboxyl có tính acid nên các amino acid có tính lưỡng tính, có thể tác dụng với acid mạnh cũng như base mạnh.",
    "HCl + H$_2$N–CH$_2$–COOH $\\longrightarrow$ ClH$_3$N–CH$_2$–COOH",
    "H$_2$N–CH$_2$–COOH + NaOH $\\longrightarrow$ H$_2$N–CH$_2$–COONa + H$_2$O",
    "Tính lưỡng tính của amino acid rất quan trọng trong nhiều quá trình sinh học như ổn định pH của dung dịch máu, dung dịch nội bào,...",
    "",
    "**c) Tính chất điện di**",
    "Các amino acid có khả năng di chuyển khác nhau trong điện trường tuỳ thuộc vào pH của môi trường (tính chất điện di).",
    "*Ví dụ:* Ở pH ~ 6, Gly tồn tại chủ yếu ở dạng ion lưỡng cực có tổng điện tích bằng không. Khi đặt trong điện trường, Gly hầu như không di chuyển; ở pH < 6, Gly nhận proton, trở thành cation và di chuyển về cực âm (–); còn ở pH > 6, Gly nhường proton, trở thành anion và di chuyển về cực dương (+).",
    "",
    "**d) Phản ứng trùng ngưng**",
    "Khi đun nóng, các $\\varepsilon$-amino acid hoặc $\\omega$-amino acid có thể phản ứng với nhau để tạo thành polymer, đồng thời tách ra các phân tử nước (phản ứng trùng ngưng). Trong phản ứng trùng ngưng của amino acid, nhóm –COOH của phân tử này phản ứng với nhóm –NH$_2$ của phân tử khác để tạo thành polyamide.",
    "*Ví dụ:* Phản ứng trùng ngưng tổng hợp polycaproamide (capron) từ 6-aminohexanoic acid ($\\varepsilon$-aminocaproic acid):",
    "nH$_2$N–[CH$_2$]$_5$–COOH $\\xrightarrow{\\text{t}^\\circ}$ –(–NH–[CH$_2$]$_5$–CO–)–$_n$ + nH$_2$O",
    "($\\varepsilon$-aminocaproic acid) (polycaproamide)",
    "",
    "❓ 1. Viết phương trình hoá học của phản ứng trùng ngưng tổng hợp polyenanthamide từ 7-aminoheptanoic acid ($\\omega$-aminoenanthic acid).",
    "",
    "$^{(1)}$ Trong điều kiện phản ứng, sản phẩm tồn tại ở dạng muối.",
    "",
    "43",
    "## II PEPTIDE",
    "🖐 Một tripeptide có cấu tạo như sau:",
    "[Hình minh hoạ sự hình thành tripeptide Val-Gly-Ala từ 3 amino acid Valine, Glycine và Alanine. Nhóm –COOH của Val kết hợp với nhóm –NH$_2$ của Gly tạo liên kết peptide thứ nhất. Nhóm –COOH của Gly kết hợp với nhóm –NH$_2$ của Ala tạo liên kết peptide thứ hai. Phân tử có một amino acid đầu N (Val) và một amino acid đầu C (Ala).]",
    "**Hình 9.2.** Cấu tạo của phân tử tripeptide Val-Gly-Ala",
    "Tripeptide trên cấu thành bằng cách nào? Tại sao lại gọi là tripeptide?",
    "",
    "### 1. Khái niệm",
    "*Peptide* là những hợp chất hữu cơ được cấu tạo từ các đơn vị $\\alpha$-amino acid liên kết với nhau qua liên kết peptide (–CO–NH–).",
    "Các peptide chứa từ 2, 3, 4,... đơn vị $\\alpha$-amino acid lần lượt được gọi là dipeptide, tripeptide, tetrapeptide,...; peptide chứa nhiều đơn vị $\\alpha$-amino acid được gọi là polypeptide.",
    "",
    "### 2. Cấu tạo",
    "Cấu tạo của một peptide được xác định bằng thứ tự liên kết của các $\\alpha$-amino acid trong phân tử. Mỗi peptide mạch hở bắt đầu bằng amino acid đầu N và kết thúc bằng amino acid đầu C (Hình 9.2).",
    "Tên viết tắt của peptide gồm tên viết tắt của các amino acid theo thứ tự từ amino acid đầu N đến amino acid đầu C.",
    "*Ví dụ:* Tripeptide trong Hình 9.2 được biểu diễn là Val-Gly-Ala.",
    "",
    "❓ 2. Viết cấu tạo của tripeptide Gly-Ala-Val.",
    "",
    "### 3. Tính chất hoá học",
    "**a) Phản ứng thuỷ phân**",
    "Peptide bị thuỷ phân bởi acid, base hoặc enzyme. Quá trình thuỷ phân không hoàn toàn có thể tạo thành các peptide nhỏ hơn.",
    "*Ví dụ:* Tetrapeptide Gly-Tyr-Val-Ala khi bị thuỷ phân không hoàn toàn có thể tạo thành các tripeptide Gly-Tyr-Val, Tyr-Val-Ala và các dipeptide là Gly-Tyr, Tyr-Val, Val-Ala.",
    "",
    "44",
    "Quá trình thuỷ phân hoàn toàn peptide tạo ra các amino acid cấu thành nên peptide đó. Tuy nhiên, trong môi trường acid hoặc môi trường base, các amino acid sẽ tác dụng với acid hoặc base để tạo thành muối tương ứng.",
    "*Ví dụ:*",
    "H$_2$N–CH$_2$–CO–NH–CH$_2$–COOH + H$_2$O $\\xrightarrow{\\text{enzyme}}$ 2H$_2$N–CH$_2$–COOH",
    "H$_2$N–CH$_2$–CO–NH–CH$_2$–COOH + H$_2$O + 2HCl $\\longrightarrow$ 2Cl$^-$H$_3$N$^+$–CH$_2$–COOH",
    "H$_2$N–CH$_2$–CO–NH–CH$_2$–COOH + 2NaOH $\\longrightarrow$ 2H$_2$N–CH$_2$–COONa + H$_2$O",
    "",
    "**b) Phản ứng màu biuret**",
    "",
    "**Thí nghiệm: Phản ứng màu biuret của peptide**",
    "*Chuẩn bị:*",
    "Hoá chất: dung dịch lòng trắng trứng (polypeptide), dung dịch CuSO$_4$ 2%, dung dịch NaOH 30%.",
    "Dụng cụ: ống nghiệm.",
    "*Tiến hành:*",
    "– Cho khoảng 1 mL dung dịch NaOH 30% vào ống nghiệm. Nhỏ thêm 2 – 3 giọt dung dịch CuSO$_4$ 2%, lắc đều.",
    "– Cho khoảng 4 mL dung dịch lòng trắng trứng vào ống nghiệm, lắc đều.",
    "*Quan sát và giải thích hiện tượng xảy ra.*",
    "",
    "💡 **EM CÓ BIẾT**",
    "Hợp chất tạo bởi thuốc thử biuret với các peptide",
    "[Hình minh hoạ cấu trúc phức chất tạo bởi ion Cu$^{2+}$ và 4 nhóm –NH– của liên kết peptide trong môi trường kiềm]",
    "",
    "Các peptide có từ hai liên kết peptide trở lên phản ứng với thuốc thử biuret (Cu(OH)$_2$ trong môi trường kiềm), tạo thành dung dịch có màu tím đặc trưng. Phản ứng này được sử dụng để nhận biết các peptide (trừ dipeptide).",
    "",
    "❓ 3. Thuỷ phân không hoàn toàn tripeptide Val-Gly-Ala thu được các dipeptide nào? Viết phương trình hoá học minh hoạ phản ứng thuỷ phân hoàn toàn tripeptide này trong môi trường kiềm.",
    "",
    "**EM ĐÃ HỌC**",
    "- Amino acid là hợp chất hữu cơ tạp chức, trong phân tử chứa đồng thời nhóm amino và nhóm carboxyl, tồn tại chủ yếu ở dạng ion lưỡng cực. Hầu hết amino acid thiên nhiên là $\\alpha$-amino acid.",
    "- Amino acid là chất rắn, thường tan tốt trong nước, có nhiệt độ nóng chảy cao. Các amino acid có tính lưỡng tính và tham gia được phản ứng ester hoá; các $\\varepsilon$- và $\\omega$-amino acid có thể tham gia phản ứng trùng ngưng tạo polyamide.",
    "- Peptide là những hợp chất hữu cơ được cấu tạo từ nhiều đơn vị $\\alpha$-amino acid liên kết với nhau qua liên kết peptide (–CO–NH–). Peptide tham gia phản ứng thuỷ phân và phản ứng màu biuret.",
    "",
    "**EM CÓ THỂ**",
    "- Biết được tại sao amino acid quan trọng cho sức khoẻ, từ đó có thể lựa chọn được một số thực phẩm giàu dinh dưỡng.",
    "",
    "45"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B10', 'Protein và enzyme', 48, 3, $JSON$
{
  "content": [
    "# BÀI 10 PROTEIN VÀ ENZYME",
    "",
    "**MỤC TIÊU**",
    "– Nêu được khái niệm, đặc điểm cấu tạo phân tử, tính chất vật lí của protein.",
    "– Trình bày được tính chất hoá học đặc trưng của protein (phản ứng thuỷ phân, phản ứng màu của protein với nitric acid và copper(II) hydroxide; sự đông tụ bởi nhiệt, bởi acid, kiềm và muối kim loại nặng).",
    "– Thực hiện được thí nghiệm về phản ứng đông tụ của protein: đun nóng lòng trắng trứng hoặc tác dụng của acid, kiềm với lòng trắng trứng; phản ứng của lòng trắng trứng với nitric acid; mô tả các hiện tượng thí nghiệm, giải thích được tính chất hoá học của protein.",
    "– Nêu được vai trò của protein đối với sự sống; vai trò của enzyme trong phản ứng sinh hoá và ứng dụng của enzyme trong công nghệ sinh học.",
    "",
    "❓ Các protein khác nhau đảm nhận nhiều vai trò thiết yếu khác nhau với sự sống như xây dựng tế bào, xúc tác cho các quá trình sinh hoá, điều hoà quá trình trao đổi chất, vận chuyển chất, kháng thể,... Vậy, protein có đặc điểm cấu tạo và tính chất đặc trưng là gì?",
    "",
    "## I PROTEIN",
    "### 1. Khái niệm và đặc điểm cấu tạo",
    "🖐 Insulin, một loại hormone thuộc loại protein, được sản sinh bởi tuyến tuỵ, có chức năng điều hoà quá trình chuyển hoá glucose trong cơ thể. Insulin thúc đẩy sự hấp thu glucose của các tế bào và dự trữ glucose dư thừa trong gan và cơ.",
    "Insulin có cấu tạo được mô tả trong Hình 10.1. Hãy nhận xét về thành phần cấu tạo và phân tử khối của insulin.",
    "[Hình 10.1. Cấu tạo của insulin: gồm mạch A (21 đơn vị amino acid) và mạch B (30 đơn vị amino acid), liên kết với nhau bằng các cầu nối disulfide –S–S–]",
    "",
    "*Protein* là hợp chất cao phân tử được cấu tạo từ một hay nhiều chuỗi polypeptide.",
    "Mỗi chuỗi polypeptide gồm các đơn vị $\\alpha$-amino acid liên kết với nhau qua liên kết peptide theo một trật tự nhất định.",
    "",
    "46",
    "Protein khi thuỷ phân chỉ cho hỗn hợp các $\\alpha$-amino acid gọi là protein đơn giản.",
    "Protein phức tạp là loại protein được tạo thành từ protein đơn giản và các thành phần \"phi protein\" như nucleic acid, lipid,...",
    "",
    "### 2. Tính chất vật lí",
    "Các protein dạng hình sợi như keratin (có ở tóc, móng), collagen (có ở da, sụn), myosin (có ở cơ bắp),... không tan trong nước cũng như trong các dung môi thông thường.",
    "Các protein dạng hình cầu như hemoglobin (có ở máu), albumin (có ở lòng trắng trứng) có thể tan được trong nước tạo dung dịch keo.",
    "",
    "### 3. Tính chất hoá học",
    "**a) Phản ứng thuỷ phân**",
    "Tương tự như peptide, protein bị thuỷ phân bởi acid, base hoặc enzyme. Quá trình thuỷ phân hoàn toàn protein tạo thành các $\\alpha$-amino acid.",
    "",
    "**b) Phản ứng màu**",
    "– Protein có khả năng tạo thành sản phẩm màu tím đặc trưng với thuốc thử biuret, tương tự như peptide.",
    "– Protein hình thành sản phẩm rắn màu vàng với dung dịch nitric acid đặc, một phần do phản ứng nitro hoá các đơn vị amino acid chứa vòng benzene và một phần khác do sự đông tụ protein trong môi trường acid (Hình 10.2).",
    "[Hình 10.2. Phản ứng của lòng trắng trứng với nitric acid tạo kết tủa màu vàng]",
    "",
    "**c) Phản ứng đông tụ**",
    "",
    "**Thí nghiệm: Phản ứng đông tụ và phản ứng màu của protein**",
    "*Chuẩn bị:*",
    "Hoá chất: dung dịch HNO$_3$ đặc, dung dịch lòng trắng trứng.",
    "Dụng cụ: ống nghiệm, đèn cồn.",
    "*Tiến hành:*",
    "– Cho vào hai ống nghiệm (1) và (2), mỗi ống 2 mL dung dịch lòng trắng trứng.",
    "– Đun nóng ống nghiệm (1) trên ngọn lửa đèn cồn trong 2 – 3 phút.",
    "– Thêm vài giọt dung dịch HNO$_3$ đặc vào ống nghiệm (2).",
    "*Quan sát hiện tượng xảy ra trong các ống nghiệm, giải thích.*",
    "",
    "Protein có thể bị đông tụ dưới tác dụng của nhiệt, acid, base hoặc ion kim loại nặng. Sự đông tụ này xảy ra do cấu tạo ban đầu của protein bị biến đổi.",
    "",
    "### 4. Vai trò của protein đối với sự sống",
    "Các protein khác nhau đảm nhận vai trò khác nhau, rất cần thiết cho sự sống như tham gia xây dựng tế bào, vận chuyển các chất trong cơ thể, điều hoà quá trình trao đổi chất, xúc tác cho các phản ứng hoá sinh, giúp cơ thể chống lại tác nhân có hại,...",
    "Protein có vai trò rất quan trọng cho hoạt động sống của cơ thể người. Protein là một trong những nguồn thức ăn chính bổ sung các amino acid thiết yếu và năng lượng cho cơ thể.",
    "",
    "47",
    "## II ENZYME",
    "### 1. Vai trò của enzyme trong phản ứng sinh hoá",
    "Phần lớn enzyme là những protein xúc tác cho các phản ứng hoá học và sinh hoá.",
    "Enzyme có tính chọn lọc cao, mỗi enzyme chỉ xúc tác cho một hoặc một số phản ứng nhất định.",
    "Tốc độ phản ứng có xúc tác enzyme thường nhanh hơn rất nhiều lần so với xúc tác hoá học của cùng quá trình hoá học.$^{(1)}$",
    "",
    "### 2. Ứng dụng của enzyme trong công nghệ sinh học",
    "Bên cạnh vai trò quan trọng trong cơ thể sinh vật, enzyme còn có nhiều ứng dụng trong công nghệ sinh học, như trong công nghiệp thực phẩm (sản xuất, bảo quản, chế biến thực phẩm,...); công nghiệp dược phẩm (sản xuất enzyme thay thế, enzyme vận chuyển thuốc, enzyme xúc tác một số quá trình sản xuất dược phẩm,...); kĩ thuật di truyền (enzyme tham gia vào quá trình tạo ra thông tin di truyền mới hoặc sửa đổi thông tin di truyền hiện có)$^{(2)}$;...",
    "",
    "❓ Viết ba phương trình hoá học minh hoạ cho phản ứng có enzyme làm xúc tác mà em đã học.",
    "",
    "**EM ĐÃ HỌC**",
    "- Protein là hợp chất cao phân tử được cấu tạo từ một hay nhiều chuỗi polypeptide.",
    "- Protein dạng hình sợi không tan trong nước và các dung môi thông thường, protein dạng hình cầu tan trong nước tạo dung dịch keo.",
    "- Protein bị đông tụ dưới tác dụng của nhiệt, acid, base và ion kim loại nặng; Protein tác dụng với thuốc thử biuret tạo sản phẩm có màu tím và với nitric acid tạo sản phẩm rắn màu vàng. Protein bị thuỷ phân bởi acid, base hoặc dưới tác dụng enzyme. Khi thuỷ phân hoàn toàn protein tạo thành các $\\alpha$-amino acid.",
    "- Protein có vai trò quan trọng đối với sự sống như tham gia xây dựng tế bào, điều hoà quá trình trao đổi chất,...",
    "- Phần lớn enzyme là những protein xúc tác các phản ứng hoá học và phản ứng sinh hoá. Enzyme có tính chọn lọc cao, có nhiều ứng dụng quan trọng trong công nghệ sinh học,...",
    "",
    "**EM CÓ THỂ**",
    "- Giải thích được hiện tượng đông tụ protein trong quá trình chế biến một số thực phẩm giàu protein.",
    "- Lựa chọn và sử dụng một số nguồn cung cấp protein phù hợp trong chế độ ăn uống để đảm bảo sức khoẻ.",
    "",
    "$^{(1)}$ Nguồn: Nelson, D. L., Cox, M. & Aaron, A. H. 2021. *Lehninger Principles of Biochemistry*, 8$^\\text{th}$ Edition, Macmillan Learning.",
    "$^{(2)}$ Nguồn: Palmer, T. & Bonner, P. L. 2007. *Enzymes: Biochemistry, Biotechnology, Clinical Chemistry*, Elsevier Science.",
    "",
    "48"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B11', 'Ôn tập chương 3', 51, 4, $JSON$
{
  "content": [
    "# BÀI 11 ÔN TẬP CHƯƠNG 3",
    "",
    "## I HỆ THỐNG HOÁ KIẾN THỨC",
    "",
    "| | AMINE | AMINO ACID | PEPTIDE | PROTEIN |",
    "| --- | --- | --- | --- | --- |",
    "| **Khái niệm** | Dẫn xuất của ammonia, trong đó nguyên tử hydrogen trong phân tử ammonia được thay thế bằng gốc hydrocarbon. | Hợp chất tạp chức chứa nhóm amino và nhóm carboxyl. | Cấu tạo từ các đơn vị $\\alpha$-amino acid qua liên kết peptide. | Hợp chất cao phân tử, được cấu tạo từ một hay nhiều chuỗi polypeptide. |",
    "| **Phân loại** | Theo bậc amine: Amine bậc 1, 2 và 3; Theo gốc hydrocarbon: Alkylamine và arylamine. | | | Protein đơn giản và protein phức tạp. |",
    "| **Tính chất vật lí** | Một số amine có số nguyên tử carbon nhỏ ở thể khí, tan tốt trong nước. Aniline là chất lỏng, ít tan trong nước. | Chất rắn, nhiệt độ nóng chảy cao, thường tan tốt trong nước. | | Protein dạng hình sợi không tan trong nước, protein dạng hình cầu tan được trong nước tạo dung dịch keo. |",
    "| **Tính chất hoá học** | Amine có tính base yếu.<br>Methylamine, ethylamine,... có phản ứng tạo phức với Cu(OH)$_2$.<br>Amine bậc một phản ứng với nitrous acid.<br>Aniline tham gia phản ứng thế nguyên tử H của vòng benzene dễ hơn benzene. | Có phản ứng đặc trưng của nhóm amino và nhóm carboxyl.<br>Có tính lưỡng tính.<br>Các $\\varepsilon$- và $\\omega$-amino acid tham gia phản ứng trùng ngưng tạo polyamide. | Bị thuỷ phân một phần thành các peptide nhỏ hơn và bị thuỷ phân hoàn toàn tạo thành các $\\alpha$-amino acid.<br>Tripeptide trở lên tham gia phản ứng màu biuret. | Bị thuỷ phân hoàn toàn tạo thành các $\\alpha$-amino acid.<br>Tạo sản phẩm rắn có màu vàng khi tác dụng với nitric acid đặc.<br>Bị đông tụ dưới tác dụng của nhiệt, acid, base hoặc ion kim loại nặng.<br>Tham gia phản ứng màu biuret. |",
    "| **Điều chế** | \\multicolumn{4}{l|}{Amine được điều chế bằng cách alkyl hoá ammonia hoặc khử hợp chất nitro.} |",
    "| **Ứng dụng** | \\multicolumn{4}{l|}{Aniline là nguyên liệu tổng hợp một số dược phẩm, phẩm nhuộm, polymer.<br>Protein là một trong các nguồn thức ăn chính của con người, đảm nhiệm nhiều vai trò khác nhau trong cơ thể sống, có nhiều ứng dụng khác nhau trong ngành công nghệ sinh học.} |",
    "",
    "49",
    "## II LUYỆN TẬP",
    "**Câu 1.** Trong các đồng phân cấu tạo của các amine có công thức C$_3$H$_9$N, số amine bậc hai là",
    "A. 0.          B. 1.          C. 2.          D. 3.",
    "",
    "**Câu 2.** Cho các phát biểu sau:",
    "(1) Dung dịch ethylamine và dung dịch aniline đều làm xanh giấy quỳ tím.",
    "(2) Nhỏ từ từ đến dư dung dịch methylamine vào dung dịch copper(II) sulfate, ban đầu thấy xuất hiện kết tủa màu xanh nhạt, sau đó kết tủa tan tạo thành dung dịch màu xanh lam.",
    "(3) Cho dung dịch methylamine vào ống nghiệm đựng dung dịch iron(III) chloride thấy xuất hiện kết tủa nâu đỏ.",
    "(4) Nhỏ vài giọt dung dịch aniline vào ống nghiệm đựng nước bromine thấy xuất hiện kết tủa trắng.",
    "Số phát biểu đúng là",
    "A. 1.          B. 2.          C. 3.          D. 4.",
    "",
    "**Câu 3.** Phát biểu nào sau đây **không** đúng?",
    "A. Thuỷ phân hoàn toàn polypeptide thu được các phân tử $\\alpha$-amino acid.",
    "B. Protein tác dụng với Cu(OH)$_2$ trong môi trường kiềm tạo dung dịch màu xanh lam.",
    "C. Protein có thể bị đông tụ dưới tác dụng của nhiệt, acid hoặc base.",
    "D. Protein tác dụng với dung dịch nitric acid đặc tạo thành sản phẩm rắn có màu vàng.",
    "",
    "**Câu 4.** Viết phương trình hoá học của các phản ứng xảy ra khi cho:",
    "(a) dung dịch aniline vào dung dịch HCl.",
    "(b) dung dịch alanine vào dung dịch HCl.",
    "(c) dung dịch Gly-Ala vào dung dịch NaOH dư, đun nóng.",
    "",
    "**Câu 5.** Thuỷ phân không hoàn toàn tetrapeptide Ala-Gly-Glu-Val thì có thể thu được các dipeptide và tripeptide nào?",
    "",
    "50"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B12', 'Đại cương về polymer', 53, 1, $JSON$
{
  "content": [
    "# CHƯƠNG 4",
    "# POLYMER",
    "",
    "# BÀI 12 ĐẠI CƯƠNG VỀ POLYMER",
    "",
    "**MỤC TIÊU**",
    "– Viết được công thức cấu tạo và gọi được tên của một số polymer thường gặp (polyethylene (PE), polypropylene (PP), polystyrene (PS), poly(vinyl chloride) (PVC), polybuta-1,3-diene, polyisoprene, poly(methyl methacrylate), poly(phenol formaldehyde) (PPF), capron, nylon-6,6).",
    "– Nêu được đặc điểm về tính chất vật lí (trạng thái, nhiệt độ nóng chảy, tính chất cơ học) và tính chất hoá học (phản ứng cắt mạch (tinh bột, cellulose, polyamide, polystyrene), tăng mạch (lưu hoá cao su), giữ nguyên mạch của một số polymer).",
    "– Trình bày được phương pháp trùng hợp, trùng ngưng để tổng hợp một số polymer thường gặp.",
    "",
    "❓ Các polymer tự nhiên (tinh bột, cellulose, tơ tằm,...) hay polymer tổng hợp (PE, PVC, nylon-6,6,...) được sử dụng rộng rãi trong đời sống và sản xuất. Vậy, polymer là gì và chúng có các tính chất cơ bản nào?",
    "",
    "## I KHÁI NIỆM, DANH PHÁP",
    "### 1. Khái niệm",
    "🖐 Trùng hợp ethylene tạo thành polyethylene (PE):",
    "nCH$_2$=CH$_2$ $\\xrightarrow{\\text{t}^\\circ, \\text{xt}, \\text{p}}$ –(–CH$_2$–CH$_2$–)–$_n$",
    "ethylene (monomer) polyethylene (polymer)",
    "Em hãy so sánh về thành phần nguyên tố, phân tử khối của polyethylene so với ethylene.",
    "",
    "*Polymer* là những hợp chất có phân tử khối lớn do nhiều đơn vị nhỏ (gọi là mắt xích) liên kết với nhau tạo nên.",
    "*Monomer* là những phân tử nhỏ, phản ứng với nhau để tạo nên polymer.",
    "",
    "### 2. Danh pháp",
    "Các polymer đơn giản có tên gọi chung như sau:",
    "Poly + Tên monomer",
    "(thêm ngoặc đơn nếu tên của monomer gồm hai cụm từ)",
    "",
    "51",
    "Dưới đây là công thức cấu tạo và tên gọi của một số polymer thường gặp.",
    "**Công thức cấu tạo của polymer và tên gọi**",
    "–(–CH$_2$–CH$_2$–)–$_n$ (polyethylene (PE))",
    "–(–CH$_2$–CH(Cl)–)–$_n$ (poly(vinyl chloride) (PVC))",
    "–(–CH$_2$–CH(C$_6$H$_5$)–)–$_n$ (polystyrene (PS))",
    "–(–C$_6$H$_3$(OH)–CH$_2$–)–$_n$ (poly(phenol formaldehyde) (PPF))",
    "–(–CH$_2$–CH=CH–CH$_2$–)–$_n$ (polybuta-1,3-diene)",
    "–(–NH–[CH$_2$]$_5$–CO–)–$_n$ (capron)",
    "–(–CH$_2$–C(CH$_3$)=CH–CH$_2$–)–$_n$ (polyisoprene)",
    "–(–NH–[CH$_2$]$_6$–NH–CO–[CH$_2$]$_4$–CO–)–$_n$ (nylon-6,6)",
    "",
    "❓ 1. Hãy xác định các monomer tương ứng dùng để tổng hợp các polymer sau: PE, PS và PVC.",
    "2. Viết công thức cấu tạo và gọi tên polymer được tổng hợp từ monomer sau:",
    "a) propylene;",
    "b) methyl methacrylate (CH$_2$=C(CH$_3$)–COOCH$_3$).",
    "",
    "## II TÍNH CHẤT VẬT LÍ",
    "Hầu hết polymer là những chất rắn, không bay hơi, không bị nóng chảy hoặc nóng chảy ở một khoảng nhiệt độ khá rộng. Các polymer bị nóng chảy khi đun nóng được gọi là *polymer nhiệt dẻo*. Các polymer không bị nóng chảy mà bị phân huỷ bởi nhiệt được gọi là *polymer nhiệt rắn*.",
    "Hầu hết polymer không tan trong nước, một số tan được trong dung môi hữu cơ.",
    "Tính chất vật lí của polymer thường phụ thuộc vào cấu tạo: nhiều polymer có tính dẻo (PE, PP (polypropylene),...); một số polymer có tính đàn hồi (polyisoprene, polybuta-1,3-diene,...); một số polymer khác có tính dai, bền và có thể kéo sợi (capron, nylon-6,6,...). Nhiều polymer có tính cách điện (PE, PVC,...); một số polymer có tính bán dẫn.",
    "",
    "💡 **EM CÓ BIẾT**",
    "**Một số polymer nhiệt dẻo thường gặp**",
    "Sáu polymer nhiệt dẻo phổ biến, có kí hiệu được mô tả như Hình 12.1. Các polymer này có thể tái chế được. Các kí hiệu này thường được in trên bao bì, vỏ hộp, đồ dùng,... để giúp nhận biết vật liệu polymer cũng như thuận lợi cho việc thu gom, tái chế.",
    "[Hình 12.1. Kí hiệu của sáu polymer nhiệt dẻo phổ biến: PET (1), HDPE (2), PVC (3), LDPE (4), PP (5), PS (6)]",
    "",
    "52",
    "## III TÍNH CHẤT HOÁ HỌC",
    "### 1. Phản ứng cắt mạch polymer",
    "Polymer có thể bị phân cắt thành monomer bởi nhiệt, tác nhân hoá học, sinh học,...",
    "*Ví dụ:*",
    "– Polystyrene bị nhiệt phân thu được styrene:",
    "–(–CH$_2$–CH(C$_6$H$_5$)–)–$_n$ (polystyrene) $\\xrightarrow{\\text{t}^\\circ}$ nCH$_2$=CH(C$_6$H$_5$) (styrene)",
    "– Polyamide có thể bị thuỷ phân hoàn toàn trong môi trường acid hoặc môi trường base thu được amino acid:",
    "–(–NH–[CH$_2$]$_5$–CO–)–$_n$ (capron) + nH$_2$O $\\xrightarrow{\\text{t}^\\circ, \\text{xt}}$ nH$_2$N–[CH$_2$]$_5$–COOH (6-aminohexanoic acid)",
    "– Tinh bột và cellulose có thể bị thuỷ phân hoàn toàn trong môi trường acid hoặc bởi enzyme thu được glucose:",
    "(C$_6$H$_{10}$O$_5$)$_n$ (tinh bột, cellulose) + nH$_2$O $\\xrightarrow{\\text{H}^+, \\text{t}^\\circ \\text{ hoặc enzyme}}$ nC$_6$H$_{12}$O$_6$ (glucose)",
    "",
    "### 2. Phản ứng tăng mạch polymer",
    "Khi có điều kiện thích hợp như nhiệt độ, chất xúc tác,... các mạch polymer có thể nối với nhau thành mạch dài hơn hoặc thành mạng lưới.",
    "*Ví dụ:* Khi đun cao su với lưu huỳnh thì thu được cao su lưu hoá. Ở cao su lưu hoá, các mạch polymer được nối với nhau chủ yếu bởi các cầu nối –S–S– (cầu nối disulfide).",
    "[Hình 12.2. Sơ đồ lưu hoá cao su: Mạch cao su thẳng $\\xrightarrow{\\text{nS}, \\text{t}^\\circ}$ Cao su lưu hoá với các cầu nối disulfide nối các mạch lại]",
    "",
    "### 3. Phản ứng giữ nguyên mạch polymer",
    "Polymer có thể tham gia các phản ứng hoá học mà không làm thay đổi chiều dài mạch polymer. Phản ứng có thể xảy ra ở nhóm thế đính vào mạch polymer, cộng vào liên kết đôi trong mạch polymer,...",
    "*Ví dụ:* Poly(vinyl acetate) tác dụng với dung dịch NaOH:",
    "–(–CH$_2$–CH(OCOCH$_3$)–)–$_n$ + nNaOH $\\xrightarrow{\\text{t}^\\circ}$ –(–CH$_2$–CH(OH)–)–$_n$ + nCH$_3$COONa",
    "",
    "53",
    "❓ 3. Viết phương trình hoá học của các phản ứng sau:",
    "a) Thuỷ phân hoàn toàn poly(methyl methacrylate) trong môi trường base.",
    "b) Thuỷ phân hoàn toàn nylon-6,6 trong môi trường acid.",
    "4. Hộp xốp đựng thực phẩm chế biến sẵn thường làm bằng polystyrene. Hãy tìm hiểu và cho biết có nên sử dụng các hộp này để đựng thức ăn nóng hoặc cho hộp vào lò vi sóng để hâm nóng thức ăn hay không. Tại sao?",
    "",
    "## IV PHƯƠNG PHÁP TỔNG HỢP",
    "Polymer thường được tổng hợp theo hai phương pháp phổ biến là phương pháp trùng hợp và phương pháp trùng ngưng.",
    "",
    "### 1. Phương pháp trùng hợp",
    "*Trùng hợp* là quá trình kết hợp nhiều phân tử nhỏ giống nhau hay tương tự nhau tạo thành phân tử có phân tử khối lớn (polymer).",
    "nCH$_2$=CH$_2$ (ethylene) $\\xrightarrow{\\text{xt}, \\text{t}^\\circ, \\text{p}}$ –(–CH$_2$–CH$_2$–)–$_n$ (polyethylene (PE))",
    "",
    "Các monomer tham gia phản ứng trùng hợp thường có liên kết đôi (CH$_2$=CHR) hoặc vòng như caprolactam.",
    "[Công thức cấu tạo vòng của caprolactam]",
    "",
    "### 2. Phương pháp trùng ngưng",
    "*Trùng ngưng* là quá trình kết hợp nhiều phân tử nhỏ (monomer) thành phân tử lớn (polymer) đồng thời giải phóng những phân tử nhỏ khác (thường là nước).",
    "Các monomer tham gia phản ứng trùng ngưng phải có ít nhất hai nhóm chức có khả năng phản ứng.",
    "*Ví dụ:* Nylon-6,6 thu được từ phản ứng trùng ngưng adipic acid với hexamethylenediamine:",
    "nHO–CO–[CH$_2$]$_4$–CO–OH + nH–NH–[CH$_2$]$_6$–NH–H $\\xrightarrow{\\text{t}^\\circ}$ –(–CO–[CH$_2$]$_4$–CO–NH–[CH$_2$]$_6$–NH–)–$_n$ (nylon-6,6) + 2nH$_2$O",
    "",
    "❓ 5. Cho các polymer sau: PS; nylon-6,6; PVC.",
    "Polymer nào được điều chế bằng phản ứng trùng hợp? Polymer nào được điều chế bằng phản ứng trùng ngưng?",
    "",
    "54",
    "**EM ĐÃ HỌC**",
    "- Polymer là những hợp chất có phân tử khối rất lớn do nhiều đơn vị nhỏ (gọi là mắt xích) liên kết với nhau.",
    "Monomer: là những phân tử nhỏ, phản ứng với nhau tạo thành polymer.",
    "- Các polymer thường là chất rắn, không nóng chảy hoặc nóng chảy ở một khoảng nhiệt độ khá rộng. Hầu hết polymer không tan trong nước, một số tan được trong dung môi hữu cơ. Nhiều polymer có tính dẻo (nhựa); một số polymer có tính đàn hồi (cao su); một số polymer khác thường dai, bền và dễ kéo sợi. Nhiều polymer không dẫn điện nhưng có một số polymer có tính bán dẫn.",
    "- Polymer có thể tham gia phản ứng cắt mạch, giữ nguyên mạch và tăng mạch.",
    "- Nhiều polymer thường gặp có thể được tổng hợp bằng phương pháp trùng hợp hoặc trùng ngưng.",
    "",
    "**EM CÓ THỂ**",
    "- Vận dụng các tính chất của polymer như tính đàn hồi, tính dai bền và có thể kéo sợi,... để giải thích ứng dụng của một số vật liệu polymer được tổng hợp từ các polymer đó.",
    "- Biết cách sử dụng hợp lí một số polymer theo tính chất của chúng.",
    "",
    "55"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B13', 'Vật liệu polymer', 58, 2, $JSON$
{
  "content": [
    "# BÀI 13 VẬT LIỆU POLYMER",
    "",
    "**MỤC TIÊU**",
    "– Nêu được khái niệm về chất dẻo.",
    "– Trình bày được thành phần phân tử và phản ứng điều chế polyethylene (PE), polypropylene (PP), polystyrene (PS), poly(vinyl chloride) (PVC), poly(methyl methacrylate), poly(phenol formaldehyde) (PPF).",
    "– Trình bày được ứng dụng của chất dẻo và tác hại của việc lạm dụng chất dẻo trong đời sống và sản xuất. Nêu được một số biện pháp hạn chế sử dụng chất dẻo để giảm thiểu ô nhiễm môi trường, bảo vệ sức khoẻ con người.",
    "– Nêu được khái niệm về composite.",
    "– Trình bày được ứng dụng của một số loại composite.",
    "– Nêu được khái niệm và phân loại về tơ.",
    "– Trình bày được cấu tạo, tính chất và ứng dụng một số tơ tự nhiên (bông, sợi, len lông cừu, tơ tằm,...), tơ tổng hợp (như nylon-6,6; capron; nitron hay olon,...) và tơ bán tổng hợp (như visco, cellulose acetate,...).",
    "– Nêu được khái niệm cao su, cao su tự nhiên, cao su nhân tạo.",
    "– Trình bày được đặc điểm cấu tạo, tính chất, ứng dụng của cao su tự nhiên và cao su tổng hợp (cao su buna, cao su buna-S, cao su buna-N, cao su isoprene, cao su chloroprene).",
    "– Trình bày được phản ứng điều chế cao su tổng hợp (cao su buna, cao su buna-S, cao su buna-N, cao su isoprene, cao su chloroprene).",
    "– Nêu được bản chất và ý nghĩa của quá trình lưu hoá cao su.",
    "– Nêu được khái niệm về keo dán.",
    "– Trình bày được thành phần, tính chất, ứng dụng của một số keo dán (nhựa vá săm, keo dán epoxy, keo dán poly(urea-formaldehyde)).",
    "",
    "❓ Vật liệu polymer như chất dẻo, tơ, cao su, keo dán, vật liệu composite,... được ứng dụng rộng rãi trong đời sống và sản xuất. Các vật liệu polymer này là gì? Chúng có thành phần cấu tạo như thế nào?",
    "",
    "## I CHẤT DẺO",
    "### 1. Khái niệm",
    "*Chất dẻo* là các vật liệu polymer có tính dẻo.",
    "Tính dẻo của vật liệu là tính bị biến dạng khi chịu tác dụng của nhiệt, áp lực bên ngoài và vẫn giữ được sự biến dạng đó khi thôi tác dụng.",
    "Thành phần chính của chất dẻo là polymer. Ngoài ra chất dẻo còn có chất độn, chất hoá dẻo, chất tạo màu,...",
    "",
    "### 2. Tổng hợp một số polymer dùng làm chất dẻo",
    "- Một số polymer dùng làm chất dẻo thông dụng như PE, PP, PVC, PS, poly(methyl methacrylate),... được tổng hợp bằng phương pháp trùng hợp từ các monomer tương ứng.",
    "",
    "56",
    "*Ví dụ:*",
    "nCH$_2$=CH(R) $\\xrightarrow{\\text{t}^\\circ, \\text{xt}, \\text{p}}$ –(–CH$_2$–CH(R)–)–$_n$",
    "",
    "| R | H | CH$_3$ | Cl | C$_6$H$_5$ |",
    "| --- | --- | --- | --- | --- |",
    "| **Chất dẻo** | PE | PP | PVC | PS |",
    "",
    "nCH$_2$=C(CH$_3$)–COOCH$_3$ $\\xrightarrow{\\text{t}^\\circ, \\text{xt}, \\text{p}}$ –(–CH$_2$–C(CH$_3$)(COOCH$_3$)–)–$_n$ (poly(methyl methacrylate))",
    "",
    "- Poly(phenol formaldehyde) (PPF) được điều chế từ phản ứng của formaldehyde với phenol, có mặt acid làm xúc tác:",
    "nC$_6$H$_5$OH + nHCHO $\\xrightarrow{\\text{H}^+, \\text{t}^\\circ}$ –(–C$_6$H$_3$(OH)–CH$_2$–)–$_n$ + nH$_2$O",
    "",
    "### 3. Ứng dụng của chất dẻo",
    "Chất dẻo được sử dụng rất phổ biến trên thế giới để tạo ra nhiều sản phẩm ứng dụng trong đời sống, công nghiệp, xây dựng,... Ước tính có khoảng hai phần ba lượng polymer tiêu thụ trên thế giới là từ các chất dẻo thông dụng như PE, PP, PVC, PS.",
    "",
    "| Chất dẻo | Ứng dụng |",
    "| --- | --- |",
    "| PE | Sản xuất túi nylon, bao gói, màng bọc thực phẩm, chai lọ, đồ chơi trẻ em,... |",
    "| PP | Sản xuất bao gói, hộp đựng, ống nước, chi tiết nhựa trong công nghiệp ô tô,... |",
    "| PVC | Sản xuất giày ủng, rèm nhựa, khung cửa, sàn nhựa, ống nước, vỏ cáp điện, vải giả da,... |",
    "| PS | Sản xuất bao gói thực phẩm, hộp xốp, vật liệu cách nhiệt,... |",
    "| Poly(methyl methacrylate) | Sản xuất thuỷ tinh hữu cơ dùng làm kính máy bay, kính xây dựng, kính bảo hiểm, bể cá,... |",
    "",
    "🖐 Em hãy tìm hiểu các vật dụng trong gia đình được làm từ chất dẻo. Cho biết chúng được làm từ loại chất dẻo nào.",
    "",
    "### 4. Ô nhiễm môi trường do chất dẻo và rác thải nhựa",
    "Các loại nhựa được tạo ra từ chất dẻo khi thải ra môi trường thì phải mất rất nhiều thời gian để phân huỷ (lên đến hàng trăm năm), do đó việc xử lí rác thải nhựa không đúng cách sẽ gây ô nhiễm môi trường, ảnh hưởng đến môi trường sống của con người và động vật. Đốt nhựa tạo ra các khí độc hại và làm tăng lượng khí gây hiệu ứng nhà kính. Khi chôn lấp, rác thải nhựa sẽ làm cho đất không giữ được nước, dinh dưỡng, làm chết vi sinh vật có lợi trong đất, gây tác động xấu đến sự sinh trưởng của cây trồng. Nhựa thải ra sông, hồ, đại dương,... gây ô nhiễm nguồn nước, làm mất cân bằng hệ sinh thái.",
    "",
    "💡 **EM CÓ BIẾT**",
    "Hiện nay, sản lượng nhựa sản xuất trên thế giới đạt khoảng 400 triệu tấn/năm. Như vậy, bình quân đầu người sử dụng khoảng 50 kg nhựa mỗi năm, trong đó chỉ dưới 10% được tái chế, phần còn lại bị đốt cháy, chôn lấp hoặc thải ra môi trường. Nếu tốc độ tiêu thụ nhựa tiếp tục tăng như hiện nay, ước tính vào năm 2050, lượng nhựa bình quân đầu người sẽ đạt khoảng 100 kg/người/năm.",
    "(Nguồn: Chương trình môi trường LHQ, 2022.)",
    "",
    "57",
    "Để hạn chế tình trạng ô nhiễm môi trường khi sử dụng đồ nhựa, cần thực hiện một số biện pháp như mô tả trong Hình 13.1.",
    "**MỘT SỐ BIỆN PHÁP GIẢM THIỂU RÁC THẢI NHỰA**",
    "- Tái chế và tái sử dụng đồ nhựa đã dùng",
    "- Hạn chế các loại bao bì nhựa, túi nylon",
    "- Mang theo túi đựng khi đi mua sắm",
    "- Sử dụng vật liệu phân huỷ sinh học",
    "- Phân loại rác thải tại nguồn",
    "**Hình 13.1.** Một số biện pháp để giảm thiểu rác thải nhựa",
    "",
    "🖐 Nêu một số biện pháp có thể thực hiện được trong gia đình để giảm thiểu rác thải nhựa giúp hạn chế ô nhiễm môi trường.",
    "",
    "❓ 1. Cho các polymer sau: PE, PP, poly(methyl methacrylate) và PPF. Hãy xác định polymer nào được tạo thành từ phản ứng trùng hợp, polymer nào được tạo thành từ phản ứng trùng ngưng.",
    "2. PVC được dùng làm vỏ bọc dây điện. Ứng dụng này dựa trên tính chất đặc trưng nào của PVC?",
    "",
    "## II VẬT LIỆU COMPOSITE",
    "### 1. Khái niệm",
    "*Vật liệu composite* là loại vật liệu được tổ hợp từ hai hay nhiều vật liệu khác nhau tạo nên vật liệu mới có các tính chất vượt trội so với các vật liệu ban đầu.",
    "Vật liệu composite thường bao gồm hai thành phần chính:",
    "- *Vật liệu cốt* có vai trò đảm bảo cho composite có được các đặc tính cơ học cần thiết. Hai dạng vật liệu cốt thường gặp là dạng cốt sợi (sợi thuỷ tinh, sợi hữu cơ, sợi carbon, vải,...) và dạng cốt hạt.",
    "- *Vật liệu nền* có vai trò đảm bảo cho các thành phần cốt của composite liên kết với nhau nhằm tạo tính thống nhất cho vật liệu composite. Các dạng vật liệu nền điển hình như nền hữu cơ (nhựa polymer), nền kim loại, nền gốm,...",
    "",
    "❓ 3. Một loại vật liệu composite dùng để làm vỏ tàu thuyền được chế tạo từ sợi thuỷ tinh và nhựa polyester. Hãy xác định vật liệu cốt và vật liệu nền trong vật liệu composite trên.",
    "",
    "58",
    "### 2. Ứng dụng",
    "Vật liệu composite có nhiều tính chất vượt trội nên hiện nay được dùng phổ biến để thay thế các vật liệu truyền thống trong nhiều ngành công nghiệp và đời sống.",
    "Vật liệu composite cốt sợi được dùng phổ biến để sản xuất thân, vỏ máy bay, tàu thuyền, thân xe đua, khung xe đạp, bồn chứa, ống dẫn,...",
    "Vật liệu composite cốt hạt được dùng để sản xuất gỗ nhựa, bê tông nhựa, gốm chất lượng cao,...",
    "",
    "🖐 Sưu tầm hình ảnh từ sách, báo, Internet và trình bày ứng dụng của một số loại vật liệu composite.",
    "",
    "## III TƠ",
    "### 1. Khái niệm",
    "*Tơ* là những vật liệu polymer có dạng sợi mảnh và có độ bền nhất định.",
    "Các phân tử polymer dùng làm tơ thường có mạch không phân nhánh, sắp xếp song song với nhau. Các polymer này tương đối bền với các dung môi thông thường, mềm, dai, không độc và có khả năng nhuộm màu.",
    "",
    "### 2. Phân loại",
    "Dựa vào nguồn gốc và quy trình chế tạo, tơ thường được phân loại theo sơ đồ sau:",
    "[Sơ đồ phân loại tơ:",
    "- TƠ TỰ NHIÊN: Có sẵn trong tự nhiên như bông, len, tơ tằm,...",
    "- TƠ TỔNG HỢP: Chế tạo từ các polymer tổng hợp như các tơ polyamide (capron, nylon-6,6), tơ nitron,...",
    "- TƠ BÁN TỔNG HỢP: Chế biến từ các polymer tự nhiên bằng phương pháp hoá học như tơ visco, tơ cellulose acetate,...]",
    "**Hình 13.2.** Sơ đồ phân loại tơ",
    "",
    "### 3. Một số loại tơ thường gặp",
    "**a) Tơ tự nhiên**",
    "- *Sợi bông:* là một loại tơ sợi được lấy từ quả bông. Thành phần chủ yếu của sợi bông là cellulose. Sợi bông có nhiều ưu điểm như mềm mịn, thấm hút mồ hôi tốt, thông thoáng nên vải dệt từ sợi bông (vải cotton) được sử dụng phổ biến trong ngành may mặc.",
    "- *Len:* là một loại tơ được làm từ lông một số loài động vật như cừu, dê, lạc đà,... có thành phần chính là protein. Sợi len giữ nhiệt tốt nên được dùng để dệt áo len, áo choàng, khăn len,...",
    "",
    "59",
    "- *Tơ tằm:* là loại tơ được lấy từ kén của con sâu tằm. Tơ tằm có cấu trúc là các chuỗi protein do sâu tằm tiết ra. Vải dệt từ sợi tơ tằm có độ bóng cao, mềm mại, thoáng khí, hút ẩm tốt nên được dùng phổ biến để dệt vải may trang phục vào mùa hè.",
    "",
    "**b) Tơ tổng hợp**",
    "- *Tơ nylon-6,6:*",
    "Tơ nylon-6,6 thuộc loại tơ polyamide được tổng hợp từ hai loại hợp chất đều chứa 6 nguyên tử carbon trong phân tử:",
    "–(–NH–[CH$_2$]$_6$–NH–CO–[CH$_2$]$_4$–CO–)–$_n$ (nylon-6,6)",
    "Tơ nylon-6,6 có tính dai, mềm, ít thấm nước nên được dùng để dệt vải may mặc, vải lót lốp xe, bện dây cáp, dây dù, đan lưới,...",
    "",
    "- *Tơ capron:*",
    "Tơ capron thường được tổng hợp từ phản ứng trùng hợp mở vòng $\\varepsilon$-caprolactam:",
    "n(Caprolactam) $\\xrightarrow{\\text{t}^\\circ}$ –(–NH–[CH$_2$]$_5$–CO–)–$_n$ (capron)",
    "Tơ capron dai, bền, độ đàn hồi và độ bóng cao, ít bị nhăn, có khả năng chống mài mòn.",
    "",
    "- *Tơ nitron (hay olon):*",
    "Tơ nitron được tổng hợp từ phản ứng trùng hợp vinyl cyanide (hay acrylonitrile), tạo thành polyacrylonitrile:",
    "nCH$_2$=CH(CN) $\\xrightarrow{\\text{t}^\\circ, \\text{xt}, \\text{p}}$ –(–CH$_2$–CH(CN)–)–$_n$ (polyacrylonitrile (nitron))",
    "Tơ nitron dai, bền với nhiệt và giữ nhiệt tốt nên thường được dùng để dệt vải may quần áo ấm, vải bạt, mái hiên ngoài trời, vải làm cánh buồm, sợi gia cường,...",
    "",
    "**c) Tơ bán tổng hợp**",
    "- *Tơ visco:*",
    "Tơ visco có cấu trúc phân tử giống như cellulose, được sản xuất từ các nguồn cellulose.",
    "Vải visco dai, bền, thấm mồ hôi và thoáng khí, thường dùng để dệt vải may quần áo mùa hè.",
    "",
    "60",
    "- *Tơ cellulose acetate:*",
    "Tơ cellulose acetate là một trong những loại tơ sợi bán tổng hợp được tạo ra sớm nhất. Mỗi mắt xích trong cellulose thường chứa 2 nhóm acetate ([C$_6$H$_7$O$_2$(OH)(OOCCH$_3$)$_2$]$_n$) hoặc 3 nhóm acetate ([C$_6$H$_7$O$_2$(OOCCH$_3$)$_3$]$_n$).",
    "Tơ cellulose acetate mềm, mịn, đàn hồi, thoáng khí, thấm hút mồ hôi, khô nhanh, bền màu nên được sử dụng để dệt các loại vải như sa tanh, dệt kim,...",
    "",
    "## IV CAO SU",
    "### 1. Khái niệm",
    "*Cao su* là vật liệu polymer có tính đàn hồi.",
    "Tính đàn hồi là tính biến dạng khi chịu lực tác dụng bên ngoài và trở lại dạng ban đầu khi lực đó thôi tác dụng.",
    "Có hai loại cao su: cao su tự nhiên và cao su tổng hợp.",
    "",
    "### 2. Cao su tự nhiên",
    "Cao su tự nhiên lấy từ mủ cây cao su. Cây cao su có tên khoa học là *Hevea brasiliensis*, có nguồn gốc từ Nam Mỹ, được trồng ở Việt Nam và ở nhiều nơi trên thế giới.",
    "[Hình 13.3. Mủ cây cao su]",
    "",
    "**a) Đặc điểm cấu tạo**",
    "Cao su tự nhiên là một loại polymer có chứa các mắt xích isoprene, các liên kết đôi trong mạch cao su đều ở dạng *cis*:",
    "–(–CH$_2$–C(CH$_3$)=CH–CH$_2$–)–$_n$ (dạng *cis*)",
    "",
    "**b) Tính chất và ứng dụng**",
    "Cao su tự nhiên có tính đàn hồi, không dẫn điện, chịu mài mòn, không thấm khí và nước, không tan trong nước và một số dung môi hữu cơ như ethanol,... nhưng tan trong xăng, benzene,... Cao su tự nhiên được dùng để sản xuất các loại lốp xe, băng tải, ống dẫn, gioăng, đệm, gối,...",
    "Do có liên kết đôi trong phân tử polymer nên cao su tự nhiên có thể tham gia các phản ứng cộng với H$_2$, HCl, Cl$_2$,...",
    "Khi cho cao su tác dụng với lưu huỳnh thu được cao su lưu hoá. Cao su sau khi lưu hoá có các cầu nối disulfide tạo mạng lưới không gian nên có các tính chất lí hoá nổi trội hơn so với cao su ban đầu,...",
    "",
    "61",
    "### 3. Cao su tổng hợp",
    "Cao su tổng hợp là loại vật liệu polymer có tính chất đàn hồi tương tự cao su tự nhiên, được điều chế bằng phản ứng trùng hợp.",
    "Có nhiều loại cao su tổng hợp, trong đó có một số loại thông dụng sau đây:",
    "",
    "**a) Cao su buna**",
    "Trùng hợp buta-1,3-diene có mặt sodium, thu được cao su buna:",
    "nCH$_2$=CH–CH=CH$_2$ $\\xrightarrow{\\text{Na}, \\text{t}^\\circ, \\text{p}}$ –(–CH$_2$–CH=CH–CH$_2$–)–$_n$",
    "",
    "**b) Cao su buna-S, buna-N**",
    "Khi trùng hợp buta-1,3-diene với styrene (C$_6$H$_5$CH=CH$_2$) thu được cao su buna-S, trùng hợp buta-1,3-diene với acrylonitrile (CH$_2$=CH–CN) thu được cao su buna-N:",
    "nCH$_2$=CH–CH=CH$_2$ + nCH$_2$=CH(R) $\\xrightarrow{\\text{t}^\\circ, \\text{xt}, \\text{p}}$ –(–CH$_2$–CH=CH–CH$_2$–CH$_2$–CH(R)–)–$_n$",
    "R = –C$_6$H$_5$ : cao su buna-S",
    "R = –CN : cao su buna-N",
    "",
    "**c) Cao su isoprene**",
    "Khi trùng hợp isoprene có mặt xúc tác, thu được cao su isoprene:",
    "nCH$_2$=C(CH$_3$)–CH=CH$_2$ (isoprene) $\\xrightarrow{\\text{t}^\\circ, \\text{xt}, \\text{p}}$ –(–CH$_2$–C(CH$_3$)=CH–CH$_2$–)–$_n$ (cao su isoprene)",
    "",
    "**d) Cao su chloroprene**",
    "Khi trùng hợp chloroprene có mặt xúc tác, thu được cao su chloroprene:",
    "nCH$_2$=C(Cl)–CH=CH$_2$ (chloroprene) $\\xrightarrow{\\text{t}^\\circ, \\text{xt}, \\text{p}}$ –(–CH$_2$–C(Cl)=CH–CH$_2$–)–$_n$ (cao su chloroprene)",
    "Cao su tổng hợp có độ đàn hồi tốt, độ bền cao, khả năng chống lão hoá tốt, giá thành thấp nên được ứng dụng phổ biến trong nhiều lĩnh vực như xây dựng, giao thông (lốp xe, đệm chống va đập, gối cầu, khe co giãn), máy móc công nghiệp (băng tải, dây chuyền động,...), y tế (găng tay nitrile),...",
    "",
    "🖐 Hãy kể tên các vật dụng trong gia đình được làm từ cao su. Em hãy tìm hiểu và cho biết chúng được làm từ cao su tự nhiên hay cao su tổng hợp.",
    "",
    "💡 **EM CÓ BIẾT**",
    "Cao su tổng hợp phổ biến nhất hiện nay là cao su buna-S (SBR). SBR được tổng hợp bằng phản ứng trùng hợp styrene với buta-1,3-diene (tỉ lệ khoảng 1:3). Sản lượng hàng năm của SBR gấp hơn hai lần cao su tự nhiên, trong đó khoảng hai phần ba được sử dụng để sản xuất lốp xe.",
    "",
    "62",
    "## V KEO DÁN TỔNG HỢP",
    "### 1. Khái niệm",
    "*Keo dán* là loại vật liệu có khả năng kết dính bề mặt của hai vật liệu rắn với nhau, mà không làm biến đổi bản chất các vật liệu được kết dính.",
    "Bản chất kết dính của keo dán là tạo ra lớp màng mỏng bám chắc vào hai mảnh vật liệu để giúp chúng kết dính lại được với nhau.",
    "",
    "### 2. Một số loại keo dán thông dụng",
    "**a) Nhựa vá săm**",
    "Nhựa vá săm là dung dịch dạng keo của cao su được hoà tan trong các dung môi hữu cơ như xăng, toluene, xylene,... Nhựa vá săm dùng để vá chỗ thủng của săm hoặc lốp.",
    "[Hình 13.4. Nhựa vá săm]",
    "",
    "**b) Keo dán epoxy**",
    "Keo dán epoxy gồm hai thành phần: thành phần chính có cấu tạo là hợp chất hữu cơ chứa hai nhóm epoxy ở hai đầu.",
    "*Ví dụ:* [Công thức cấu tạo của một loại nhựa epoxy]",
    "Thành phần thứ hai gọi là chất đóng rắn, thường là các amine, chẳng hạn như H$_2$NCH$_2$CH$_2$NHCH$_2$CH$_2$NH$_2$.",
    "[Hình 13.5. Keo dán epoxy]",
    "Để tạo keo dán cần trộn hai thành phần trên với nhau. Các nhóm amine sẽ phản ứng với các nhóm epoxy tạo ra polymer mạng không gian gắn kết hai bề mặt vật cần dán lại.",
    "Keo dán epoxy dùng để dán các vật liệu kim loại, gỗ, thuỷ tinh, chất dẻo, bê tông,... trong các ngành công nghiệp sản xuất ô tô, máy bay, xây dựng và trong đời sống hàng ngày.",
    "",
    "**c) Keo dán poly(urea-formaldehyde)**",
    "Keo dán poly(urea-formaldehyde) được điều chế từ urea và formaldehyde:",
    "nH$_2$N–CO–NH$_2$ (urea) + nCH$_2$=O (formaldehyde) $\\xrightarrow{\\text{xt}, \\text{t}^\\circ}$ –(–NH–CO–NH–CH$_2$–)–$_n$ (poly(urea-formaldehyde)) + nH$_2$O",
    "Keo dán poly(urea-formaldehyde) được dùng làm chất kết dính trong gỗ ván ép, chất dẻo,... Khi sử dụng keo dán poly(urea-formaldehyde) cần bổ sung thêm chất đóng rắn như ammonium chloride, oxalic acid,... để tạo polymer mạng không gian.",
    "",
    "63",
    "**EM ĐÃ HỌC**",
    "- *Chất dẻo* là các vật liệu polymer có tính dẻo. Tính dẻo của vật liệu là tính bị biến dạng khi chịu tác dụng của nhiệt, áp lực bên ngoài và vẫn giữ được sự biến dạng đó khi thôi tác dụng.",
    "- Chất dẻo được ứng dụng rộng rãi trong đời sống và sản xuất. Lạm dụng và xử lí chất dẻo không đúng cách là nguyên nhân gây ô nhiễm môi trường.",
    "- *Vật liệu composite* là loại vật liệu được tổ hợp từ hai hay nhiều vật liệu khác nhau tạo nên vật liệu mới có các tính chất vượt trội so với các vật liệu ban đầu.",
    "- *Tơ* là những vật liệu polymer có dạng sợi mảnh và có độ bền nhất định.",
    "- *Cao su* là vật liệu polymer có tính đàn hồi.",
    "- *Keo dán* là vật liệu có khả năng kết dính bề mặt của hai vật liệu rắn với nhau mà không làm biến đổi bản chất các vật liệu được kết dính.",
    "- Vật liệu composite, tơ, cao su, keo dán được ứng dụng rộng rãi trong đời sống và sản xuất.",
    "",
    "**EM CÓ THỂ**",
    "- Nhận biết được một số vật dụng trong gia đình được làm bằng vật liệu polymer như chất dẻo, vật liệu composite, tơ, cao su, keo dán,...",
    "- Biết cách phân loại để tái chế rác thải nhựa theo tính chất của chúng.",
    "- Biết được các tác hại của rác thải nhựa, từ đó có biện pháp để giảm thiểu rác thải nhựa.",
    "",
    "64"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B14', 'Ôn tập chương 4', 67, 3, $JSON$
{
  "content": [
    "# BÀI 14 ÔN TẬP CHƯƠNG 4",
    "",
    "## I HỆ THỐNG HOÁ KIẾN THỨC",
    "*Polymer* là những hợp chất có phân tử khối lớn do nhiều đơn vị nhỏ (gọi là mắt xích) liên kết với nhau.",
    "Các phản ứng đặc trưng của polymer: cắt mạch, tăng mạch, giữ nguyên mạch.",
    "Polymer thường được tổng hợp từ phản ứng trùng hợp hoặc phản ứng trùng ngưng.",
    "Một số vật liệu polymer phổ biến:",
    "",
    "| Vật liệu polymer | Thành phần, nguồn gốc | Tính chất |",
    "| --- | --- | --- |",
    "| **Chất dẻo** | PE | Trùng hợp ethylene | Có tính dẻo |",
    "| | PP | Trùng hợp propylene | |",
    "| | PVC | Trùng hợp vinyl chloride | |",
    "| | PS | Trùng hợp styrene | |",
    "| | Poly(methyl methacrylate) | Trùng hợp methyl methacrylate | |",
    "| | Poly(phenol formaldehyde) | Trùng ngưng phenol với formaldehyde | |",
    "| **Vật liệu composite** | Vật liệu nền và vật liệu cốt. | Tính chất tốt hơn các vật liệu riêng rẽ ban đầu. |",
    "| **Tơ** | Tơ tự nhiên | Có nguồn gốc từ thiên nhiên: sợi bông, len, tơ tằm,... | Có dạng sợi mảnh, dai bền,... |",
    "| | Tơ bán tổng hợp | Chế biến từ polymer tự nhiên bằng phương pháp hoá học: tơ visco, tơ cellulose acetate. | |",
    "| | Tơ tổng hợp | Chế biến từ các polymer tổng hợp như: tơ capron, nylon-6,6, tơ nitron. | |",
    "| **Cao su** | Cao su tự nhiên | Được lấy từ mủ cây cao su. | Có tính đàn hồi. |",
    "| | Cao su nhân tạo | Tổng hợp bằng phương pháp hoá học: cao su buna, buna-S, buna-N, cao su chloroprene, cao su isoprene,... | |",
    "| **Keo dán** | Nhựa vá săm | Cao su hoà tan trong dung môi hữu cơ. | Có khả năng kết dính bề mặt của hai vật liệu rắn với nhau. |",
    "| | Keo epoxy | Polymer tạo thành từ nhựa epoxy và một số amine. | |",
    "| | Keo poly(urea-formaldehyde) | Polymer tạo thành do phản ứng trùng ngưng giữa urea và formaldehyde. | |",
    "",
    "65",
    "## II LUYỆN TẬP",
    "**Câu 1.** Chất dẻo nào sau đây chứa chlorine?",
    "A. PE.          B. PVC.          C. PS.          D. PPF.",
    "",
    "**Câu 2.** Trùng hợp styrene thu được polymer có kí hiệu viết tắt là",
    "A. PE.          B. PP.          C. PVC.          D. PS.",
    "",
    "**Câu 3.** PE là một polymer thông dụng, dùng làm chất dẻo (chất dẻo chứa PE chiếm gần 1/3 tổng lượng chất dẻo được sản xuất hàng năm). Trong đời sống, PE được dùng làm màng bọc thực phẩm, túi nylon, bao gói, chai lọ đựng hoá mĩ phẩm,...",
    "PE được điều chế từ monomer nào sau đây?",
    "A. Ethylene.          B. Propylene.          C. Styrene.          D. Vinyl chroride.",
    "",
    "**Câu 4.** Viết phương trình hoá học của phản ứng điều chế polymer từ các monomer sau:",
    "a) CH$_2$=CH–CH$_3$;",
    "b) H$_2$N–[CH$_2$]$_5$–COOH;",
    "c) HOOC–[CH$_2$]$_4$–COOH và H$_2$N–[CH$_2$]$_6$–NH$_2$.",
    "",
    "**Câu 5.** Cao su buna-S được sử dụng phổ biến làm lốp xe, băng tải,... Cao su buna-S được tổng hợp từ các chất nào sau đây?",
    "A. CH$_2$=CH$_2$ và C$_6$H$_5$–CH=CH$_2$.",
    "B. CH$_2$=CH–CH=CH$_2$ và lưu huỳnh.",
    "C. CH$_2$=CH–CH$_2$–CH$_3$ và C$_6$H$_5$–CH=CH$_2$.",
    "D. CH$_2$=CH–CH=CH$_2$ và C$_6$H$_5$–CH=CH$_2$.",
    "",
    "**Câu 6.** Keo siêu dính 502 là một loại keo được dùng phổ biến trong đời sống để kết dính các bề mặt vật liệu như gỗ, nhựa, da,... Thành phần của keo 502 có chứa methyl cyanoacrylate (CH$_2$=C(CN)COOCH$_3$). Sau khi dán, hơi ẩm trong không khí giúp cho phản ứng trùng hợp methyl cyanoacrylate xảy ra, tạo thành polymer dạng màng mỏng kết dính các vật liệu lại với nhau. Viết phương trình hoá học của phản ứng trùng hợp xảy ra trong quá trình dán keo 502.",
    "",
    "66"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C5' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B15', 'Thế điện cực và nguồn điện hoá học', 69, 1, $JSON$
{
  "content": [
    "# CHƯƠNG 5",
    "# PIN ĐIỆN VÀ ĐIỆN PHÂN",
    "",
    "# BÀI 15 THẾ ĐIỆN CỰC VÀ NGUỒN ĐIỆN HOÁ HỌC",
    "",
    "**MỤC TIÊU**",
    "– Mô tả được cặp oxi hoá – khử của kim loại.",
    "– Nêu được giá trị thế điện cực chuẩn là đại lượng đánh giá khả năng khử giữa các dạng khử, khả năng oxi hoá giữa các dạng oxi hoá trong điều kiện chuẩn.",
    "– Sử dụng bảng giá trị thế điện cực chuẩn để: so sánh được tính khử, tính oxi hoá giữa các cặp oxi hoá – khử; Dự đoán được chiều hướng xảy ra phản ứng giữa hai cặp oxi hoá – khử; tính được sức điện động của pin điện hoá tạo bởi hai cặp oxi hoá – khử.",
    "– Nêu được cấu tạo, nguyên tắc hoạt động của pin Galvani, ưu nhược điểm chính của một số loại pin khác như acquy; pin nhiên liệu; pin Mặt Trời;...",
    "– Lắp ráp được pin đơn giản (pin đơn giản: 2 thanh kim loại khác nhau cắm vào quả chanh, lọ nước muối,...) và đo được sức điện động của pin.",
    "",
    "❓ Pin điện hoá là nguồn năng lượng được sử dụng phổ biến trong nhiều thiết bị như đèn pin, điện thoại, laptop, máy tính cầm tay, đồng hồ, xe đạp điện, xe máy điện, ô tô, máy bay không người lái,... Pin điện hoá có cấu tạo như thế nào? Phản ứng oxi hoá – khử đóng vai trò gì trong hoạt động của pin điện hoá? Làm thế nào để lắp ráp được một số pin điện hoá đơn giản?",
    "[Hình 15.1. Một số loại pin điện hoá]",
    "",
    "## I CẶP OXI HOÁ – KHỬ",
    "🖐 Nhúng một thanh kẽm vào cốc đựng dung dịch copper(II) sulfate (Hình 15.2a), sau một thời gian nhấc thanh kẽm ra thì thấy xuất hiện một lớp đồng màu đỏ bám vào thanh kẽm (Hình 15.2b).",
    "1. Viết phương trình hoá học dạng ion rút gọn của phản ứng oxi hoá – khử xảy ra trong thí nghiệm.",
    "2. Viết quá trình oxi hoá nguyên tử Zn và quá trình khử ion Cu$^{2+}$. Chỉ ra dạng oxi hoá và dạng khử trong mỗi quá trình.",
    "3. Biểu diễn dạng oxi hoá và dạng khử của mỗi nguyên tố trên như sau: dạng oxi hoá/dạng khử.",
    "[Hình 15.2. Thí nghiệm phản ứng của kẽm với dung dịch copper(II) sulfate: (a) Thanh Zn nhúng trong dd CuSO$_4$; (b) Lớp Cu bám trên thanh Zn]",
    "",
    "67",
    "Nguyên tử kim loại có thể nhường electron để trở thành cation kim loại. Ngược lại, cation kim loại có thể nhận electron để trở thành nguyên tử kim loại.",
    "*Ví dụ:*",
    "Al$^{3+}$ + 3e $\\rightleftharpoons$ Al;",
    "Zn$^{2+}$ + 2e $\\rightleftharpoons$ Zn;",
    "Cu$^{2+}$ + 2e $\\rightleftharpoons$ Cu.",
    "Các nguyên tử kim loại (Al, Zn, Cu,...) đóng vai trò chất khử, các ion kim loại (Al$^{3+}$, Zn$^{2+}$, Cu$^{2+}$,...) đóng vai trò chất oxi hoá.",
    "Dạng oxi hoá và dạng khử tương ứng của cùng một nguyên tố kim loại tạo nên cặp oxi hoá – khử của kim loại. *Ví dụ:* Al$^{3+}$/Al; Zn$^{2+}$/Zn; Cu$^{2+}$/Cu.",
    "Tổng quát, dạng oxi hoá (M$^{n+}$) và dạng khử (M) của cùng một kim loại tạo nên cặp oxi hoá – khử M$^{n+}$/M, giữa chúng có mối quan hệ:",
    "M$^{n+}$ (dạng oxi hoá) + ne $\\rightleftharpoons$ M (dạng khử)",
    "",
    "💡 **EM CÓ BIẾT**",
    "Trong cặp oxi hoá – khử của kim loại, dạng oxi hoá và dạng khử có thể tồn tại ở dạng ion đơn nguyên tử, ion đa nguyên tử hoặc dạng phân tử, ví dụ: Fe$^{3+}$/Fe$^{2+}$; [Ag(NH$_3$)$_2$]$^+$/Ag; AgCl/Ag;...",
    "Các nguyên tố phi kim cũng có các cặp oxi hoá – khử tương ứng, ví dụ: 2H$^+$/H$_2$; Cl$_2$/2Cl$^-$;...",
    "",
    "❓ 1. Viết bán phản ứng hoặc cặp oxi hoá – khử còn thiếu trong bảng dưới đây vào vở:",
    "",
    "| Bán phản ứng | Cặp oxi hoá – khử | Bán phản ứng | Cặp oxi hoá – khử |",
    "| --- | --- | --- | --- |",
    "| Na$^+$ + 1e $\\rightleftharpoons$ Na | ? | ? | 2H$^+$/H$_2$ |",
    "| ? | Al$^{3+}$/Al | Ag$^+$ + 1e $\\rightleftharpoons$ Ag | ? |",
    "| Fe$^{2+}$ + 2e $\\rightleftharpoons$ Fe | ? | ? | Au$^{3+}$/Au |",
    "",
    "2. Cho đinh sắt (iron) tác dụng với dung dịch hydrochloric acid, thu được muối iron(II) chloride và khí hydrogen.",
    "a) Viết phương trình hoá học của phản ứng ở dạng ion thu gọn.",
    "b) Xác định các cặp oxi hoá – khử trong phản ứng trên.",
    "",
    "## II THẾ ĐIỆN CỰC CHUẨN",
    "### 1. Điện cực",
    "Ứng với mỗi cặp oxi hoá – khử có thể thiết lập một điện cực, tại đó tồn tại cân bằng giữa dạng oxi hoá và dạng khử.",
    "*Ví dụ:*",
    "Đối với cặp Zn$^{2+}$/Zn, thiết lập được điện cực kẽm bằng cách cho thanh Zn tiếp xúc trực tiếp với dung dịch muối chứa ion Zn$^{2+}$ (Hình 15.3 a).",
    "",
    "68",
    "Tương tự, đối với cặp Cu$^{2+}$/Cu cũng thiết lập được điện cực đồng như Hình 15.3 b.",
    "Tại ranh giới giữa kim loại và dung dịch chất điện li của mỗi điện cực tồn tại cân bằng:",
    "Zn$^{2+}$ + 2e $\\rightleftharpoons$ Zn;",
    "Cu$^{2+}$ + 2e $\\rightleftharpoons$ Cu",
    "Điện cực kim loại có nồng độ ion kim loại bằng 1 M và nhiệt độ thường được chọn là 25 $^\\circ$C (298 K) được gọi là điện cực ở điều kiện chuẩn.",
    "[Hình 15.3. Sơ đồ điện cực: a) điện cực kẽm; b) điện cực đồng]",
    "",
    "💡 **EM CÓ BIẾT**",
    "**Điện cực hydrogen chuẩn**",
    "Điện cực hydrogen chuẩn gồm một lá Pt (hấp phụ bão hoà khí hydrogen với áp suất 1 bar), nhúng trong dung dịch acid có nồng độ ion H$^+$ bằng 1 M.",
    "Tại ranh giới giữa lá Pt (có hấp phụ H$_2$) và dung dịch chất điện li tồn tại cân bằng:",
    "2H$^+$ + 2e $\\rightleftharpoons$ H$_2$.",
    "[Hình 15.4. Minh hoạ điện cực hydrogen chuẩn]",
    "",
    "### 2. Thế điện cực chuẩn",
    "Mỗi điện cực ở điều kiện chuẩn có một đại lượng đặc trưng về điện thế, gọi là thế điện cực chuẩn.",
    "Thế điện cực chuẩn gắn liền với cặp oxi hoá – khử tương ứng nên thường được kí hiệu là E$^\\circ_{\\text{oxi hoá/khử}}$ và thường có đơn vị là volt (vôn).",
    "Thực nghiệm không đo được giá trị tuyệt đối của thế điện cực chuẩn nhưng đo được sự chênh lệch điện thế giữa hai điện cực ở điều kiện chuẩn.",
    "Do vậy, bằng cách quy ước thế điện cực chuẩn của hydrogen bằng 0:",
    "2H$^+$ + 2e $\\rightleftharpoons$ H$_2$",
    "E$^\\circ_{\\text{2H}^+/\\text{H}_2}$ = 0 V",
    "Từ đó, thế điện cực chuẩn của một điện cực khác được xác định bằng thực nghiệm trên cơ sở đo sự chênh lệch điện thế giữa điện cực đó với điện cực hydrogen chuẩn.",
    "*Ví dụ:*",
    "Zn$^{2+}$ + 2e $\\rightleftharpoons$ Zn",
    "E$^\\circ_{\\text{Zn}^{2+}/\\text{Zn}}$ = – 0,762 V",
    "Cu$^{2+}$ + 2e $\\rightleftharpoons$ Cu",
    "E$^\\circ_{\\text{Cu}^{2+}/\\text{Cu}}$ = +0,340 V",
