    "ZnSO$_4$ + H$_2$O $\\xrightarrow{\\text{đpdd}}$ Zn + $\\frac{1}{2}$O$_2$ + H$_2$SO$_4$",
    "Các kim loại mạnh như Na, K, Mg, Ca, Al,... được sản xuất bằng phương pháp điện phân nóng chảy (đpnc) hợp chất ion của chúng.",
    "*Ví dụ:* Trong công nghiệp, nhôm được sản xuất từ quặng bauxite theo hai giai đoạn chính:",
    "*Giai đoạn 1:* Tinh chế quặng bauxite",
    "Quặng bauxite (thành phần chính Al$_2$O$_3$$\\cdot$2H$_2$O) thường lẫn tạp chất. Sau khi loại bỏ tạp chất bằng phương pháp hoá học thu được Al$_2$O$_3$.",
    "*Giai đoạn 2:* Điện phân Al$_2$O$_3$ nóng chảy",
    "Do Al$_2$O$_3$ có nhiệt độ nóng chảy rất cao (2 050 $^\\circ$C) nên Al$_2$O$_3$ được trộn cùng với cryolite (Na$_3$AlF$_6$) để tạo thành hỗn hợp nóng chảy ở gần 1 000 $^\\circ$C. Giải pháp này giúp tiết kiệm nhiều năng lượng, đồng thời tạo ra chất lỏng vừa có tính dẫn điện tốt, vừa nổi lên trên Al lỏng để ngăn cách Al lỏng với không khí.",
    "Thùng điện phân có cathode là tấm than chì ở dưới đáy thùng, anode là những tấm than chì có thể di chuyển theo phương thẳng đứng (Hình 16.4).",
    "Ở anode xảy ra quá trình oxi hoá O$^{2-}$ thành O$_2$:",
    "2O$^{2-}$ $\\longrightarrow$ O$_2$ + 4e",
    "Ở cathode xảy ra quá trình khử Al$^{3+}$ thành Al:",
    "Al$^{3+}$ + 3e $\\longrightarrow$ Al",
    "Phương trình hoá học của phản ứng điện phân:",
    "2Al$_2$O$_3$ $\\xrightarrow{\\text{đpnc}}$ 4Al + 3O$_2$",
    "Khí O$_2$ tạo thành ở nhiệt độ cao, đốt cháy dần điện cực anode than chì thành CO và CO$_2$. Do vậy, trong quá trình điện phân phải hạ thấp dần các điện cực anode vào thùng điện phân.",
    "[Hình 16.4. Sơ đồ thùng điện phân Al$_2$O$_3$ nóng chảy: Anode bằng than chì nhúng vào hỗn hợp Aluminium oxide và cryolite nóng chảy. Cathode bằng than chì ở đáy. Nhôm nóng chảy ở dưới cùng, có cửa tháo nhôm nóng chảy.]",
    "",
    "82",
    "### 2. Tinh chế kim loại",
    "Từ nguồn kim loại thô (kim loại phế liệu hoặc sau quá trình nhiệt luyện, thuỷ luyện), các kim loại như Zn, Ni, Co, Cu, Ag, Au,... được tinh chế bằng phương pháp điện phân.",
    "Quá trình tinh chế được thực hiện bằng cách điện phân dung dịch chất tan (muối hoặc phức chất) của kim loại đó với anode làm bằng kim loại thô tương ứng.",
    "*Ví dụ:* Trong công nghiệp, đồng phế liệu hoặc đồng thô được tinh chế bằng phương pháp điện phân.",
    "Bình điện phân tinh chế đồng chứa dung dịch muối CuSO$_4$ trong dung dịch H$_2$SO$_4$, anode bằng đồng thô và cathode là đồng tinh khiết.",
    "Tại anode: Cu bị oxi hoá thành ion Cu$^{2+}$ đi vào dung dịch:",
    "Cu $\\longrightarrow$ Cu$^{2+}$ + 2e",
    "Do vậy, anode dần bị hoà tan.",
    "Tại cathode: Cu$^{2+}$ bị khử thành Cu bám trên cathode:",
    "Cu$^{2+}$ + 2e $\\longrightarrow$ Cu",
    "Quá trình điện phân này được coi như là sự chuyển dời kim loại Cu từ anode (ở dạng đồng thô) về cathode (ở dạng đồng tinh khiết).",
    "Kết thúc quá trình điện phân thu được đồng tinh khiết ở cathode.",
    "",
    "### 3. Mạ điện",
    "Phương pháp điện phân được sử dụng trong mạ điện, trong đó ion kim loại bị khử, tạo thành lớp kim loại rắn bao phủ trên bề mặt kim loại cần mạ nhằm trang trí bề mặt hoặc chống sự ăn mòn.",
    "Trong kĩ thuật mạ điện, các kim loại mạ thường là chromium, nickel, đồng, vàng, bạc, platinum,...",
    "Bình mạ điện chứa dung dịch muối của kim loại mạ, vật cần mạ và thanh kim loại mạ.",
    "*Ví dụ:* Quá trình điện phân để mạ đồng lên một chiếc chìa khoá được mô tả ở Hình 16.5. Trong quá trình điện phân, thanh kim loại đóng vai trò là anode, chiếc chìa khoá đóng vai trò là cathode và dung dịch điện phân là dung dịch CuSO$_4$. Các quá trình xảy ra ở các điện cực tương tự như quá trình điện phân tinh chế đồng với anode tan. Độ dày của lớp mạ tỉ lệ thuận với cường độ dòng điện chạy qua dung dịch điện phân và thời gian mạ.",
    "[Hình 16.5. Sơ đồ điện phân mạ đồng lên chìa khoá: Anode là thanh Cu, Cathode là chiếc chìa khoá. Nhúng trong dung dịch.]",
    "",
    "83",
    "❓ 2. a) Liệt kê một số đồ vật được mạ kim loại và nêu tác dụng của việc mạ đó.",
    "b) Kể tên một số kim loại được sản xuất bằng phương pháp điện phân.",
    "",
    "**EM ĐÃ HỌC**",
    "- Thứ tự điện phân:",
    "Tại anode, chất khử mạnh hơn bị oxi hoá trước.",
    "Tại cathode, chất oxi hoá mạnh hơn bị khử trước.",
    "- Trong thực tiễn, phương pháp điện phân được sử dụng để sản xuất kim loại, tinh chế kim loại, mạ điện.",
    "- Trong công nghiệp, nhôm được sản xuất bằng cách điện phân aluminium oxide nóng chảy.",
    "- Quá trình tinh chế đồng được thực hiện bằng phương pháp điện phân với anode bằng đồng thô.",
    "",
    "**EM CÓ THỂ**",
    "- Vận dụng được kiến thức về điện phân để giải thích một số quá trình sản xuất kim loại, tinh chế kim loại, mạ điện.",
    "- Hiểu được nguyên tắc của các quá trình sản xuất nước Javel bằng phương pháp điện phân.",
    "",
    "84"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C5' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B17', 'Ôn tập chương 5', 87, 3, $JSON$
{
  "content": [
    "# BÀI 17 ÔN TẬP CHƯƠNG 5",
    "",
    "## I HỆ THỐNG HOÁ KIẾN THỨC",
    "",
    "| CẶP OXI HOÁ – KHỬ CỦA KIM LOẠI |",
    "| --- |",
    "| Dạng oxi hoá (M$^{n+}$) và dạng khử (M) của cùng một kim loại tạo nên cặp oxi hoá – khử, giữa chúng có mối quan hệ: M$^{n+}$ + ne $\\rightleftharpoons$ M |",
    "| **THẾ ĐIỆN CỰC CHUẨN** |",
    "| **Khái niệm**<br>Thế điện cực chuẩn là đại lượng đánh giá khả năng khử giữa các dạng khử và khả năng oxi hoá giữa các dạng oxi hoá ở điều kiện chuẩn.<br>**Ý nghĩa**<br>• Giá trị thế điện cực chuẩn của cặp oxi hoá – khử M$^{n+}$/M càng lớn thì tính oxi hoá của ion M$^{n+}$ càng mạnh và tính khử của kim loại M càng yếu và ngược lại.<br>• Phản ứng hoá học giữa hai cặp oxi hoá – khử xảy ra theo chiều: Chất oxi hoá của cặp oxi hoá – khử có thế điện cực chuẩn lớn hơn oxi hoá chất khử của cặp oxi hoá – khử có thế điện cực chuẩn nhỏ hơn. |",
    "| **NGUỒN ĐIỆN HOÁ HỌC** |",
    "| **Pin Galvani**<br>• Pin Galvani có cấu tạo gồm hai điện cực, mỗi điện cực ứng với một cặp oxi hoá – khử và thường nối với nhau qua cầu muối.<br>• Ở anode xảy ra quá trình oxi hoá, còn ở cathode xảy ra quá trình khử.<br>• Sức điện động chuẩn của pin: E$^\\circ_{\\text{pin}}$ = E$^\\circ_{\\text{cathode}}$ – E$^\\circ_{\\text{anode}}$<br>**Một số nguồn điện khác**<br>• Acquy thuộc loại pin sạc, được sử dụng phổ biến trong nhiều loại ô tô.<br>• Pin nhiên liệu và pin Mặt Trời là những nguồn năng lượng sạch, tiềm năng. |",
    "| **ĐIỆN PHÂN** |",
    "| **Thứ tự điện phân**<br>• Tại anode, chất khử mạnh hơn bị oxi hoá trước.<br>• Tại cathode, chất oxi hoá mạnh hơn bị khử trước.<br>**Ứng dụng**<br>• Nhôm được sản xuất bằng phương pháp điện phân nóng chảy:<br>2Al$_2$O$_3$ $\\xrightarrow{\\text{đpnc}}$ 4Al + 3O$_2$<br>• Đồng được tinh luyện bằng phương pháp điện phân với anode bằng đồng thô.<br>• Mạ điện được sử dụng để trang trí bề mặt hoặc bảo vệ kim loại khỏi sự ăn mòn. |",
    "",
    "85",
    "## II LUYỆN TẬP",
    "**Câu 1.** Xét các cặp oxi hoá – khử sau:",
    "",
    "| Cặp oxi hoá – khử | Al$^{3+}$/Al | Ag$^+$/Ag | Mg$^{2+}$/Mg | Fe$^{2+}$/Fe |",
    "| --- | --- | --- | --- | --- |",
    "| Thế điện cực chuẩn (V) | –1,676 | +0,799 | –2,356 | –0,44 |",
    "",
    "a) Kim loại có tính khử mạnh nhất, yếu nhất lần lượt là",
    "A. Mg, Ag.          B. Al, Ag.          C. Al, Fe.          D. Mg, Fe.",
    "b) Số kim loại khử được ion H$^+$ thành khí H$_2$ ở điều kiện chuẩn là",
    "A. 1.          B. 2.          C. 3.          D. 4.",
    "c) Số kim loại khử được ion Ag$^+$ thành Ag ở điều kiện chuẩn là",
    "A. 4.          B. 1.          C. 3.          D. 2.",
    "",
    "**Câu 2.** Cho pin điện hoá tạo bởi hai cặp oxi hoá – khử ở điều kiện chuẩn: Pb$^{2+}$/Pb và Zn$^{2+}$/Zn với thế điện cực chuẩn tương ứng là –0,126 V và –0,762 V.",
    "a) Xác định anode, cathode của pin điện.",
    "b) Viết quá trình xảy ra ở mỗi điện cực và phương trình hoá học của phản ứng xảy ra khi pin hoạt động.",
    "c) Xác định sức điện động chuẩn của pin.",
    "",
    "**Câu 3.** Sức điện động chuẩn của pin điện hoá gồm hai điện cực M$^{2+}$/M và Ag$^+$/Ag bằng 1,056 V.",
    "Trong số các kim loại Cu, Fe, Ni, Sn:",
    "a) Hãy cho biết kim loại nào phù hợp với M.",
    "b) Lựa chọn kim loại M để pin điện hoá có sức điện động chuẩn lớn nhất.",
    "Cho biết:",
    "",
    "| Cặp oxi hoá – khử | Fe$^{2+}$/Fe | Ni$^{2+}$/Ni | Sn$^{2+}$/Sn | Cu$^{2+}$/Cu | Ag$^+$/Ag |",
    "| --- | --- | --- | --- | --- | --- |",
    "| Thế điện cực chuẩn (V) | –0,44 | –0,257 | –0,137 | +0,340 | +0,799 |",
    "",
    "86"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C6' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B18', 'Cấu tạo và liên kết trong tinh thể kim loại', 89, 1, $JSON$
{
  "content": [
    "# CHƯƠNG 6",
    "# ĐẠI CƯƠNG VỀ KIM LOẠI",
    "",
    "# BÀI 18 CẤU TẠO VÀ LIÊN KẾT TRONG TINH THỂ KIM LOẠI",
    "",
    "**MỤC TIÊU**",
    "– Trình bày được đặc điểm cấu tạo của nguyên tử kim loại và tinh thể kim loại.",
    "– Nêu được đặc điểm của liên kết kim loại.",
    "",
    "❓ Kim loại được sử dụng nhiều trong cuộc sống như các kết cấu bằng thép, dây dẫn điện bằng đồng, đồ trang sức bằng vàng,... Kim loại có đặc điểm gì về cấu tạo nguyên tử và liên kết mà hữu dụng như vậy?",
    "",
    "## I ĐẶC ĐIỂM CẤU TẠO CỦA NGUYÊN TỬ KIM LOẠI",
    "🖐 Dựa vào bảng tuần hoàn các nguyên tố hoá học, hãy cho biết:",
    "1. Các nguyên tố khối s, d, f thường là kim loại hay phi kim?",
    "2. Kể tên các kim loại thuộc nhóm IA và IIA.",
    "3. Các nguyên tố kim loại thường có bao nhiêu electron ở lớp ngoài cùng?",
    "",
    "Trong cùng một chu kì, so với các nguyên tử nguyên tố phi kim, nguyên tử kim loại có điện tích hạt nhân nhỏ hơn và bán kính lớn hơn nên dễ nhường electron hoá trị hơn và có độ âm điện nhỏ hơn.",
    "",
    "❓ 1. Viết cấu hình electron nguyên tử của Sc (Z = 21) và Ti (Z = 22). Cho biết số electron ở lớp ngoài cùng và trên phân lớp d sát lớp ngoài cùng.",
    "",
    "## II TINH THỂ KIM LOẠI",
    "### 1. Tinh thể kim loại",
    "Ở nhiệt độ phòng, các đơn chất kim loại ở thể rắn và có cấu tạo tinh thể (trừ thuỷ ngân ở thể lỏng).",
    "Trong tinh thể kim loại, các ion dương kim loại nằm ở các nút mạng tinh thể và các electron hoá trị chuyển động tự do xung quanh.",
    "",
    "87",
    "💡 **EM CÓ BIẾT**",
    "Các kiểu mạng tinh thể phổ biến của kim loại:",
    "",
    "| Kiểu mạng tinh thể | Mạng lập phương tâm khối | Mạng lập phương tâm mặt | Mạng lục phương chặt khít |",
    "| --- | --- | --- | --- |",
    "| Cấu trúc | [Hình mạng lập phương tâm khối] | [Hình mạng lập phương tâm mặt] | [Hình mạng lục phương chặt khít] |",
    "| Độ đặc khít (%) | 68 | 74 | 74 |",
    "| Số phối trí | 8 | 12 | 12 |",
    "| Ví dụ | Li, Na, K, Ba,... | Ca, Sr, Cu,... | Be, Mg,... |",
    "",
    "### 2. Liên kết kim loại",
    "Trong tinh thể kim loại, liên kết kim loại được hình thành do lực hút tĩnh điện giữa các electron hoá trị tự do với các ion dương kim loại ở các nút mạng.",
    "[Hình 18.1. Liên kết kim loại: Các ion kim loại (+) xen kẽ với các electron tự do (màu xanh lá)]",
    "",
    "❓ 2. Hãy cho biết liên kết kim loại có đặc điểm gì giống và khác với liên kết ion.",
    "",
    "**EM ĐÃ HỌC**",
    "- Nguyên tử của hầu hết các kim loại có từ 1 đến 3 electron ở lớp ngoài cùng. Nguyên tử kim loại dễ nhường electron và có độ âm điện nhỏ hơn so với các nguyên tử phi kim.",
    "- Ở nhiệt độ phòng, các đơn chất kim loại ở thể rắn và có cấu tạo tinh thể (trừ thuỷ ngân).",
    "- Liên kết kim loại được hình thành do lực hút tĩnh điện giữa các electron hoá trị tự do với các ion dương kim loại trong mạng tinh thể kim loại.",
    "",
    "**EM CÓ THỂ**",
    "- So sánh được đặc điểm liên kết kim loại với liên kết ion.",
    "",
    "88"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C6' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B19', 'Tính chất vật lí và tính chất hoá học của kim loại', 91, 2, $JSON$
{
  "content": [
    "# BÀI 19 TÍNH CHẤT VẬT LÍ VÀ TÍNH CHẤT HOÁ HỌC CỦA KIM LOẠI",
    "",
    "**MỤC TIÊU**",
    "– Giải thích được một số tính chất vật lí chung của kim loại (tính dẻo, tính dẫn điện, tính dẫn nhiệt, tính ánh kim).",
    "– Trình bày được ứng dụng từ tính chất vật lí chung và riêng của kim loại.",
    "– Sử dụng bảng giá trị thế điện cực chuẩn của một số cặp oxi hoá – khử phổ biến của ion kim loại/kim loại (có bổ sung thế điện cực chuẩn của các cặp H$_2$O/OH$^-$ + $\\frac{1}{2}$H$_2$; 2H$^+$/H$_2$) để giải thích được các trường hợp kim loại phản ứng với dung dịch HCl, H$_2$SO$_4$ loãng và đặc; nước; dung dịch muối.",
    "– Trình bày được phản ứng của kim loại với phi kim (chlorine, oxygen, lưu huỳnh) và viết được các phương trình hoá học.",
    "– Thực hiện được một số thí nghiệm của kim loại tác dụng với phi kim, acid (HCl, H$_2$SO$_4$), muối.",
    "",
    "❓ Tại sao kim loại có thể được sử dụng làm dây dẫn điện, chế tạo dụng cụ đun nấu, dùng trong công trình xây dựng? Kim loại có những tính chất hoá học đặc trưng nào?",
    "",
    "## I TÍNH CHẤT VẬT LÍ",
    "Ở điều kiện thường, các kim loại đều có tính dẻo, dẫn điện, dẫn nhiệt và có ánh kim.",
    "",
    "### 1. Tính dẻo",
    "Kim loại có tính dẻo: dễ rèn, dễ dát mỏng và dễ kéo sợi. Tính chất này khác với phi kim và các hợp chất ion.",
    "Khi thanh kim loại chịu lực tác động (rèn, cán, kéo,...), các ion dương kim loại trong mạng tinh thể kim loại có thể trượt lên nhau mà không tách rời nhau. Đó là do các electron tự do trong mạng tinh thể kim loại chuyển động, liên kết các ion dương kim loại lại với nhau (Hình 19.1).",
    "[Hình 19.1. Các lớp mạng tinh thể kim loại trước và sau khi bị biến dạng: Các lớp ion kim loại (+) trượt lên nhau dưới lực tác động, electron (màu xanh lá) vẫn bao quanh giữ chúng lại]",
    "Những kim loại có tính dẻo cao là Au, Ag, Al, Cu, Sn,... Người ta có thể dát được những lá vàng mỏng tới khoảng 8 nm.",
    "Nhờ có tính dẻo mà kim loại có thể được uốn cong, ép khuôn thành nhiều hình dạng hay kích thước khác nhau.",
    "",
    "89",
    "❓ 1. Vì sao kim loại có tính dẻo?",
    "",
    "### 2. Tính dẫn điện",
    "Tất cả các kim loại đều có tính dẫn điện. Khi một hiệu điện thế được áp vào thanh kim loại, các electron tự do trong mạng tinh thể sẽ di chuyển từ phía cực âm về phía cực dương (Hình 19.2). Hệ quả là thanh kim loại trở thành vật dẫn điện.",
    "[Hình 19.2. Hướng di chuyển của các electron tự do: Các electron di chuyển từ cực (-) sang cực (+)]",
    "Bạc (Ag) là kim loại dẫn điện tốt nhất, tiếp sau bạc là đồng (Cu), vàng (Au) và nhôm (Al),... Tuy nhiên, nhôm và đồng thường được sử dụng làm dây dẫn điện hơn.",
    "",
    "❓ 2.",
    "a) Hãy nêu sự khác biệt giữa liên kết kim loại và liên kết cộng hoá trị.",
    "b) Vì sao kim loại có tính dẫn điện, trong khi hầu hết các phi kim không dẫn điện?",
    "",
    "### 3. Tính dẫn nhiệt",
    "Tính dẫn nhiệt của các kim loại cũng được giải thích bằng sự có mặt của các electron tự do trong mạng tinh thể. Khi đốt nóng một đầu của thanh kim loại thì động năng của các electron trong vùng đó tăng lên. Các electron này truyền động năng của chúng cho các ion dương ở các nút mạng và các electron khác trong toàn thanh kim loại thông qua va chạm, làm cho nhiệt được lan truyền trong toàn bộ thanh kim loại.",
    "Các kim loại dẫn điện tốt thường dẫn nhiệt tốt. Do có tính dẫn nhiệt tốt, các kim loại hoặc hợp kim được sử dụng làm các dụng cụ đun nấu như xoong, nồi, chảo,...",
    "",
    "❓ 3. Vì sao kim loại có tính dẫn nhiệt tốt? Hãy nêu một số ứng dụng của kim loại dựa trên tính dẫn nhiệt của chúng.",
    "",
    "### 4. Tính ánh kim",
    "Các electron tự do trong tinh thể kim loại phản xạ hầu hết những tia sáng nhìn thấy được. Do đó, kim loại có vẻ sáng lấp lánh, gọi là “ánh kim”.",
    "Trên thực tế, khi nhìn vào nhiều kim loại không thấy ánh kim vì chúng thường bị bao phủ bởi một lớp oxide, ví dụ như sắt thường có gỉ sắt, nhôm bị phủ lớp aluminium oxide,...",
    "",
    "❓ 4. Vì sao kim loại có ánh kim? Hãy nêu một số ứng dụng của kim loại dựa trên tính ánh kim của chúng.",
    "",
    "90",
    "### 5. Một số tính chất vật lí khác của kim loại",
    "**a) Khối lượng riêng**",
    "Khối lượng riêng của các kim loại rất khác nhau. Kim loại nhẹ nhất là lithium (D = 0,534 g/cm$^3$), kim loại nặng nhất là osmium (D = 22,6 g/cm$^3$). Kim loại có D < 5 g/cm$^3$, được gọi là kim loại nhẹ, những kim loại có D $\\ge$ 5 g/cm$^3$, được gọi là kim loại nặng.",
    "",
    "**b) Nhiệt độ nóng chảy**",
    "Nhiệt độ nóng chảy của các kim loại biến đổi trong khoảng rộng: Có kim loại nóng chảy ở nhiệt độ rất cao, như tungsten (vonfram, W) nóng chảy ở 3 410 $^\\circ$C; kim loại duy nhất ở trạng thái lỏng trong điều kiện thường là thuỷ ngân (nhiệt độ nóng chảy là –39 $^\\circ$C).",
    "",
    "**c) Tính cứng**",
    "Các kim loại có độ cứng rất khác nhau. Kim loại cứng nhất là chromium, có thể cắt được kính, các kim loại mềm nhất là kim loại kiềm như potassium, rubidium, sodium và caesium, chúng có thể được cắt dễ dàng bằng dao.",
    "",
    "🖐 Hãy tìm hiểu và trình bày một số ứng dụng của kim loại có nhiệt độ nóng chảy cao và kim loại có độ cứng lớn.",
    "",
    "## II TÍNH CHẤT HOÁ HỌC",
    "Các nguyên tử kim loại dễ nhường electron hoá trị:",
    "M $\\longrightarrow$ M$^{n+}$ + ne",
    "Trong đó: M là kí hiệu của kim loại.",
    "Như vậy, tính chất hoá học chung của kim loại là tính khử.",
    "",
    "### 1. Tác dụng với phi kim",
    "Hầu hết các kim loại đều phản ứng với các phi kim điển hình.",
    "",
    "**Thí nghiệm: Kim loại tác dụng với phi kim**",
    "*Chuẩn bị:*",
    "Hoá chất: dây magnesium (Mg), nhôm bột, lưu huỳnh bột.",
    "Dụng cụ: kẹp sắt, ống nghiệm chịu nhiệt, đũa thuỷ tinh, đèn cồn.",
    "*Tiến hành:*",
    "1. Magnesium tác dụng với oxygen: Dùng kẹp sắt kẹp một mẩu dây magnesium (Mg) và đốt trên ngọn lửa đèn cồn.",
    "2. Nhôm tác dụng với lưu huỳnh: Trộn đều bột nhôm và bột lưu huỳnh theo tỉ lệ khối lượng tương ứng khoảng 1 : 2. Lấy một thìa thuỷ tinh (khoảng 0,3 g) hỗn hợp vào ống nghiệm khô chịu nhiệt. Hơ nóng đều ống nghiệm trên ngọn lửa đèn cồn, sau đó đun tập trung vào phần ống nghiệm chứa hỗn hợp.",
    "*Thực hiện yêu cầu sau:*",
    "Hãy mô tả hiện tượng quan sát được và viết phương trình hoá học của các phản ứng xảy ra.",
    "",
    "91",
    "**a) Tác dụng với oxygen**",
    "Hầu hết các kim loại (trừ vàng, bạc, platinum,...) đều tác dụng với oxygen tạo thành oxide.",
    "*Ví dụ:* Khi đốt nóng, bột nhôm cháy mạnh trong không khí tạo thành aluminium oxide:",
    "4Al(s) + 3O$_2$(g) $\\longrightarrow$ 2Al$_2$O$_3$(s)",
    "",
    "**b) Tác dụng với chlorine**",
    "Hầu hết các kim loại đều tác dụng với khí chlorine khi đun nóng, thu được muối chloride tương ứng.",
    "*Ví dụ:* Dây sắt nóng đỏ cháy mạnh trong khí chlorine tạo ra khói màu nâu có chứa iron(III) chloride:",
    "2Fe(s) + 3Cl$_2$(g) $\\longrightarrow$ 2FeCl$_3$(s)",
    "",
    "**c) Tác dụng với lưu huỳnh (sulfur)**",
    "Nhiều kim loại có thể khử lưu huỳnh khi đun nóng (trừ thuỷ ngân phản ứng ngay ở nhiệt độ thường).",
    "*Ví dụ :*",
    "Fe(s) + S(s) $\\xrightarrow{\\text{t}^\\circ}$ FeS(s)",
    "Hg(l) + S(s) $\\longrightarrow$ HgS(s)",
    "",
    "❓ 5. Khi tác dụng với phi kim, kim loại thể hiện tính chất hoá học gì? Minh hoạ bằng các phương trình hoá học.",
    "",
    "### 2. Tác dụng với nước",
    "Hầu hết các kim loại nhóm IA, IIA có tính khử mạnh, tác dụng với nước ở nhiệt độ thường giải phóng H$_2$.",
    "*Ví dụ:* 2Na(s) + 2H$_2$O(l) $\\longrightarrow$ 2NaOH(aq) + H$_2$(g)",
    "Những kim loại có thế điện cực chuẩn E$^\\circ_{\\text{M}^{n+}/\\text{M}}$ nhỏ hơn –0,414 V có thể đẩy được hydrogen ra khỏi nước.",
    "",
    "❓ 6. Hãy cho biết kim loại nào trong Bảng 15.1 có thể phản ứng được với nước ở nhiệt độ thường giải phóng khí hydrogen.",
    "",
    "### 3. Tác dụng với dung dịch acid",
    "**a) Với dung dịch HCl, H$_2$SO$_4$ loãng**",
    "",
    "**Thí nghiệm: Kim loại tác dụng với dung dịch acid loãng**",
    "*Chuẩn bị:*",
    "Hoá chất: dung dịch H$_2$SO$_4$ 10%, kẽm hạt.",
    "Dụng cụ: ống nghiệm, kẹp gỗ.",
    "*Tiến hành:*",
    "Cho vài hạt kẽm vào ống nghiệm. Thêm tiếp khoảng 2 mL dung dịch H$_2$SO$_4$ 10%.",
    "*Thực hiện yêu cầu sau:*",
    "Hãy mô tả hiện tượng quan sát được và viết phương trình hoá học.",
    "",
    "92",
    "Ở điều kiện chuẩn, những kim loại có E$^\\circ_{\\text{M}^{n+}/\\text{M}}$ < 0 có thể tác dụng với các dung dịch acid (như HCl, H$_2$SO$_4$) tạo thành H$_2$.",
    "*Ví dụ:* Sắt phản ứng với dung dịch H$_2$SO$_4$ loãng theo phương trình hoá học sau:",
    "Fe(s) + H$_2$SO$_4$(aq) $\\longrightarrow$ FeSO$_4$(aq) + H$_2$(g)",
    "(số oxi hoá của Fe tăng từ 0 lên +2, của H giảm từ +1 xuống 0)",
    "",
    "❓ 7. Các kim loại từ Cu đến Au trong dãy điện hoá không đẩy được H$_2$ ra khỏi dung dịch của các acid như HCl, H$_2$SO$_4$ loãng. Hãy dựa vào thế điện cực chuẩn của các cặp oxi hoá – khử tương ứng để giải thích.",
    "",
    "**b) Với dung dịch H$_2$SO$_4$ đặc**",
    "Hầu hết kim loại (trừ Pt, Au) khử được S$^{+6}$ (trong H$_2$SO$_4$ đặc) xuống số oxi hoá thấp hơn.",
    "*Ví dụ:* Cu(s) + 2H$_2$SO$_4$(đặc) $\\xrightarrow{\\text{t}^\\circ}$ CuSO$_4$(aq) + SO$_2$(g) + 2H$_2$O(l)",
    "(số oxi hoá của Cu tăng từ 0 lên +2, của S giảm từ +6 xuống +4)",
    "*Chú ý:* HNO$_3$ đặc, nguội và H$_2$SO$_4$ đặc, nguội làm thụ động hoá Al, Fe, Cr,...",
    "",
    "### 4. Tác dụng với dung dịch muối",
    "Kim loại hoạt động mạnh hơn có thể đẩy kim loại hoạt động yếu hơn ra khỏi dung dịch muối của nó.",
    "*Ví dụ:* Cu(s) + 2AgNO$_3$(aq) $\\longrightarrow$ Cu(NO$_3$)$_2$(aq) + 2Ag(s)",
    "",
    "**Thí nghiệm: Kim loại tác dụng với dung dịch muối**",
    "*Chuẩn bị:*",
    "Hoá chất: đinh sắt mới (đã rửa sạch lớp dầu mỡ), dung dịch CuSO$_4$ 1 M.",
    "Dụng cụ: cốc thuỷ tinh, kẹp sắt.",
    "*Tiến hành:* Cho đinh sắt vào cốc. Thêm tiếp 2 – 3 mL dung dịch CuSO$_4$ 1 M. Sau 5 phút dùng kẹp lấy đinh sắt ra khỏi dung dịch.",
    "*Thực hiện yêu cầu sau:*",
    "Mô tả hiện tượng xảy ra, giải thích và viết phương trình hoá học.",
    "",
    "**EM ĐÃ HỌC**",
    "- Ở điều kiện thường, các kim loại đều ở trạng thái rắn (trừ Hg), có tính dẻo, dẫn điện, dẫn nhiệt và có ánh kim.",
    "- Một số ứng dụng dựa trên tính chất vật lí chung và các tính chất vật lí riêng của kim loại (như khối lượng riêng, nhiệt độ nóng chảy, tính cứng).",
    "- Tính chất hoá học của kim loại: kim loại phản ứng với phi kim; với dung dịch HCl, H$_2$SO$_4$ loãng và H$_2$SO$_4$ đặc; với nước và với dung dịch muối.",
    "",
    "**EM CÓ THỂ**",
    "- Giải thích được các ứng dụng của kim loại dựa trên tính chất vật lí của chúng.",
    "- Giải thích được vì sao các vật bằng sắt thép bị phá huỷ nhanh hơn trong môi trường acid loãng, còn vật bằng đồng thì khó bị phá huỷ hơn.",
    "",
    "93"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C6' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B20', 'Kim loại trong tự nhiên và phương pháp tách kim loại', 96, 3, $JSON$
{
  "content": [
    "# BÀI 20 KIM LOẠI TRONG TỰ NHIÊN VÀ PHƯƠNG PHÁP TÁCH KIM LOẠI",
    "",
    "**MỤC TIÊU**",
    "– Nêu được khái quát trạng thái tự nhiên của kim loại và một số quặng, mỏ kim loại phổ biến.",
    "– Trình bày và giải thích được phương pháp tách kim loại hoạt động mạnh như sodium, magnesium, nhôm (aluminium).",
    "– Trình bày và giải thích được phương pháp tách kim loại hoạt động trung bình như kẽm (zinc), sắt (iron); Phương pháp tách kim loại kém hoạt động như đồng (copper).",
    "– Trình bày được nhu cầu và thực tiễn tái chế kim loại phổ biến như sắt, nhôm, đồng,...",
    "",
    "❓ Trong tự nhiên, các kim loại (trừ vàng, bạc và platinum) thường tồn tại dưới dạng hợp chất trong quặng. Làm thế nào để tách kim loại ra khỏi quặng?",
    "",
    "## I KIM LOẠI TRONG TỰ NHIÊN",
    "Trong tự nhiên, hầu hết các kim loại tồn tại ở dạng hợp chất (oxide, muối,...) trong quặng, chỉ một số kim loại kém hoạt động như vàng, bạc, platinum,... được tìm thấy dưới dạng đơn chất.",
    "Quặng là những loại đất, đá tồn tại trong tự nhiên có chứa khoáng vật của kim loại hoặc hợp chất kim loại với trữ lượng đủ lớn để có thể khai thác (Hình 20.1). Quặng thường chứa tạp chất. Phương pháp được sử dụng để tách một kim loại nhất định từ quặng của nó phụ thuộc vào tính chất của kim loại và của quặng.",
    "[Hình 20.1. Một số quặng kim loại trong tự nhiên: a) Quặng bauxite; b) Quặng hematite]",
    "Một số loại quặng kim loại thông dụng được trình bày trong Bảng 20.1.",
    "**Bảng 20.1.** Một số quặng kim loại thông dụng",
    "",
    "| Kim loại | Quặng | Thành phần chính |",
    "| --- | --- | --- |",
    "| Al | Bauxite | Al$_2$O$_3$$\\cdot$2H$_2$O |",
    "| Zn | Zinc blende | ZnS |",
    "| Fe | Hematite | Fe$_2$O$_3$ |",
    "| | Pyrite | FeS$_2$ |",
    "| Cu | Chalcopyrite | CuFeS$_2$ |",
    "",
    "94",
    "❓ 1.",
    "a) Hãy cho biết những kim loại nào tồn tại ở dạng đơn chất trong tự nhiên.",
    "b) Hãy tìm hiểu và cho biết một số mỏ quặng kim loại quan trọng ở Việt Nam.",
    "",
    "## II CÁC PHƯƠNG PHÁP TÁCH KIM LOẠI",
    "### 1. Nguyên tắc",
    "Nguyên tắc điều chế kim loại là khử ion kim loại thành nguyên tử:",
    "M$^{n+}$ + ne $\\longrightarrow$ M",
    "",
    "### 2. Tách kim loại hoạt động hoá học mạnh – Điện phân nóng chảy",
    "Những kim loại hoạt động hoá học mạnh như K, Na, Ca, Mg, Al,... được điều chế bằng phương pháp điện phân nóng chảy các hợp chất của chúng (oxide, muối chloride).",
    "**a) Điện phân oxide nóng chảy**",
    "🖐 Hãy tìm hiểu quá trình điện phân Al$_2$O$_3$ nóng chảy và thực hiện các yêu cầu sau:",
    "1. Nêu vai trò của cryolite trong quá trình điện phân.",
    "2. Tại sao sau một thời gian, cần phải thay cực dương của bình điện phân. Viết các phương trình hoá học để giải thích.",
    "",
    "**b) Điện phân muối chloride nóng chảy**",
    "Để điều chế các kim loại như K, Na, Ca, Mg,... người ta điện phân muối chloride của chúng ở trạng thái nóng chảy.",
    "*Ví dụ:* Điện phân MgCl$_2$ nóng chảy.",
    "MgCl$_2$ nóng chảy phân li thành các ion Mg$^{2+}$ và ion Cl$^-$. Cation Mg$^{2+}$ di chuyển về cực âm (cathode) và anion Cl$^-$ di chuyển về cực dương (anode) của bình điện phân.",
    "Ở cathode: Mg$^{2+}$ + 2e $\\longrightarrow$ Mg",
    "Ở anode: 2Cl$^-$ $\\longrightarrow$ Cl$_2$ + 2e",
    "Phương trình hoá học của phản ứng điện phân: MgCl$_2$(l) $\\xrightarrow{\\text{đpnc}}$ Mg(l) + Cl$_2$(g).",
    "",
    "❓ 2.",
    "a) Hãy cho biết những kim loại nào thường được điều chế bằng phương pháp điện phân nóng chảy. Giải thích.",
    "b) Hãy viết các quá trình xảy ra trên các điện cực và phương trình hoá học của phản ứng khi điện phân nóng chảy muối ăn.",
    "",
    "95",
    "### 3. Tách kim loại hoạt động trung bình, yếu",
    "**a) Phương pháp nhiệt luyện**",
    "- *Nguyên tắc:* Khử các oxide kim loại ở nhiệt độ cao bằng chất khử như C, CO,...",
    "Những kim loại có độ hoạt động trung bình, yếu như Zn, Fe, Sn, Pb, Cu,... thường được điều chế bằng phương pháp nhiệt luyện.",
    "*Ví dụ 1:* Tách kẽm từ quặng zinc blende.",
    "– Đốt quặng zinc blende: 2ZnS(s) + 3O$_2$(g) $\\xrightarrow{\\text{t}^\\circ}$ 2ZnO(s) + 2SO$_2$(g).",
    "– Khử zinc oxide ở nhiệt độ cao bằng than cốc: ZnO(s) + C(s) $\\xrightarrow{\\text{t}^\\circ}$ Zn(g) + CO(g).",
    "*Ví dụ 2:* Tách sắt từ quặng hematite.",
    "Ở nhiệt độ cao, sắt được tách ra khỏi iron(III) oxide bởi carbon monoxide:",
    "Fe$_2$O$_3$(s) + 3CO(g) $\\xrightarrow{\\text{t}^\\circ}$ 2Fe(l) + 3CO$_2$(g)",
    "",
    "❓ 3. Hãy kể tên một số kim loại được điều chế bằng phương pháp nhiệt luyện.",
    "",
    "**b) Phương pháp điện phân dung dịch**",
    "Kim loại hoạt động trung bình hoặc yếu có thể được điều chế bằng cách điện phân dung dịch muối của chúng.",
    "*Ví dụ:* Điện phân dung dịch CuCl$_2$ để điều chế Cu.",
    "Phương trình hoá học của phản ứng điện phân: CuCl$_2$(aq) $\\xrightarrow{\\text{đpdd}}$ Cu(s) + Cl$_2$(g)",
    "",
    "🖐 Quan sát Hình 20.2 và thực hiện các yêu cầu sau:",
    "1. Cho biết điện cực nào là điện cực dương, điện cực nào là điện cực âm.",
    "2. Hãy viết các quá trình xảy ra trên các điện cực và phương trình hoá học của phản ứng điện phân dung dịch CuSO$_4$.",
    "[Hình 20.2. Điện phân dung dịch CuSO$_4$ với hai điện cực than chì: 2 điện cực than chì nối với nguồn điện, nhúng trong cốc chứa dung dịch CuSO$_4$.]",
    "",
    "**c) Phương pháp thuỷ luyện**",
    "Cơ sở của phương pháp này là dùng những dung dịch thích hợp như dung dịch H$_2$SO$_4$, NaOH, NaCN,... để hoà tan kim loại hoặc hợp chất của kim loại, tách phần không tan ra khỏi dung dịch. Sau đó khử những ion kim loại này trong dung dịch bằng kim loại có tính khử mạnh hơn như Fe, Zn,...",
    "*Ví dụ:* Dùng Fe để khử ion Cu$^{2+}$ trong dung dịch muối đồng.",
    "Fe(s) + CuSO$_4$(aq) $\\longrightarrow$ FeSO$_4$(aq) + Cu(s)",
    "",
    "96",
    "💡 **EM CÓ BIẾT**",
    "Trong công nghiệp, phương pháp thuỷ luyện thường được dùng để điều chế các kim loại quý như Au, Ag.",
    "*Ví dụ:* Au tồn tại trong tự nhiên dưới dạng đơn chất nhưng quặng vàng thường có hàm lượng vàng thấp. Người ta nghiền quặng, hoà tan chúng vào dung dịch KCN và liên tục sục không khí vào. Vàng bị hoà tan tạo thành phức chất:",
    "4Au(s) + 8KCN(aq) + O$_2$(g) + 2H$_2$O(l) $\\longrightarrow$ 4K[Au(CN)$_2$](aq) + 4KOH(aq)",
    "Dùng bột kẽm đẩy vàng ra khỏi hợp chất:",
    "2K[Au(CN)$_2$](aq) + Zn(s) $\\longrightarrow$ K$_2$[Zn(CN)$_4$](aq) + 2Au(s)",
    "",
    "## III TÁI CHẾ KIM LOẠI",
    "Hiện nay, trữ lượng các mỏ quặng kim loại ngày càng cạn kiệt, trong khi nhu cầu sử dụng kim loại ngày càng tăng và lượng phế thải kim loại tạo ra ngày càng nhiều. Do đó, tái chế kim loại là công việc cần thiết, vừa đảm bảo nguồn cung, vừa gia tăng giá trị kinh tế, bảo vệ môi trường và thực hiện mục tiêu phát triển bền vững.",
    "Quy trình tái chế kim loại thường gồm các giai đoạn: thu gom, phân loại; xử lí sơ bộ; phối trộn phế liệu; nấu chảy; tinh chế; đúc, chế tạo, gia công.",
    "- **Tái chế nhôm**",
    "Nhôm là một trong những kim loại có thể được tái chế hiệu quả nhất, tiết kiệm năng lượng so với sản xuất từ quặng. Giống như hầu hết các kim loại, nhôm có thể được tái chế nhiều lần mà không mất đi các tính chất vốn có của nó. Nhôm tái chế được sử dụng trong các lĩnh vực như xây dựng, sản xuất ô tô, xe máy, xe đạp, thiết bị điện tử,... Hiện nay, khoảng 75% tổng lượng nhôm từng được sản xuất vẫn đang được sử dụng$^{(1)}$.",
    "- **Tái chế đồng**",
    "Đồng cũng có thể được tái chế nhiều lần mà ít bị tiêu hao. Đồng tái chế được sử dụng trong nhiều lĩnh vực như làm vật liệu xây dựng, phương tiện giao thông, dụng cụ nấu ăn, nhạc cụ, dây dẫn điện,... Tái chế đồng giúp tiết kiệm một lượng lớn năng lượng so với sản xuất kim loại từ quặng. Ước tính khoảng 80% lượng đồng từng được khai thác từ Trái Đất vẫn đang được sử dụng cho đến ngày nay$^{(2)}$.",
    "- **Tái chế sắt**",
    "Sắt là kim loại được tái chế nhiều nhất trên thế giới và có thể tái chế nhiều lần. Tái chế sắt giúp tiết kiệm năng lượng so với sản xuất sắt thép từ quặng sắt, giảm thiểu một số tác động tiêu cực tới môi trường của quá trình khai thác quặng. Phần lớn sắt tái chế được sử dụng để sản xuất thép. Sắt thép tái chế được sử dụng trong các lĩnh vực xây dựng, sản xuất ô tô,...",
    "",
    "$^{(1)}$ Nguồn: Dierk raabe, et al 2022. Making sustainable aluminum by recycling scrap: The science of “dirty” alloys. *Progress in Materials Science*, 128, page 100947.",
    "$^{(2)}$ Nguồn: Lusty, P. A. J. & Hannis, S. D. 2009. Commodity Profile: Copper. Keyworth, Nottingham: British Geological Survey.",
    "",
    "97",
    "💡 **EM CÓ BIẾT**",
    "- Khoảng 70% trọng lượng xe hơi là thép. Quá trình tái chế xe hơi phế liệu cung cấp một lượng rất lớn thép mỗi năm.",
    "- Việc tái chế thép giúp giảm 80% lượng khí thải CO$_2$ so với sản xuất thép mới từ nguyên liệu thô. Các quy trình tái chế thép cũng giảm 40% mức tiêu thụ nước và ô nhiễm nước xuống 76%.",
    "(Nguồn: Yue, K. 2012. Comparative analysis of scrap car recycling management policies. The 7th International Conference on Waste Management and Technology Conference, pages 44 – 50.)",
    "",
    "🖐 Em hãy tìm hiểu, trình bày nhu cầu sử dụng và thực tiễn tái chế sắt, nhôm, đồng ở Việt Nam.",
    "",
    "**EM ĐÃ HỌC**",
    "- Trong tự nhiên, hầu hết các kim loại tồn tại ở dạng hợp chất trong quặng, chỉ một vài kim loại kém hoạt động như vàng, bạc, platinum,... được tìm thấy dưới dạng đơn chất.",
    "- Nguyên tắc điều chế kim loại là khử ion kim loại thành nguyên tử:",
    "M$^{n+}$ + ne $\\longrightarrow$ M",
    "– Những kim loại hoạt động hoá học mạnh được điều chế bằng phương pháp điện phân nóng chảy các hợp chất của chúng.",
    "– Những kim loại hoạt động trung bình, yếu thường được điều chế bằng phương pháp nhiệt luyện hoặc điện phân dung dịch muối của chúng hoặc thuỷ luyện.",
    "- Sắt, nhôm, đồng là những vật liệu kim loại được sử dụng phổ biến nhất, nhu cầu tái chế nhiều nhất và việc tái chế kim loại góp phần giảm thải ô nhiễm môi trường.",
    "",
    "**EM CÓ THỂ**",
    "- Trình bày được nguyên tắc tinh chế kẽm, đồng bằng phương pháp điện phân dung dịch.",
    "- Trình bày được thực tiễn tái chế sắt, nhôm, đồng ở Việt Nam.",
    "",
    "98"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C6' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B21', 'Hợp kim', 101, 4, $JSON$
{
  "content": [
    "# BÀI 21 HỢP KIM",
    "",
    "**MỤC TIÊU**",
    "– Trình bày được khái niệm hợp kim và việc sử dụng phổ biến hợp kim.",
    "– Trình bày được một số tính chất của hợp kim so với kim loại thành phần.",
    "– Nêu được thành phần, tính chất và ứng dụng của một số hợp kim quan trọng của sắt và nhôm (gang, thép, duralumin,...).",
    "",
    "❓ Khung xe đạp, xe máy, ô tô hay thân vỏ máy bay thường được làm bằng hợp kim. Vậy, hợp kim là gì? Hợp kim có những tính chất khác biệt nào so với kim loại thành phần mà được sử dụng rộng rãi như vậy?",
    "",
    "## I KHÁI NIỆM VÀ ỨNG DỤNG CỦA HỢP KIM",
    "### 1. Khái niệm hợp kim",
    "*Hợp kim* là vật liệu kim loại chứa một kim loại cơ bản và một số kim loại khác hoặc phi kim.",
    "*Ví dụ:* Thép, gang là hợp kim của Fe với C và một số nguyên tố khác (Mn, Si,...); Duralumin là hợp kim của Al với Cu, Mn, Mg, Si.",
    "Hợp kim thường được điều chế bằng cách nung chảy các thành phần rồi để nguội.",
    "",
    "### 2. Ứng dụng của hợp kim",
    "🖐 Trong đời sống và sản xuất, hợp kim được sử dụng rộng rãi hơn nhiều so với kim loại nguyên chất. Hãy tìm hiểu và nêu tên gọi, thành phần chính của các hợp kim có đặc điểm sau:",
    "a) Hợp kim nhẹ, bền, dùng để chế tạo các chi tiết của máy bay, ô tô,...",
    "b) Hợp kim cứng và bền dùng để xây dựng nhà cửa, cầu cống.",
    "",
    "Từ thời cổ đại, con người đã biết sử dụng hợp kim để làm công cụ lao động và chế tạo vũ khí. Ngày nay, hợp kim được sử dụng rộng rãi trong đời sống và sản xuất. Trong lĩnh vực chế tạo máy bay, ô tô,... sử dụng những hợp kim nhẹ, bền, chịu nhiệt,... Ngành công nghiệp hoá chất sử dụng những hợp kim có tính bền hoá học và cơ học cao,... Các đồ gia dụng được làm từ những hợp kim không gỉ, không độc hại,...",
    "",
    "❓ 1. Hãy nêu tên và ứng dụng của một số hợp kim thông dụng của nhôm và sắt.",
    "",
    "## II TÍNH CHẤT CỦA HỢP KIM",
    "Tính chất của hợp kim phụ thuộc vào thành phần các đơn chất tham gia cấu tạo mạng tinh thể của hợp kim. Nhìn chung, hợp kim có nhiều tính chất hoá học tương tự các kim loại thành phần, nhưng tính chất vật lí thường khác nhau nhiều.",
    "",
    "99",
    "- Hợp kim có những tính chất vật lí chung như có ánh kim, dẫn điện, dẫn nhiệt,... Tuy nhiên, tính dẫn điện và dẫn nhiệt kém hơn kim loại cơ bản trong hợp kim.",
    "*Ví dụ:* đồng dẫn điện tốt hơn hợp kim đồng.",
    "- Độ cứng của hợp kim thường lớn hơn độ cứng của kim loại thành phần trong hợp kim và độ dẻo thường kém hơn.",
    "*Ví dụ:* hợp kim Au – Cu (khoảng 8% – 12% Cu) cứng hơn vàng, dùng đúc tiền, làm đồ trang sức, ngòi bút máy.",
    "- Nhiệt độ nóng chảy của hợp kim tuỳ thuộc vào thành phần và cấu tạo tinh thể của hợp kim, nhưng khác so với kim loại thành phần trong hợp kim.",
    "*Ví dụ:* gang là hợp kim Fe – C có nhiệt độ nóng chảy thấp hơn nhiệt độ nóng chảy của sắt nguyên chất.",
    "",
    "## III MỘT SỐ HỢP KIM QUAN TRỌNG CỦA SẮT VÀ NHÔM",
    "### 1. Hợp kim của sắt",
    "**a) Gang**",
    "Gang là hợp kim chứa khoảng 95% sắt, 2% đến 4% carbon và một số nguyên tố khác như manganese, silicon, phosphorus, sulfur,... Gang cứng hơn nhưng cũng giòn hơn sắt. Gang được sử dụng để làm nguyên liệu sản xuất thép, chế tạo dụng cụ đun nấu, các chi tiết máy,...",
    "",
    "**b) Thép**",
    "Thép là hợp kim của sắt chứa ít hơn 2,0% carbon và một số nguyên tố như chromium, manganese, silicon,... tạo cho thép có tính cứng, tính chịu nhiệt và các tính chất quý khác. Thép là vật liệu chủ yếu trong ngành chế tạo máy, xây dựng và nhiều lĩnh vực khác của đời sống và sản xuất.",
    "Các tính chất của thép có thể được điều chỉnh để phù hợp với mục đích sử dụng, thường bằng cách thêm các kim loại như titanium, vanadium, manganese,... vào hợp kim. *Ví dụ:* thép không gỉ là hợp kim của sắt có chứa ít nhất 10% chromium theo khối lượng, ngoài ra còn có một lượng nhỏ carbon. Thép không gỉ có khả năng chống ăn mòn cao hơn nhiều so với sắt nguyên chất, thường được sử dụng làm dụng cụ y tế,...",
    "[Hình 21.1. Các cuộn thép chống gỉ]",
    "",
    "100",
    "### 2. Hợp kim của nhôm",
    "Duralumin là hợp kim chứa trên 90% nhôm, khoảng 4% đồng và một số nguyên tố khác như manganese, magnesium, silicon,...",
    "Duralumin nhẹ, cứng và bền, được sử dụng rộng rãi trong ngành công nghiệp chế tạo máy bay.",
    "",
    "❓ 2. Cho biết một số đặc tính vượt trội của các hợp kim: gang, thép và duralumin so với kim loại cơ bản trong hợp kim.",
    "",
    "**EM ĐÃ HỌC**",
    "- Hợp kim là vật liệu kim loại chứa một kim loại cơ bản và một số kim loại khác hoặc phi kim.",
    "- Nhìn chung, hợp kim có nhiều tính chất hoá học tương tự kim loại thành phần nhưng tính chất vật lí thường khác nhau nhiều.",
    "- Một số hợp kim của sắt như gang được sử dụng để làm nguyên liệu sản xuất thép, chế tạo dụng cụ đun nấu, các chi tiết máy;... Thép là vật liệu chủ yếu trong ngành chế tạo máy, xây dựng và nhiều lĩnh vực khác của đời sống và sản xuất.",
    "- Hợp kim của nhôm (như duralumin), cứng, nhẹ và bền, được sử dụng rộng rãi trong ngành công nghiệp chế tạo máy bay.",
    "",
    "**EM CÓ THỂ**",
    "Giải thích được tại sao hợp kim được sử dụng phổ biến trong đời sống và sản xuất.",
    "",
    "101"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C6' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B22', 'Sự ăn mòn kim loại', 104, 5, $JSON$
{
  "content": [
    "# BÀI 22 SỰ ĂN MÒN KIM LOẠI",
    "",
    "**MỤC TIÊU**",
    "– Nêu được khái niệm ăn mòn kim loại từ sự biến đổi của một số kim loại, hợp kim trong tự nhiên.",
    "– Trình bày được các dạng ăn mòn kim loại và các phương pháp chống ăn mòn kim loại.",
    "– Thực hiện được (hoặc quan sát qua video) thí nghiệm ăn mòn điện hoá đối với sắt và thí nghiệm bảo vệ sắt bằng phương pháp điện hoá, mô tả hiện tượng thí nghiệm, giải thích và nhận xét.",
    "",
    "❓ Vỏ tàu biển bằng thép để lâu trong tự nhiên thường bị ăn mòn. Để bảo vệ vỏ tàu khỏi bị ăn mòn, người ta thường phủ sơn lên vỏ tàu; phần vỏ tàu chìm trong nước biển thường được gắn thêm các tấm kẽm. Vậy, ăn mòn kim loại là gì? Để bảo vệ kim loại khỏi sự ăn mòn có thể dùng những cách nào?",
    "",
    "## I ĂN MÒN KIM LOẠI",
    "### 1. Khái niệm",
    "Thép để lâu ngoài không khí ẩm thường tạo thành gỉ sắt có màu nâu đỏ (Hình 22.1a); Vật bằng đồng để lâu trong tự nhiên có thể tạo thành gỉ đồng màu xanh (Hình 22.1b). Nhiều kim loại và hợp kim để lâu trong tự nhiên cũng có hiện tượng tương tự như vậy. Hiện tượng này được gọi là sự ăn mòn kim loại.",
    "*Ăn mòn kim loại* là sự phá huỷ kim loại hoặc hợp kim dưới tác dụng của các chất trong môi trường, trong đó kim loại bị oxi hoá.",
    "[Hình 22.1. Một số hiện tượng ăn mòn kim loại: a) Ống thép bị gỉ; b) Chuông đồng bị gỉ]",
    "",
    "### 2. Các dạng ăn mòn kim loại trong tự nhiên",
    "Tuỳ theo cơ chế của sự ăn mòn, người ta chia ăn mòn kim loại thành hai loại: ăn mòn hoá học và ăn mòn điện hoá.",
    "**a) Ăn mòn hoá học**",
    "Khi để kim loại trong không khí, có thể xảy ra hiện tượng ăn mòn hoá học. Nguyên nhân của hiện tượng trên là do xảy ra phản ứng oxi hoá – khử trực tiếp giữa kim loại với các chất oxi hoá có trong môi trường.",
    "",
    "102",
    "*Ví dụ:* Bộ phận của thiết bị lò đốt bằng sắt bị ăn mòn bởi khí oxygen:",
    "3Fe(s) + 2O$_2$(g) $\\xrightarrow{\\text{t}^\\circ}$ Fe$_3$O$_4$(s)",
    "",
    "**b) Ăn mòn điện hoá**",
    "**Thí nghiệm: Sự ăn mòn điện hoá sắt**",
    "*Chuẩn bị:*",
    "Hoá chất: đinh sắt mới$^{(1)}$, nước.",
    "Dụng cụ: ống nghiệm (hoặc cốc thuỷ tinh), giá ống nghiệm.",
    "*Tiến hành:*",
    "– Cho đinh sắt vào ống nghiệm. Thêm tiếp khoảng 3 mL nước.",
    "– Để ống nghiệm trong không khí khoảng 3 ngày.",
    "*Thực hiện yêu cầu sau:*",
    "Hãy nêu hiện tượng quan sát được ở ống nghiệm và giải thích.",
    "[Hình 22.2. Thí nghiệm sự ăn mòn điện hoá sắt: Ống nghiệm chứa nước và đinh sắt bị gỉ ở phần tiếp xúc với nước và không khí]",
    "",
    "Sự ăn mòn điện hoá kim loại xảy ra khi có sự tạo thành pin điện.",
    "*Ví dụ:* Sự ăn mòn điện hoá kim loại trong không khí ẩm.",
    "Trong không khí ẩm, trên bề mặt của gang thép luôn có một lớp nước mỏng đã hoà tan khí oxygen và carbon dioxide tạo thành dung dịch chất điện li. Sắt và các thành phần khác (chủ yếu là carbon) cùng tiếp xúc với dung dịch đó, tạo nên vô số pin điện hoá rất nhỏ mà anode là sắt và cathode là carbon.",
    "[Hình 22.3. Sự ăn mòn điện hoá sắt: Vật bằng gang có cực âm (Fe) bị oxi hoá thành Fe2+, cực dương (C) nhận electron khử O2 thành OH-. Fe2+ và OH- tạo thành gỉ sắt trong lớp dung dịch điện li.]",
    "Ở anode, xảy ra quá trình oxi hoá:",
    "Fe(s) $\\longrightarrow$ Fe$^{2+}$(aq) + 2e",
    "Ở cathode, xảy ra quá trình khử:",
    "$\\frac{1}{2}$O$_2$(g) + H$_2$O(l) + 2e $\\longrightarrow$ 2OH$^-$(aq)",
    "Fe$^{2+}$ tiếp tục bị oxi hoá bởi oxygen không khí, tạo thành gỉ sắt có thành phần chính là Fe$_2$O$_3$$\\cdot$nH$_2$O.",
    "*Điều kiện của quá trình ăn mòn điện hoá:* Hai kim loại khác nhau hoặc một kim loại và một phi kim; Chúng tiếp xúc với nhau trực tiếp hoặc gián tiếp thông qua dây dẫn điện và cùng tiếp xúc với một dung dịch chất điện li.",
    "",
    "$^{(1)}$ Đinh sắt được làm từ hợp kim của sắt với carbon và một số nguyên tố khác.",
    "",
    "103",
    "❓ 1. Một số hiện tượng ăn mòn thép trong đời sống:",
    "a) Thép bị gỉ trong không khí khô.",
    "b) Thép bị gỉ trong không khí ẩm.",
    "c) Thép bị gỉ khi tiếp xúc với nước biển.",
    "Hãy cho biết các hiện tượng ăn mòn thép trên thuộc loại ăn mòn hoá học hay ăn mòn điện hoá. Giải thích.",
    "",
    "## II CHỐNG ĂN MÒN KIM LOẠI",
    "Có hai phương pháp phổ biến bảo vệ kim loại khỏi bị ăn mòn là phương pháp điện hoá và phương pháp phủ bề mặt.",
    "",
    "### 1. Phương pháp điện hoá",
    "**Bảo vệ sắt bằng phương pháp điện hoá**",
    "*Chuẩn bị:*",
    "Hoá chất: hai đinh sắt mới, dây kẽm, nước máy hoặc nước tự nhiên.",
    "Dụng cụ: hai ống nghiệm đánh số (1) và (2).",
    "*Tiến hành:*",
    "– Cho đinh sắt thứ nhất vào ống nghiệm (1).",
    "– Quấn dây kẽm quanh đinh sắt thứ hai, sau đó cho vào ống nghiệm (2).",
    "– Thêm nước máy vào mỗi ống nghiệm đến ngập đinh sắt.",
    "– Để các ống nghiệm trong không khí khoảng 3 ngày.",
    "*Quan sát hiện tượng xảy ra và thực hiện yêu cầu sau:*",
    "Đinh sắt có gắn kẽm bị ăn mòn nhanh hơn hay chậm hơn đinh sắt không gắn kẽm? Giải thích.",
    "",
    "💡 **EM CÓ BIẾT**",
    "Ăn mòn kim loại xảy ra phổ biến và gây thiệt hại kinh tế, nhất là ăn mòn thép tạo gỉ sắt. Gỉ sắt làm thay đổi tính chất cơ học vốn có của thép, gây mất an toàn. Khoảng 25% thép được sản xuất tại Mỹ chỉ để thay thế thép bị ăn mòn khi sử dụng.",
    "",
    "Nguyên tắc bảo vệ kim loại khỏi bị ăn mòn bằng phương pháp điện hoá là gắn lên kim loại cần bảo vệ một kim loại khác hoạt động hoá học mạnh hơn. Khi đó, kim loại hoạt động hoá học mạnh hơn bị ăn mòn.",
    "*Ví dụ:* để bảo vệ tàu biển làm bằng thép, người ta gắn các tấm kẽm lên vỏ tàu (phần chìm dưới nước).",
    "",
    "❓ 2. Các thiết bị bằng thép (đường ống, bể chứa, giàn khoan dầu, tàu thuỷ,...) trong môi trường biển hoặc dưới lòng đất ẩm ướt thường được bảo vệ bằng phương pháp điện hoá. Kim loại được sử dụng để bảo vệ thép thường là kẽm (Hình 22.4). Hãy cho biết kim loại nào bị ăn mòn. Giải thích.",
    "[Hình 22.4. Bảo vệ thép bằng phương pháp điện hoá: Thanh Zn gắn trên chân vịt tàu biển]",
    "",
    "104",
    "### 2. Phương pháp phủ bề mặt",
    "Phương pháp phủ bề mặt ngăn kim loại tiếp xúc trực tiếp với môi trường bằng cách:",
    "• Phủ kim loại cần bảo vệ bằng các kim loại khác không bị gỉ như Au, Sn, Zn.",
    "*Ví dụ:* vỏ đồng hồ mạ vàng; tráng thiếc lên lá thép (sắt tây); tráng kẽm lên lá thép (tôn).",
    "• Phủ kim loại cần bảo vệ bằng các hợp chất vô cơ hoặc hữu cơ như sơn, dầu, mỡ,...",
    "*Ví dụ:* Các đồ vật bằng sắt thường được sơn hoặc tra dầu, mỡ.",
    "[Hình 22.5. Bảo vệ kim loại bằng phương pháp phủ bề mặt: a) phủ sơn, b) mạ vàng]",
    "",
    "❓ 3. Hãy tìm hiểu và cho biết cách bảo vệ các đồ vật làm từ gang, thép bằng phương pháp phủ bề mặt.",
    "",
    "**EM ĐÃ HỌC**",
    "- Ăn mòn kim loại là sự phá huỷ kim loại hoặc hợp kim dưới tác dụng của các chất trong môi trường.",
    "- Hai loại ăn mòn kim loại:",
    "– Ăn mòn hoá học: xảy ra phản ứng oxi hoá – khử trực tiếp giữa kim loại với các chất oxi hoá có trong môi trường.",
    "– Ăn mòn điện hoá: xảy ra khi có sự tạo thành pin điện.",
    "- Hai phương pháp bảo vệ kim loại:",
    "– Phương pháp điện hoá: gắn kim loại cần bảo vệ với kim loại hoạt động hoá học mạnh hơn.",
    "– Phương pháp phủ bề mặt: phủ lên bề mặt kim loại cần bảo vệ một kim loại khác không bị gỉ hoặc các chất như sơn, dầu, mỡ,...",
    "",
    "**EM CÓ THỂ**",
    "- Giải thích được một số hiện tượng ăn mòn kim loại trong tự nhiên.",
    "- Bảo vệ các đồ dùng làm bằng kim loại trong gia đình khỏi bị ăn mòn kim loại.",
    "",
    "105"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C6' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B23', 'Ôn tập chương 6', 108, 6, $JSON$
{
  "content": [
    "# BÀI 23 ÔN TẬP CHƯƠNG 6",
    "",
    "## I HỆ THỐNG HOÁ KIẾN THỨC",
    "**1. Cấu tạo và liên kết trong tinh thể kim loại**",
    "• Nguyên tử kim loại thường có từ 1 đến 3 electron lớp ngoài cùng.",
    "• Trong tinh thể kim loại, các ion dương chiếm những nút của mạng tinh thể, các electron hoá trị chuyển động tự do trong toàn bộ mạng tinh thể.",
    "• Trong tinh thể kim loại, liên kết kim loại được hình thành do lực hút tĩnh điện giữa các electron tự do với các ion dương kim loại ở các nút mạng.",
    "**2. Tính chất vật lí và tính chất hoá học của kim loại**",
    "• Kim loại là chất rắn (trừ Hg), có tính dẻo (dễ rèn, dễ dát mỏng và dễ kéo sợi), tính dẫn điện, dẫn nhiệt và có ánh kim.",
    "• Kim loại có tính khử: Tác dụng với phi kim, nước, dung dịch acid, dung dịch muối.",
    "**3. Kim loại trong tự nhiên và phương pháp tách kim loại**",
    "• Trong tự nhiên, hầu hết các kim loại tồn tại ở dạng hợp chất, chỉ một vài kim loại kém hoạt động như vàng, bạc, platinum,... được tìm thấy dưới dạng đơn chất.",
    "• Nguyên tắc điều chế kim loại là khử ion kim loại thành nguyên tử:",
    "M$^{n+}$ + ne $\\longrightarrow$ M",
    "– Những kim loại hoạt động hoá học mạnh được điều chế bằng phương pháp điện phân nóng chảy các hợp chất của chúng.",
    "– Những kim loại hoạt động trung bình, yếu thường được điều chế bằng phương pháp nhiệt luyện hoặc điện phân dung dịch muối của chúng hoặc thuỷ luyện.",
    "**4. Hợp kim**",
    "• Vật liệu kim loại chứa một kim loại cơ bản và một số kim loại khác hoặc phi kim.",
    "• Tính chất hoá học của hợp kim tương tự tính chất hoá học của kim loại thành phần.",
    "• Tính chất vật lí thường khác nhiều so với tính chất của các kim loại thành phần như độ cứng của hợp kim thường lớn hơn độ cứng của kim loại thành phần và độ dẻo thì kém hơn. Nhiệt độ nóng chảy của hợp kim tuỳ thuộc vào thành phần và cấu tạo tinh thể của hợp kim.",
    "**5. Sự ăn mòn kim loại**",
    "• Ăn mòn kim loại là sự phá huỷ kim loại hoặc hợp kim dưới tác dụng của các chất trong môi trường.",
    "• Hai dạng ăn mòn kim loại là ăn mòn hoá học và ăn mòn điện hoá.",
    "• Hai phương pháp bảo vệ kim loại là phương pháp điện hoá và phương pháp phủ bề mặt.",
    "",
    "106",
    "## II LUYỆN TẬP",
    "**Câu 1.** Cho các phát biểu sau:",
    "(1) Nguyên tử của các nguyên tố kim loại thường có từ 1 electron đến 3 electron ở lớp electron ngoài cùng.",
    "(2) Tất cả các nguyên tố nhóm B đều là kim loại.",
    "(3) Ở trạng thái rắn, đơn chất kim loại có cấu tạo tinh thể.",
    "(4) Các kim loại đều có bán kính nguyên tử nhỏ hơn bán kính nguyên tử các phi kim thuộc cùng một chu kì.",
    "(5) Liên kết kim loại được hình thành do lực hút tĩnh điện giữa các electron tự do với các ion dương kim loại trong mạng tinh thể kim loại.",
    "Các phát biểu đúng là",
    "A. (1), (2), (3), (5).",
    "B. (1), (2), (3), (4), (5).",
    "C. (1), (2), (3).",
    "D. (1), (3), (5).",
    "",
    "**Câu 2.** Kim loại nào sau đây **không** phản ứng với dung dịch HCl loãng?",
    "A. Đồng.          B. Calcium.          C. Magnesium.          D. Kẽm.",
    "",
    "**Câu 3.** Trường hợp nào sau đây có xảy ra phản ứng hoá học?",
    "A. Nhúng thanh Cu vào dung dịch NaCl.",
    "B. Nhúng thanh Al vào dung dịch MgCl$_2$.",
    "C. Nhúng thanh Ag vào dung dịch FeSO$_4$.",
    "D. Nhúng thanh Cu vào dung dịch AgNO$_3$.",
    "",
    "**Câu 4.** Cho các phản ứng sau:",
    "Fe + CuSO$_4$ $\\longrightarrow$ FeSO$_4$ + Cu",
    "Cu + Fe$_2$(SO$_4$)$_3$ $\\longrightarrow$ 2FeSO$_4$ + CuSO$_4$",
    "Sự sắp xếp các cặp oxi hoá – khử nào sau đây đúng theo thứ tự tăng dần thế điện cực chuẩn?",
    "A. Fe$^{2+}$/Fe; Cu$^{2+}$/Cu; Fe$^{3+}$/Fe$^{2+}$.",
    "B. Fe$^{3+}$/Fe$^{2+}$; Cu$^{2+}$/Cu; Fe$^{2+}$/Fe.",
    "C. Cu$^{2+}$/Cu; Fe$^{2+}$/Fe; Fe$^{3+}$/Fe$^{2+}$.",
    "D. Cu$^{2+}$/Cu; Fe$^{3+}$/Fe$^{2+}$; Fe$^{2+}$/Fe.",
    "",
    "**Câu 5.** Nhúng hai thanh kẽm giống nhau vào hai cốc (1) và (2) chứa 5 mL dung dịch HCl 1 M. Nhỏ thêm vào cốc (2) vài giọt dung dịch CuSO$_4$ 1 M. Hãy cho biết trong mỗi trường hợp trên xảy ra dạng ăn mòn nào? Giải thích.",
    "",
    "107"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C7' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B24', 'Nguyên tố nhóm IA', 110, 1, $JSON$
{
  "content": [
    "# CHƯƠNG 7",
    "# NGUYÊN TỐ NHÓM IA VÀ NHÓM IIA",
    "",
    "# BÀI 24 NGUYÊN TỐ NHÓM IA",
    "",
    "**MỤC TIÊU**",
    "– Nêu được trạng thái tự nhiên của nguyên tố nhóm IA.",
    "– Nêu được xu hướng biến đổi nhiệt độ nóng chảy, nhiệt độ sôi của kim loại nhóm IA.",
    "– Giải thích được nguyên nhân khối lượng riêng nhỏ và độ cứng thấp của kim loại nhóm IA.",
    "– Giải thích được nguyên nhân kim loại nhóm IA có tính khử mạnh hơn so với các nhóm kim loại khác.",
    "– Thông qua mô tả thí nghiệm (hoặc quan sát qua video), nêu được mức độ phản ứng tăng dần từ lithium, sodium, potassium khi chúng phản ứng với nước, chlorine và oxygen.",
    "– Trình bày được cách bảo quản kim loại nhóm IA.",
    "– Giải thích được trạng thái tồn tại của nguyên tố nhóm IA trong tự nhiên.",
    "– Nêu được khả năng tan trong nước của các hợp chất nhóm IA.",
    "– Thực hiện được thí nghiệm (hoặc qua quan sát video thí nghiệm) phân biệt các ion Li$^+$, Na$^+$, K$^+$ bằng màu ngọn lửa.",
    "– Tìm hiểu và trình bày được ứng dụng của sodium chloride.",
    "– Trình bày được quá trình điện phân dung dịch sodium chloride và các sản phẩm cơ bản của công nghiệp chlorine – kiềm.",
    "– Giải thích được các ứng dụng phổ biến của sodium hydrogencarbonate (natri hiđrocacbonat), sodium carbonate (natri cacbonat) và phương pháp Solvay sản xuất soda.",
    "",
    "❓ Các kim loại nhóm IA (nhóm kim loại kiềm) và hợp chất của chúng có nhiều ứng dụng như: sản xuất pin lithium, nước Javel, phân kali, tế bào quang điện, đồng hồ nguyên tử,...",
    "Vậy, đơn chất nhóm IA có đặc điểm gì nổi bật về tính chất vật lí và tính chất hoá học? Các hợp chất nhóm IA quan trọng như xút, soda được sản xuất trong công nghiệp như thế nào?",
    "",
    "[Hình: Các nguyên tố nhóm IA và ứng dụng của chúng: Li (Pin lithium), Na (Baking soda), K (Thuốc nổ), Rb (Pháo bông), Cs (Đồng hồ nguyên tử), Fr (Chất phóng xạ)]",
    "Hình 24.1. Một số ứng dụng của nguyên tố kim loại nhóm IA",
    "",
    "108",
    "## I ĐƠN CHẤT NHÓM IA",
    "### 1. Đặc điểm chung",
    "🖐 Một số đại lượng đặc trưng của các nguyên tố nhóm IA được trình bày trong Bảng 24.1.",
    "**Bảng 24.1.** Một số đại lượng đặc trưng của các nguyên tố nhóm IA",
    "",
