    "| --- | --- | --- | --- | --- | --- |",
    "| Li | 3 | Lithium | [He]2s$^1$ | 152 | –3,040 |",
    "| Na | 11 | Sodium | [Ne]3s$^1$ | 186 | –2,713 |",
    "| K | 19 | Potassium | [Ar]4s$^1$ | 227 | –2,924 |",
