    "2. Cho biết: xu hướng biến đổi tính khử từ Li đến Cs; số oxi hoá đặc trưng của nguyên tử kim loại nhóm IA.",
    "",
    "Nguyên tố nhóm IA là những nguyên tố s, chỉ có 1 electron hoá trị ở phân lớp ns$^1$ và đứng đầu mỗi chu kì tương ứng. Kim loại nhóm IA có thế điện cực chuẩn E$^\\circ_{\\text{M}^+/\\text{M}}$ rất nhỏ nên dễ tách electron hoá trị ra khỏi nguyên tử. Vì vậy, trong các phản ứng hoá học, chúng dễ nhường 1 electron, thể hiện tính khử rất mạnh:",
    "M $\\longrightarrow$ M$^+$ + 1e",
    "Trong hợp chất, nguyên tử kim loại nhóm IA chỉ thể hiện số oxi hoá +1.",
    "",
    "### 2. Trạng thái tự nhiên",
    "Trong tự nhiên, các nguyên tố nhóm IA chỉ tồn tại ở dạng hợp chất (chủ yếu là dạng muối). Sodium và potassium là hai nguyên tố phổ biến trong vỏ Trái Đất, có nhiều trong nước biển, mỏ muối, quặng halite (NaCl), quặng sylvinite (NaCl$\\cdot$KCl).",
    "",
    "❓ 1. Tại sao các nguyên tố kim loại nhóm IA không tồn tại ở dạng đơn chất trong tự nhiên?",
    "",
    "$^{(1)}$ Nguồn: Silberberg, M. S. 2007. *Principles of General Chemistry*, McGraw-Hill Higher Education.",
    "$^{(2)}$ Nguồn: Dean, J. A. 1999. *Lange's handbook of chemistry*, United States of America, McGraw-Hill, Inc.",
    "",
    "109",
