    "Trong y học: nước muối sinh lí, chất điện giải,...",
    "Trong công nghiệp hoá chất: sản xuất chlorine – kiềm, nước Javel, soda,...",
    "• *Quá trình điện phân dung dịch NaCl:*",
    "Trong công nghiệp chlorine – kiềm, quá trình điện phân dung dịch NaCl bão hoà có màng ngăn điện cực được ứng dụng để sản xuất xút công nghiệp (NaOH), khí chlorine (Cl$_2$). Điện phân dung dịch NaCl bão hoà không có màng ngăn điện cực được ứng dụng để sản xuất nước Javel (chứa NaClO).",
    "",
    "🖐 Viết các quá trình oxi hoá, quá trình khử xảy ra ở mỗi điện cực và viết phương trình hoá học của quá trình điện phân dung dịch NaCl có màng ngăn.",
    "",
    "💡 **EM CÓ BIẾT**",
    "Trong công nghiệp, quá trình điện phân dung dịch NaCl thường được tiến hành trong thùng điện phân có anode bằng than chì và cathode bằng sắt. Giữa hai điện cực có màng ngăn xốp để ngăn không cho Cl$_2$ tiếp xúc với OH$^-$.",
    "[Hình 24.4. Sơ đồ quá trình điện phân dung dịch NaCl trong công nghiệp chlorine – kiềm: Dung dịch NaCl (~300 g/L) vào, điện phân sinh ra Cl2 ở Anode, H2 và NaOH (~32%) ở Cathode. Dung dịch NaCl loãng (~200 g/L) thoát ra.]",
    "(Nguồn: Millet, P. 2013. 9 - Chlor-alkali technology: fundamentals, processes and materials for diaphragms and membranes. In: Basile, A. (ed.) *Handbook of Membrane Reactors - Reactor Types and Industrial Applications*. Elsevier Science.)",
    "",
    "113",
    "**b) Sodium hydrogencarbonate, sodium carbonate**",
    "• *Ứng dụng:*",
