    "## I ĐƠN CHẤT NHÓM IIA",
    "### 1. Đặc điểm chung",
    "🖐 Một số đại lượng đặc trưng của các nguyên tố nhóm IIA được trình bày trong Bảng 25.1.",
    "**Bảng 25.1.** Một số đại lượng đặc trưng các nguyên tố nhóm IIA",
    "",
