    "– Nhỏ từ từ từng giọt dung dịch Na$_2$SO$_4$ 1 M vào mỗi ống nghiệm (1) và ống nghiệm (2); nhỏ vài giọt dung dịch BaCl$_2$ 1 M vào ống nghiệm (3).",
    "*Chú ý:* BaCl$_2$ độc, cần tuân thủ quy tắc an toàn trong phòng thí nghiệm.",
    "*Quan sát hiện tượng xảy ra và thực hiện các yêu cầu sau:*",
    "1. Viết phương trình hoá học của các phản ứng xảy ra trong mỗi ống nghiệm.",
    "2. Ở ống nghiệm (1) và (2), ống nào tạo kết tủa nhanh hơn? Nhiều hơn?",
    "**2. Nhận biết ion CO$_3^{2-}$**",
    "– Cho khoảng 1 mL dung dịch Na$_2$CO$_3$ 1 M vào ống nghiệm, thêm tiếp khoảng 1 mL dung dịch CaCl$_2$ 1 M, lắc đều.",
    "– Thêm tiếp 2 mL dung dịch HCl 2 M vào ống nghiệm, lắc đều.",
    "*Quan sát hiện tượng xảy ra và thực hiện các yêu cầu sau:*",
    "1. Viết phương trình hoá học của các phản ứng xảy ra trong thí nghiệm.",
    "2. Nêu các hiện tượng xảy ra và giải thích.",
    "",
    "$^{(1)}$ Nguồn: Dean, J. A. 1999. *Lange's handbook of chemistry*, United States of America, McGraw-Hill, Inc.",
    "",
    "122",
    "### 3. Ứng dụng",
    "Các nguyên, vật liệu chứa calcium như đá vôi, vôi, nước vôi, thạch cao, quặng apatite, quặng fluorite,... có nhiều ứng dụng trong đời sống và sản xuất (Bảng 25.5).",
    "**Bảng 25.5** Một số ứng dụng của các nguyên, vật liệu chứa calcium",
    "",
    "| Nguyên, vật liệu | Ứng dụng |",
    "| --- | --- |",
    "| Đá vôi | Sản xuất vôi sống, xi măng, vật liệu xây dựng,... |",
    "| Vôi sống | Khử chua; sát trùng, tẩy uế; hút ẩm trong công nghiệp;... |",
    "| Vôi, nước vôi | Khử chua, làm mềm nước cứng,... |",
    "| Thạch cao | Vật liệu xây dựng, phấn viết bảng,... |",
    "| Apatite | Sản xuất phân lân (superphosphate, nung chảy,...),... |",
    "",
    "Một số hợp chất của calcium còn có vai trò quan trọng đối với cơ thể con người như: calcium phosphate, hydroxylapatite tham gia cấu tạo xương và răng.",
    "",
    "❓ 3. Tìm hiểu và trình bày vai trò của calcium trong cơ thể con người mà em biết.",
    "",
    "## III NƯỚC CỨNG",
    "### 1. Khái niệm, phân loại",
    "**a) Khái niệm**",
    "Nước trong tự nhiên như nước mặt (nước sông, suối, ao, hồ,...) và nước ngầm thường hoà tan muối của nhiều ion kim loại như Ca$^{2+}$, Mg$^{2+}$,...",
    "*Nước chứa nhiều ion Ca$^{2+}$ và Mg$^{2+}$ được gọi là nước cứng.* Nước chứa ít hoặc không chứa các ion Ca$^{2+}$ và Mg$^{2+}$ được gọi là nước mềm.",
    "",
    "**b) Phân loại**",
    "Căn cứ vào thành phần của anion gốc acid tạo muối với ion Ca$^{2+}$ và Mg$^{2+}$, nước cứng được phân làm ba loại: nước có tính cứng tạm thời, nước có tính cứng vĩnh cửu và nước có tính cứng toàn phần.",
    "[Hình 25.3. Phân loại tính cứng của nước: Tính cứng tạm thời (Anion HCO3-), Tính cứng vĩnh cửu (Anion SO4 2-, Cl-), Tính cứng toàn phần (Anion HCO3-, SO4 2-, Cl-)]",
    "",
    "Nước tự nhiên thường có tính cứng toàn phần, tức là có cả tính cứng tạm thời và tính cứng vĩnh cửu.",
    "",
    "123",
    "❓ 4.",
    "a) Khi đun nóng nước có tính cứng tạm thời, phần lớn các ion Ca$^{2+}$ và Mg$^{2+}$ được tách ra khỏi nước ở dạng kết tủa muối carbonate.",
    "Viết phương trình hoá học của các phản ứng xảy ra.",
    "b) Giải thích sự tạo thành cặn đá vôi trong phích nước, ấm đun nước.",
    "",
    "### 2. Tác hại của nước cứng",
    "Nước cứng ảnh hưởng nhiều đến các hoạt động trong sản xuất và đời sống.",
    "Một số ví dụ về tác hại của nước cứng:",
    "– Nồi hơi dễ bị đóng cặn gây tốn nhiên liệu và không an toàn.",
    "– Đường ống dẫn nước dễ bị đóng cặn làm giảm lưu lượng nước hoặc tắc đường ống.",
    "– Giặt bằng xà phòng sẽ tạo ra muối ít tan bám vào quần áo, xà phòng tạo ít bọt, tốn xà phòng, quần áo mau hỏng.",
    "– Nấu ăn bằng nước cứng làm cho thực phẩm lâu chín, giảm mùi vị.",
    "",
    "❓ 5. Trình bày về tác hại của nước cứng với sản xuất và đời sống.",
    "",
    "### 3. Làm mềm nước cứng",
    "Nguyên tắc làm mềm nước cứng là làm giảm nồng độ các cation Ca$^{2+}$ và Mg$^{2+}$ trong nước cứng. Có hai phương pháp làm mềm nước cứng phổ biến: chuyển các cation Ca$^{2+}$ và Mg$^{2+}$ vào hợp chất không tan (phương pháp kết tủa) và thay thế những cation này bằng các cation khác (phương pháp trao đổi ion).",
    "**a) Phương pháp kết tủa**",
    "",
    "🖐 1. Đề xuất hai cách (không dùng hoá chất và có dùng hoá chất) để làm mềm mẫu nước có tính cứng tạm thời chứa Ca(HCO$_3$)$_2$ và Mg(HCO$_3$)$_2$. Viết phương trình hoá học để minh hoạ.",
    "2. Đề xuất hai hoá chất có thể dùng để làm mềm mẫu nước có tính cứng vĩnh cửu chứa CaCl$_2$ và MgSO$_4$. Giải thích.",
    "",
    "**b) Phương pháp trao đổi ion**",
    "Vật liệu có khả năng trao đổi một số ion trong thành phần cấu tạo của chúng với các ion có trong dung dịch gọi là vật liệu trao đổi ion.",
    "Các vật liệu trao đổi ion thường dùng trong xử lí nước cứng là các vật liệu polymer có khả năng trao đổi cation, thường gọi là nhựa cationite. Khi nước cứng chảy qua cột chứa nhựa trao đổi ion, các ion Ca$^{2+}$, Mg$^{2+}$ trong nước sẽ bị hấp thụ và ở lại trên cột, đồng thời các cation như Na$^+$, H$^+$ được giải phóng từ cột vào nước.",
    "",
    "124",
    "**EM ĐÃ HỌC**",
    "- Các kim loại nhóm IIA có tính khử mạnh nên chúng chỉ tồn tại trong tự nhiên dưới dạng hợp chất.",
    "- Kim loại nhóm IIA (từ Mg đến Ba) tác dụng với nước theo mức độ phản ứng tăng dần.",
    "- Khi đốt nóng, các kim loại nhóm IIA và hợp chất của chúng có màu ngọn lửa đặc trưng: Ca$^{2+}$ màu đỏ cam, Sr$^{2+}$ màu đỏ son, Ba$^{2+}$ màu lục.",
    "- Độ bền nhiệt của muối carbonate và nitrate của kim loại nhóm IIA có xu hướng tăng dần từ Be đến Ba.",
    "- Các hợp chất của kim loại nhóm IIA có nhiều ứng dụng trong đời sống, sản xuất và có vai trò quan trọng đối với cơ thể người.",
    "- Kiểm tra sự có mặt của ion Ca$^{2+}$, Ba$^{2+}$, SO$_4^{2-}$, CO$_3^{2-}$ trong dung dịch thông qua phản ứng trao đổi để tạo thành kết tủa CaSO$_4$, BaSO$_4$ và CaCO$_3$.",
    "- Nước cứng là nước chứa nhiều ion Ca$^{2+}$ và Mg$^{2+}$. Nguyên tắc làm mềm nước cứng là làm giảm nồng độ các cation Ca$^{2+}$ và Mg$^{2+}$ trong nước cứng.",
    "",
    "**EM CÓ THỂ**",
    "Hiểu được tác hại của nước cứng với sản xuất, có thể đề xuất được hoá chất phù hợp để làm mềm nước cứng.",
    "",
    "125"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C7' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B26', 'Ôn tập chương 7', 128, 3, $JSON$
{
  "content": [
    "# BÀI 26 ÔN TẬP CHƯƠNG 7",
    "",
    "## I HỆ THỐNG HOÁ KIẾN THỨC",
    "",
    "| | ĐƠN CHẤT NHÓM IA | ĐƠN CHẤT NHÓM IIA |",
    "| --- | --- | --- |",
    "| **Tính chất vật lí** | – Nhiệt độ nóng chảy thấp, nhiệt độ sôi thấp và có xu hướng giảm dần từ Li đến Cs.<br>– Khối lượng riêng nhỏ và độ cứng thấp. | Kim loại nhóm IIA đều là kim loại nhẹ, khó nóng chảy hơn kim loại nhóm IA. |",
    "| **Tính chất hoá học** | – Kim loại nhóm IA có thế điện cực chuẩn E$^\\circ_{\\text{M}^+/\\text{M}}$ rất nhỏ nên thể hiện tính khử mạnh nhất trong các nhóm kim loại.<br>– Mức độ phản ứng tăng dần từ Li đến Cs khi tác dụng với H$_2$O, O$_2$, Cl$_2$. | – Kim loại nhóm IIA có thế điện cực chuẩn E$^\\circ_{\\text{M}^{2+}/\\text{M}}$ nhỏ nên thể hiện tính khử mạnh (chỉ sau kim loại nhóm IA) và tăng dần từ Be đến Ba.<br>– Ở điều kiện thường, kim loại nhóm IIA dễ bị oxi hoá bởi không khí (trừ Be). Khi đốt nóng trong oxygen, beryllium cháy chậm, các kim loại khác cháy mạnh.<br>– Ở điều kiện thường, Be không phản ứng với nước, Mg phản ứng chậm, các kim loại khác phản ứng mạnh với nước. |",
    "",
    "| | HỢP CHẤT CỦA KIM LOẠI NHÓM IA | HỢP CHẤT CỦA KIM LOẠI NHÓM IIA |",
    "| --- | --- | --- |",
    "| **Đặc điểm chung** | – Tính tan trong nước: hydroxide và đa số các muối đều dễ tan.<br>– Màu ngọn lửa ion kim loại: Li$^+$ màu đỏ tía, Na$^+$ màu vàng, K$^+$ màu tím nhạt. | – Tính tan trong nước: các muối carbonate và sulfate đều ít tan hoặc không tan (trừ MgSO$_4$); các muối nitrate đều dễ tan; các hydroxide của strontium và barium dễ tan, của calcium ít tan, của magnesium không tan.<br>– Màu ngọn lửa kim loại, ion kim loại: Ca$^{2+}$ màu đỏ cam, Sr$^{2+}$ màu đỏ son, Ba$^{2+}$ màu lục. |",
    "| **Một số hợp chất quan trọng** | – NaCl có nhiều ứng dụng trong đời sống, sản xuất, y học. Phản ứng điện phân dung dịch NaCl bão hoà là cơ sở của công nghiệp chlorine – kiềm.<br>– NaHCO$_3$ và Na$_2$CO$_3$ được sản xuất theo phương pháp Solvay từ các nguyên liệu chính là đá vôi, muối ăn, ammonia và nước. | – Muối carbonate tác dụng được với acid, với nước có hoà tan carbon dioxide.<br>– Độ bền nhiệt của muối carbonate và nitrate có xu hướng tăng dần từ Be đến Ba. |",
    "| **Nước cứng** | | – Nước cứng là nước có chứa nhiều ion Ca$^{2+}$ và Mg$^{2+}$.<br>– Làm mềm nước cứng bằng phương pháp kết tủa hoặc phương pháp trao đổi ion. |",
    "",
    "126",
    "## II LUYỆN TẬP",
    "**Câu 1.** Khi so sánh kim loại nhóm IA với các kim loại khác trong cùng chu kì, nhận định nào sau đây **không** đúng?",
    "A. Có tính khử mạnh nhất.",
    "B. Có thế điện cực chuẩn âm nhất.",
    "C. Có bán kính nguyên tử lớn nhất.",
    "D. Có nhiều electron hoá trị nhất.",
    "",
    "**Câu 2.** Trong quá trình Solvay, ở giai đoạn tạo thành NaHCO$_3$ tồn tại cân bằng sau:",
    "NaCl + NH$_3$ + CO$_2$ + H$_2$O $\\rightleftharpoons$ NaHCO$_3$ + NH$_4$Cl",
    "Khi làm lạnh dung dịch trên, muối bị tách ra khỏi dung dịch là",
    "A. NaHCO$_3$.          B. NH$_4$Cl.          C. NaCl.          D. NH$_4$HCO$_3$.",
    "",
    "**Câu 3.** Độ tan trong dãy muối sulfate từ MgSO$_4$ đến BaSO$_4$ biến đổi như thế nào?",
    "A. Tăng dần.          B. Giảm dần.          C. Không có quy luật.          D. Không đổi.",
    "",
    "**Câu 4.** Độ bền nhiệt trong dãy muối carbonate từ MgCO$_3$ đến BaCO$_3$ biến đổi như thế nào?",
    "A. Tăng dần.          B. Giảm dần.          C. Không có quy luật.          D. Không đổi.",
    "",
    "**Câu 5.** Nguyên tắc làm mềm nước cứng là làm giảm nồng độ của các ion nào sau đây?",
    "A. Ion sulfate và ion chloride.",
    "B. Ion nitrate và ion hydrogencarbonate.",
    "C. Ion magnesium và ion calcium.",
    "D. Ion sodium và ion potassium.",
    "",
    "**Câu 6.** Trình bày cách phân biệt dung dịch CaCl$_2$ và dung dịch BaCl$_2$ bằng màu ngọn lửa và bằng phương pháp hoá học.",
    "",
    "**Câu 7.** Trong công nghiệp, quá trình nung vôi được thực hiện theo phản ứng:",
    "CaCO$_3$(s) $\\longrightarrow$ CaO(s) + CO$_2$(g)        $\\Delta_r\\text{H}^\\circ_{298}$ = 179,2 kJ",
    "a) Cho biết quá trình nung vôi là quá trình toả nhiệt hay quá trình thu nhiệt.",
    "b) Trình bày một số ứng dụng chính của sản phẩm nung vôi.",
    "c) Nêu một số tác hại của quá trình nung vôi thủ công đối với môi trường.",
    "",
    "Đoàn văn Doanh - THPT Nam Trực - Nam Định",
    "",
    "127"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C8' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B27', 'Đại cương về kim loại chuyển tiếp dãy thứ nhất', 130, 1, $JSON$
{
  "content": [
    "# CHƯƠNG 8",
    "# SƠ LƯỢC VỀ DÃY KIM LOẠI CHUYỂN TIẾP THỨ NHẤT VÀ PHỨC CHẤT",
    "",
    "# BÀI 27 ĐẠI CƯƠNG VỀ KIM LOẠI CHUYỂN TIẾP DÃY THỨ NHẤT",
    "",
    "**MỤC TIÊU**",
    "– Nêu được đặc điểm cấu hình electron của nguyên tử kim loại chuyển tiếp dãy thứ nhất (từ Sc đến Cu).",
    "– Trình bày được một số tính chất vật lí của kim loại chuyển tiếp (nhiệt độ nóng chảy, khối lượng riêng, độ dẫn điện và dẫn nhiệt, độ cứng) và ứng dụng của kim loại chuyển tiếp từ các tính chất đó.",
    "Nêu được sự khác biệt các số liệu về nhiệt độ nóng chảy, khối lượng riêng, độ dẫn điện, độ cứng,... giữa một số kim loại chuyển tiếp so với kim loại họ s.",
    "– Nêu được xu hướng có nhiều số oxi hoá của nguyên tố chuyển tiếp.",
    "– Nêu được các trạng thái oxi hoá phổ biến, cấu hình electron, đặc tính có màu của một số ion kim loại chuyển tiếp dãy thứ nhất.",
    "– Thực hiện được (hoặc quan sát video) thí nghiệm xác định hàm lượng muối Fe(II) bằng dung dịch thuốc tím.",
    "– Thực hiện được thí nghiệm kiểm tra sự có mặt từng ion riêng biệt: Cu$^{2+}$, Fe$^{3+}$.",
    "",
    "❓ Các kim loại chuyển tiếp dãy thứ nhất và hợp kim của chúng được sử dụng phổ biến làm vật liệu chế tạo dụng cụ, thiết bị, máy móc, phương tiện giao thông,...",
    "Các ứng dụng này dựa trên tính chất nào của kim loại chuyển tiếp dãy thứ nhất?",
    "",
    "[Hình: Các kim loại chuyển tiếp dãy thứ nhất và ứng dụng: Sc (Dụng cụ thể thao), Ti (Vật liệu hàng không), V (Công cụ cầm tay), Cr (Khung xe), Mn (Vỏ hộp), Fe (Tàu thuỷ), Co (Nam châm), Ni (Tiền xu), Cu (Dây dẫn điện)]",
    "Hình 27.1. Một số ứng dụng của kim loại chuyển tiếp dãy thứ nhất",
    "",
    "128",
    "## I ĐƠN CHẤT KIM LOẠI CHUYỂN TIẾP DÃY THỨ NHẤT",
    "### 1. Đặc điểm cấu tạo nguyên tử",
    "🖐 Cấu hình electron của nguyên tử các nguyên tố kim loại chuyển tiếp dãy thứ nhất được cho trong bảng sau:",
    "**Bảng 27.1.** Cấu hình electron của nguyên tử các nguyên tố kim loại chuyển tiếp dãy thứ nhất",
    "",
    "| Số hiệu nguyên tử | Nguyên tử | Cấu hình electron | Số hiệu nguyên tử | Nguyên tử | Cấu hình electron |",
    "| --- | --- | --- | --- | --- | --- |",
    "| 21 | Sc | [Ar]3d$^1$4s$^2$ | 26 | Fe | [Ar]3d$^6$4s$^2$ |",
