INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C8' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B28', 'Sơ lược về phức chất', 136, 2, $JSON$
{
  "content": [
    "# BÀI 28 SƠ LƯỢC VỀ PHỨC CHẤT",
    "",
    "**MỤC TIÊU**",
    "– Nêu được nguyên tử trung tâm; phối tử; liên kết cho – nhận giữa nguyên tử trung tâm và phối tử trong phức chất.",
    "– Nêu được một số dạng hình học của phức chất (tứ diện, vuông phẳng, bát diện).",
    "– Trình bày được sự hình thành phức chất aqua của ion kim loại chuyển tiếp và H$_2$O trong dung dịch nước.",
    "",
    "❓ Phức chất có trong một số thành phần quan trọng của sinh vật như hemoglobin, chất diệp lục,... Một số phức chất có vai trò quan trọng trong điều trị bệnh ung thư. Vậy, phức chất là gì? Phức chất được hình thành như thế nào?",
    "[Hình 28.1. Phức chất có trong hemoglobin (a) và diệp lục (b)]",
    "",
    "## I MỘT SỐ KHÁI NIỆM CƠ BẢN VỀ PHỨC CHẤT",
    "*Phức chất* là hợp chất có chứa *nguyên tử trung tâm* (thường được kí hiệu là M) và các *phối tử* (thường được kí hiệu là L). Trong đó, nguyên tử trung tâm là cation kim loại hoặc nguyên tử kim loại liên kết với các phối tử. Phối tử là anion hoặc phân tử. Phức chất có thể mang điện tích hoặc không mang điện tích.",
    "Trong công thức phức chất, nguyên tử trung tâm M và các phối tử L thường được đặt trong móc vuông.",
    "*Ví dụ 1:* Phức chất [Co(NH$_3$)$_6$]$^{3+}$ có điện tích là +3, nguyên tử trung tâm là Co$^{3+}$ và phối tử là NH$_3$.",
    "*Ví dụ 2:* Phức chất [Zn(OH)$_4$]$^{2-}$ có điện tích là –2, nguyên tử trung tâm là Zn$^{2+}$ và phối tử là OH$^-$.",
    "*Ví dụ 3:* Phức chất [Fe(CO)$_5$] không mang điện tích, nguyên tử trung tâm là Fe và phối tử là CO.",
    "",
    "❓ 1. Cho các phức chất sau: [Cu(H$_2$O)$_6$]$^{2+}$, [CoF$_6$]$^{3-}$, [Ni(CO)$_4$], [PtCl$_2$(NH$_3$)$_2$].",
    "a) Hãy chỉ ra phối tử và nguyên tử trung tâm trong mỗi phức chất trên.",
    "b) Hãy cho biết số lượng phối tử có trong mỗi phức chất trên.",
    "c) Hãy cho biết điện tích của mỗi phức chất trên.",
    "",
    "134",
    "💡 **EM CÓ BIẾT**",
    "**Công thức phức chất**",
    "Trong công thức của phức chất, cầu nội được đặt trong móc vuông. Cầu nội của phức chất gồm nguyên tử trung tâm M và các phối tử L. Khi cầu nội mang điện tích, phức chất thường chứa ion cầu ngoại, các ion này trung hoà điện tích với ion cầu nội.",
    "*Ví dụ:* [Ag(NH$_3$)$_2$]OH (Cầu nội: [Ag(NH$_3$)$_2$]$^+$; Cầu ngoại: OH$^-$)",
    "Trong nhiều trường hợp, người ta chỉ quan tâm đến cầu nội do nó quyết định tính chất của phức chất.",
    "*Ví dụ:* Trong dung dịch thuốc thử Tollens, phức [Ag(NH$_3$)$_2$]OH phân li như sau:",
    "[Ag(NH$_3$)$_2$]OH $\\longrightarrow$ [Ag(NH$_3$)$_2$]$^+$ + OH$^-$",
    "Cation cầu nội [Ag(NH$_3$)$_2$]$^+$ quyết định tính chất của thuốc thử Tollens.",
    "",
    "## II MỘT SỐ DẠNG HÌNH HỌC CỦA PHỨC CHẤT",
    "Trong phức chất [ML$_n$] (điện tích đã được lược bỏ), các phối tử L sắp xếp một cách xác định xung quanh nguyên tử trung tâm M tạo ra các dạng hình học khác nhau, phổ biến là dạng tứ diện, vuông phẳng và bát diện (Bảng 28.1).",
    "**Bảng 28.1.** Một số dạng hình học phổ biến của phức chất [ML$_n$]",
    "",
    "| Dạng tứ diện | Dạng vuông phẳng | Dạng bát diện |",
    "| --- | --- | --- |",
    "| [Hình: Dạng tứ diện với 1 nguyên tử trung tâm M ở giữa và 4 phối tử L ở 4 đỉnh của tứ diện] | [Hình: Dạng vuông phẳng với 1 nguyên tử trung tâm M ở giữa và 4 phối tử L ở 4 góc của hình vuông] | [Hình: Dạng bát diện với 1 nguyên tử trung tâm M ở giữa và 6 phối tử L ở 6 đỉnh của bát diện] |",
    "",
    "*Chú ý:* Nét màu xanh nối các phối tử L trong phức chất để chỉ rõ dạng hình học của phức chất, nét màu trắng chỉ liên kết giữa M và L.",
    "",
    "🖐 1. Hãy xác định số lượng phối tử L trong phân tử hoặc ion phức chất ứng với mỗi dạng hình học ở Bảng 28.1.",
    "2. Hãy dự đoán dạng hình học của phức chất [Cu(H$_2$O)$_6$]$^{2+}$.",
    "",
    "135",
    "## III LIÊN KẾT TRONG PHỨC CHẤT",
    "### 1. Liên kết giữa nguyên tử trung tâm và phối tử",
    "Liên kết hoá học giữa nguyên tử trung tâm M và phối tử L trong phức chất là liên kết cho – nhận, được hình thành nhờ sự cho cặp electron chưa liên kết của phối tử vào orbital trống của nguyên tử trung tâm.",
    "*Ví dụ 1:* Liên kết trong phức chất [Co(NH$_3$)$_6$]$^{3+}$ được hình thành do phối tử NH$_3$ cho cặp electron chưa liên kết vào AO trống của nguyên tử trung tâm Co$^{3+}$.",
    "*Ví dụ 2:* Liên kết trong phức chất [Zn(OH)$_4$]$^{2-}$ được hình thành do phối tử OH$^-$ cho cặp electron chưa liên kết vào AO trống của nguyên tử trung tâm Zn$^{2+}$.",
    "",
    "❓ 2. Cho các phức chất sau: [Ag(NH$_3$)$_2$]$^+$ và [CoF$_6$]$^{3-}$.",
    "Hãy chỉ ra nguyên tử trung tâm, phối tử và giải thích sự hình thành liên kết trong mỗi phức chất trên.",
    "",
    "### 2. Sự hình thành phức chất aqua của một số ion kim loại chuyển tiếp",
    "[Hình 28.2. CuSO4 khan: Bột màu trắng trong lọ]",
    "[Hình 28.3. Dung dịch CuSO4: Dung dịch màu xanh trong cốc thuỷ tinh]",
    "Muối CuSO$_4$ khan màu trắng (Hình 28.2) khi tan vào nước tạo thành dung dịch có màu xanh (Hình 28.3) vì tạo thành phức chất [Cu(H$_2$O)$_6$]$^{2+}$.",
    "Trong dung dịch, các ion kim loại chuyển tiếp M$^{n+}$ thường nhận cặp electron chưa liên kết của H$_2$O tạo thành liên kết cộng hoá trị kiểu cho – nhận, hình thành phức chất aqua. Hầu hết các phức chất aqua có dạng hình học bát diện ([M(H$_2$O)$_6$]$^{n+}$). Chẳng hạn trong dung dịch nước, ion Fe$^{2+}$ tạo phức chất [Fe(H$_2$O)$_6$]$^{2+}$, ion Co$^{3+}$ tạo phức chất [Co(H$_2$O)$_6$]$^{3+}$.",
    "",
    "❓ 3. Phức chất aqua của Ni$^{2+}$ và Zn$^{2+}$ đều có dạng hình học bát diện.",
    "a) Viết công thức hoá học của mỗi phức chất aqua trên.",
    "b) Mô tả sự hình thành liên kết giữa phối tử và nguyên tử trung tâm trong mỗi phức chất trên.",
    "",
    "136",
    "**EM ĐÃ HỌC**",
    "- Phức chất là hợp chất có chứa nguyên tử trung tâm và các phối tử, nó có thể mang điện tích hoặc không mang điện tích.",
    "- Các phối tử sắp xếp một cách xác định xung quanh nguyên tử trung tâm, tạo ra các dạng hình học khác nhau. Các dạng hình học phổ biến là tứ diện, vuông phẳng và bát diện.",
    "- Phối tử liên kết với nguyên tử trung tâm bằng liên kết cho – nhận.",
    "- Trong dung dịch, các ion kim loại chuyển tiếp M$^{n+}$ thường tạo phức chất aqua, hầu hết có dạng hình học bát diện.",
    "",
    "**EM CÓ THỂ**",
    "- Chỉ ra được nguyên tử trung tâm, phối tử, dạng hình học của một số phức chất.",
    "- Giải thích được sự hình thành phức chất aqua của ion kim loại chuyển tiếp và H$_2$O trong dung dịch nước.",
    "",
    "137"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C8' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B29', 'Một số tính chất và ứng dụng của phức chất', 140, 3, $JSON$
{
  "content": [
    "# BÀI 29 MỘT SỐ TÍNH CHẤT VÀ ỨNG DỤNG CỦA PHỨC CHẤT",
    "",
    "**MỤC TIÊU**",
    "– Trình bày được một số dấu hiệu của phản ứng tạo phức chất trong dung dịch (đổi màu, kết tủa, hoà tan,...).",
    "– Thực hiện được một số thí nghiệm tạo phức chất của một ion kim loại chuyển tiếp trong dung dịch với một số phối tử đơn giản khác nhau (ví dụ: sự tạo phức của ion Cu$^{2+}$ trong dung dịch với NH$_3$, OH$^-$, Cl$^-$,...).",
    "– Mô tả được phản ứng thay thế phối tử của phức chất bởi một số phối tử đơn giản trong dung dịch nước.",
    "– Nêu được một số ứng dụng của phức chất.",
    "",
    "❓ Thuốc thử Tollens là phức chất được sử dụng rộng rãi trong hoá học hữu cơ. Thuốc thử Tollens thường được dùng để phân biệt aldehyde với ketone. Vậy, phức chất có tính chất và ứng dụng trong thực tiễn như thế nào?",
    "",
    "## I MỘT SỐ DẤU HIỆU CỦA PHẢN ỨNG TẠO PHỨC CHẤT VÀ PHẢN ỨNG THẾ PHỐI TỬ CỦA PHỨC CHẤT TRONG DUNG DỊCH",
    "### 1. Một số dấu hiệu của phản ứng tạo phức chất trong dung dịch",
    "Phản ứng tạo phức chất trong dung dịch có thể được nhận biết dựa vào một số dấu hiệu như: xuất hiện kết tủa; hoà tan kết tủa; thay đổi màu sắc.",
    "*Ví dụ 1:* Nhỏ vài giọt dung dịch NaOH vào ống nghiệm chứa dung dịch AlCl$_3$, thấy xuất hiện kết tủa, chứng tỏ phức chất [Al(OH)$_3$(H$_2$O)$_3$] đã được tạo thành.",
    "*Ví dụ 2:* Nhỏ vài giọt dung dịch NaCl vào ống nghiệm chứa dung dịch AgNO$_3$, thu được kết tủa trắng AgCl. Tiếp tục nhỏ vào ống nghiệm dung dịch NH$_3$ đến dư thấy kết tủa tan, chứng tỏ phức chất [Ag(NH$_3$)$_2$]$^+$ đã được tạo thành.",
    "*Ví dụ 3:* Nhỏ vài giọt dung dịch HCl đặc vào ống nghiệm chứa dung dịch CuSO$_4$ loãng thấy dung dịch từ màu xanh chuyển sang màu vàng, chứng tỏ phức chất [CuCl$_4$]$^{2-}$ đã được tạo thành.",
    "*Ví dụ 4:* Nhỏ vài giọt dung dịch NH$_3$ vào dung dịch CuSO$_4$ loãng thấy xuất hiện kết tủa màu xanh nhạt, chứng tỏ phức chất [Cu(OH)$_2$(H$_2$O)$_4$] đã được tạo thành. Tiếp tục nhỏ vào ống nghiệm dung dịch NH$_3$ đến dư thấy kết tủa tan, đồng thời dung dịch chuyển sang màu xanh lam, chứng tỏ phức chất [Cu(NH$_3$)$_4$(H$_2$O)$_2$]$^{2+}$ đã được tạo thành.",
    "",
    "[Hình: Ống nghiệm chứa [Cu(H2O)6]2+ màu xanh -> Ống nghiệm chứa [CuCl4]2- màu vàng]",
    "[Hình: Ống nghiệm chứa [Cu(OH)2(H2O)4](s) màu xanh nhạt -> Ống nghiệm chứa [Cu(NH3)4(H2O)2]2+ màu xanh lam]",
    "",
    "138",
    "💡 **EM CÓ BIẾT**",
    "• Các phức chất mang điện tích như [Co(NH$_3$)$_6$]$^{3+}$, [Zn(OH)$_4$]$^{2-}$ thường tan tốt trong nước, còn các phức chất không mang điện (phức chất trung hoà) như [Fe(CO)$_5$], [PtCl$_2$(NH$_3$)$_2$] thường ít tan trong nước.",
    "• Màu sắc đặc trưng của một số dung dịch phức chất kim loại chuyển tiếp dãy thứ nhất được cho trong bảng sau:",
    "",
    "| Phức chất | Màu sắc | | Phức chất | Màu sắc | |",
    "| --- | --- | --- | --- | --- | --- |",
    "| [Cr(H$_2$O)$_6$]$^{3+}$ | Xanh tím | [Hình ống nghiệm chứa dung dịch xanh tím] | [Cr(OH)$_6$]$^{3-}$ | Xanh rêu | [Hình ống nghiệm chứa dung dịch xanh rêu] |",
    "| [Fe(H$_2$O)$_6$]$^{2+}$ | Lục nhạt | [Hình ống nghiệm chứa dung dịch lục nhạt] | [Fe(H$_2$O)$_6$]$^{3+}$ | Vàng nhạt | [Hình ống nghiệm chứa dung dịch vàng nhạt] |",
    "| [Co(H$_2$O)$_6$]$^{2+}$ | Hồng đỏ | [Hình ống nghiệm chứa dung dịch hồng đỏ] | [Co(NH$_3$)$_6$]$^{2+}$ | Vàng nâu | [Hình ống nghiệm chứa dung dịch vàng nâu] |",
    "",
    "❓ 1. Có 3 lọ hoá chất, mỗi lọ đựng dung dịch của một trong các phức chất sau: [Ag(NH$_3$)$_2$]$^+$, [Cu(H$_2$O)$_6$]$^{2+}$, [Cu(NH$_3$)$_4$(H$_2$O)$_2$]$^{2+}$. Hãy nhận biết phức chất có trong mỗi lọ dựa vào màu sắc đặc trưng của chúng.",
    "2. CuSO$_4$ khan màu trắng, khi hoà tan trong nước, các phân tử nước liên kết với ion Cu$^{2+}$ tạo phức chất aqua [Cu(H$_2$O)$_6$]$^{2+}$. Hãy cho biết dấu hiệu nào chứng tỏ phức chất aqua đã tạo thành.",
    "",
    "### 2. Sự tạo thành phức chất của ion kim loại chuyển tiếp và phản ứng thế phối tử của phức chất trong dung dịch",
    "**a) Sự tạo thành phức chất của Cu$^{2+}$ trong dung dịch**",
    "**Thí nghiệm: Sự tạo thành phức chất của Cu$^{2+}$**",
    "*Chuẩn bị:*",
    "Hoá chất: dung dịch CuSO$_4$ 5%, dung dịch NaOH 10%, dung dịch NH$_3$ 10%, dung dịch HCl đặc.",
    "Dụng cụ: ống nghiệm.",
    "*Tiến hành:*",
    "– Cho khoảng 1 mL dung dịch CuSO$_4$ 5% vào ống nghiệm (1). Cho tiếp 3 giọt dung dịch NaOH 10% vào ống nghiệm, lắc đều. Nhỏ từ từ dung dịch NH$_3$ 10% vào ống nghiệm, vừa nhỏ vừa lắc đều đến khi kết tủa tan hoàn toàn.",
    "– Cho khoảng 1 mL dung dịch CuSO$_4$ 5% vào ống nghiệm (2). Nhỏ từ từ dung dịch HCl đặc vào ống nghiệm, vừa nhỏ vừa lắc đều đến khi dung dịch chuyển màu hoàn toàn.",
    "*Quan sát hiện tượng và viết phương trình hoá học của các phản ứng xảy ra.*",
    "",
    "139",
    "**b) Phản ứng thế phối tử của phức chất trong dung dịch**",
    "Các phối tử trong phức chất có thể bị thế bởi các phối tử khác. Quá trình xảy ra sự thế phối tử này bởi phối tử khác được gọi là phản ứng thế phối tử của phức chất. Quá trình này xảy ra thuận lợi khi phức chất mới được hình thành bền hơn phức chất ban đầu.",
    "*Ví dụ 1:*",
    "[PtCl$_4$]$^{2-}$(aq) + NH$_3$(aq) $\\longrightarrow$ [PtCl$_3$(NH$_3$)]$^-$(aq) + Cl$^-$(aq)",
    "Ở phản ứng này, một phối tử Cl$^-$ trong phức chất [PtCl$_4$]$^{2-}$ bị thế bởi một phối tử NH$_3$, tạo ra phức chất [PtCl$_3$(NH$_3$)]$^-$.",
    "*Ví dụ 2:*",
    "[Fe(H$_2$O)$_6$]$^{2+}$(aq) + 6CN$^-$(aq) $\\longrightarrow$ [Fe(CN)$_6$]$^{4-}$(aq) + 6H$_2$O(l)",
    "Ở phản ứng này, các phối tử H$_2$O trong phức chất [Fe(H$_2$O)$_6$]$^{2+}$ bị thế bởi phối tử CN$^-$, tạo ra phức chất [Fe(CN)$_6$]$^{4-}$.",
    "*Ví dụ 3:*",
    "[Cu(H$_2$O)$_6$]$^{2+}$(aq) + 4Cl$^-$(aq) $\\longrightarrow$ [CuCl$_4$]$^{2-}$(aq) + 6H$_2$O(l)",
    "Ở phản ứng này, các phối tử H$_2$O trong phức chất [Cu(H$_2$O)$_6$]$^{2+}$ bị thế bởi phối tử Cl$^-$, tạo ra phức chất [CuCl$_4$]$^{2-}$.",
    "",
    "❓ 3.",
    "a) Trong dung dịch, ion Co$^{2+}$ tạo thành phức chất aqua có dạng hình học bát diện.",
    "Hãy viết công thức hoá học của phức chất.",
    "b) Khi cho một lượng dư NH$_3$ vào dung dịch muối CoCl$_2$, thấy màu sắc của dung dịch bị thay đổi. Hiện tượng xảy ra là do toàn bộ các phối tử H$_2$O trong phức chất aqua bị thay thế bởi các phối tử NH$_3$, tạo thành phức chất mới có dạng bát diện. Viết phương trình hoá học của phản ứng thế phối tử đã xảy ra.",
    "",
    "## II MỘT SỐ ỨNG DỤNG CỦA PHỨC CHẤT",
    "– Trong y học, nhiều phức chất có khả năng chữa trị hoặc kiểm soát bệnh.",
    "*Ví dụ:* Phức chất được dùng làm thuốc chữa bệnh ung thư với tên gọi thương phẩm là cisplatin có cấu tạo như sau:",
    "[Hình: Cấu tạo của cisplatin: Pt ở trung tâm, liên kết với 2 nguyên tử Cl và 2 nhóm NH3 tạo thành dạng vuông phẳng]",
    "cisplatin",
    "– Trong công nghiệp hoá chất, nhiều hợp chất hoá học được điều chế khi có mặt chất xúc tác là phức chất.",
    "",
    "140",
    "*Ví dụ:* Phản ứng ghép mạch carbon sử dụng xúc tác là phức chất [Pd(P(C$_6$H$_5$)$_3$)$_4$].",
    "– Trong hoá học, phức chất được dùng để nhận biết và xác định hàm lượng các ion kim loại chuyển tiếp trong dung dịch.",
    "*Ví dụ:* Phức chất [Ag(NH$_3$)$_2$]$^+$ để phân biệt aldehyde với ketone.",
    "",
    "❓ 4. Hãy cho biết dạng hình học, nguyên tử trung tâm và các phối tử có trong phức chất cisplatin.",
    "",
    "💡 **EM CÓ BIẾT**",
    "**Vai trò của phức chất trong các hệ sinh học**",
    "Ba phức chất sinh học (còn gọi là các phân tử sinh học chứa kim loại) phổ biến và thiết yếu đối với cuộc sống là:",
    "– Phức chất của Mg$^{2+}$ cấu tạo nên chlorophyll hay chất diệp lục, có vai trò quan trọng trong quá trình quang hợp của cây xanh, thực vật có màu xanh là do có chứa chlorophyll.",
    "– Phức chất của Fe$^{2+}$ cấu tạo nên nhân heme, thành phần của hemoglobin. Hemoglobin còn gọi là huyết sắc tố, viết tắt là Hb hay Hgb, là thành phần cấu tạo nên hồng cầu của máu. Trong hệ thống tim mạch, heme có vai trò chính trong việc vận chuyển và tích luỹ oxygen trong cơ thể. Hồng cầu có màu đỏ là do có chứa nhân hem.",
    "– Phức chất của Co$^{3+}$ cấu tạo nên vitamin B$_{12}$, có vai trò thiết yếu trong việc hình thành tế bào hồng cầu, chuyển hoá tế bào, chức năng thần kinh và sản xuất DNA.",
    "",
    "**EM ĐÃ HỌC**",
    "- Dấu hiệu của phản ứng tạo thành phức chất trong dung dịch: xuất hiện kết tủa; hoà tan kết tủa; thay đổi màu sắc.",
    "- Phản ứng thế phối tử trong phức chất.",
    "- Phức chất có nhiều ứng dụng trong y học, trong công nghiệp tổng hợp hoá chất và trong hoá học.",
    "",
    "**EM CÓ THỂ**",
    "- Nhận biết một số phức chất thông dụng dựa vào màu sắc đặc trưng của phức chất.",
    "- Nêu được một số ứng dụng của phức chất trong cuộc sống.",
    "",
    "[Hình: Logo LUYỆN THI HÀ THÀNH 0979.817.885, xung quanh có chữ TOÁN - LÝ - HÓA - SINH - VĂN - ANH]",
    "",
    "141"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'C8' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_12')), 'B30', 'Ôn tập chương 8', 144, 4, $JSON$
{
  "content": [
    "# BÀI 30 ÔN TẬP CHƯƠNG 8",
    "",
    "## I HỆ THỐNG HOÁ KIẾN THỨC",
    "**1. Đại cương về kim loại chuyển tiếp dãy thứ nhất**",
    "- Kim loại chuyển tiếp dãy thứ nhất gồm 9 nguyên tố thuộc chu kì 4, từ Sc (Z = 21) đến Cu (Z = 29).",
    "- Cấu hình electron của nguyên tử các kim loại chuyển tiếp có dạng 3d$^{1-10}$4s$^{1-2}$.",
    "- Kim loại chuyển tiếp dãy thứ nhất có nhiệt độ nóng chảy cao, thường có độ cứng lớn, khá nặng, dẫn điện và dẫn nhiệt tốt, có nhiều ứng dụng trong thực tiễn.",
    "- Các nguyên tố chuyển tiếp có xu hướng thể hiện nhiều trạng thái oxi hoá. Các ion kim loại chuyển tiếp thường có màu sắc phong phú.",
    "- Sự có mặt của ion Cu$^{2+}$ hoặc ion Fe$^{3+}$ trong dung dịch được nhận biết bằng phản ứng tạo thành kết tủa màu xanh nhạt của Cu(OH)$_2$ hoặc nâu đỏ của Fe(OH)$_3$.",
    "**2. Sơ lược về phức chất**",
    "- Phức chất là hợp chất có chứa nguyên tử trung tâm và các phối tử.",
    "- Phức chất có dạng hình học phổ biến là tứ diện, vuông phẳng và bát diện.",
    "- Trong phức chất, phối tử cho cặp electron chưa liên kết vào orbital trống của nguyên tử trung tâm tạo liên kết cho – nhận.",
    "- Sự tạo thành phức chất trong dung dịch có thể được nhận ra nhờ dấu hiệu xuất hiện kết tủa, hoà tan kết tủa, thay đổi màu sắc.",
    "- Trong dung dịch, các ion kim loại chuyển tiếp đều tạo phức chất aqua, hầu hết có dạng hình học bát diện.",
    "- Các phối tử trong phức chất có thể bị thay thế một phần hoặc thay thế hoàn toàn bởi các phối tử khác.",
    "- Phức chất có ứng dụng trong y học, công nghiệp hoá chất.",
